(window.GIM_TS=window.GIM_TS||{})["Zevachim.9"]={"from":216,"a":[["\u0003במנא\u0004 \u0005[בכלי]\u0006 אחד, ובזאת נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003קביעות מנא\u0004 \u0005[כלי]\u0006 \u0003מילתא היא\u0004 \u0005[דבר\u0006 קובע \u0005הוא],\u0006 ונקבע בכך כל מה שבכלי להקטרה, ולכן אם הקטיר רק כזית מחוץ לעזרה אין זו נחשבת הקטרת חוץ. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 קביעות בכלי \u0003לאו מילתא היא\u0004 \u0005[לא דבר\u0006 קובע \u0005הוא],\u0006 והואיל ולא נקבע כל מה שבכלי להקטרה, ולכן גם אם הקטיר רק כזית מחוץ לעזרה יהיה חייב על כך.","ועוד בענין זה \u0003אמר רבא: השתא\u0004 \u0005[עכשיו]\u0006 שלמדנו שיטות אלו של ר' אליעזר וחכמים בענין קביעות כלי, יש לומר כי \u0003למאן דאמר קביעותא דמנא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר קביעות כלי]\u0006 \u0003ולא כלום הוא\u0004 \u0005[היא],\u0006 כלומר, לדעת חכמים, אם \u0003קבע\u0004 בכלי \u0003ששה\u0004 לוגים יין \u0003ל\u0004נסכים הבאים עם קרבן ה\u0003פר\u0004 (\"חצי ההין\", במדבר כח, יד), \u0003ומשך מהן ארבעה\u0004 לוגים \u0003והקריבן בחוץ\u0004 — \u0003חייב,\u0004 לפי \u0003שראויין ל\u0004נסכי קרבן ה\u0003איל\u0004 (שהם \"שלישית ההין\" האמורה בתורה שם).","וכמו כן, אם \u0003קבע\u0004 בכלי \u0003ארבעה\u0004 לוגים יין, שהוא שיעור הראוי \u0003לאיל, ומשך מהן שלשה\u0004 לוגים \u0003והקריבן בחוץ\u0004 — \u0003חייב,\u0004 לפי \u0003שראויין ל\u0004נסכי קרבן ה\u0003כבש\u0004 (שהם \"רביעית ההין\" האמורים בתורה שם).","ואולם אם \u0003חסרו כל שהוא\u0004 משיעור זה של שלושה לוגים, \u0003והקריבן בחוץ\u0004 — \u0003פטור.\u0004 ושבים לדון בקושייתו של רבא על שיטת אביי: כיצד ניתן לומר לדעת חכמים שהקטרת פנים נלמדת מהקטרת חוץ? והרי אף עבודת חוץ מעבודת חוץ (ניסוך מהקטרה) אין הם למדים!","\u0003רב אשי אמר:\u0004 אין בכך קושי, \u0003ניסוך מהקטרה לא ילפי רבנן\u0004 \u0005[אין חכמים למדים],\u0006","\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שזו עבודה שב\u0003חוץ\u0004 וזו עבודה שב\u0003חוץ,\u0004 משום שמעבודה אחת לעבודה אחרת \u0003לא ילפי\u0004 \u0005[אין למדים].\u0006 אבל \u0003הקטרה מהקטרה,\u0004 שהן אותה עבודה, \u0003ילפי\u0004 \u0005[למדים\u0006 חכמים\u0005]\u0006 זו מזו \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שהרי זה לימוד של עבודה ב\u0003חוץ מ\u0004עבודה של \u0003פנים.\u0004","שנינו במשנתנו: \u0003כולן שחסרו\u0004 כלשהו והקריבו בחוץ — פטור, הואיל ובפנים אינם ראויים להקרבה. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003חסרון\u0004 שאירע ב\u0003חוץ,\u0004 האם \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003חסרון\u0004 לענין זה שיהיה פטור על העלאתו בחוץ, \u0003או לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003חסרון?\u0004","וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 הרי ממילא \u0003כיון דנפק, איפסלו להו\u0004 \u0005[כיון שיצא\u0006 מהמקדש, \u0005נפסלו להם\u0006 בעצם היציאה\u0005],\u0006 ולמרות זאת חייבה התורה על העלתם בחוץ, אם כן, \u0003מה לי\u0004 אם הוא \u0003חסר, מה לי\u0004 אם הוא \u0003יתר.\u0004 \u0003או דילמא\u0004 \u0005[שמא]\u0006 מן הצד האחר יש להבחין ולומר: דווקא קרבן \u0003יוצא דאיתיה בעיניה\u0004 \u0005[ש\u0006עדיין \u0005ישנו בעינו,\u0006 בממשו הראשון\u0005]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 חייבים על העלאתו בחוץ, אבל במקרה \u0003דליתיה בעיניה\u0004 \u0005[ש\u0006שוב \u0005אינו בעינו],\u0006 שנחסר — \u0003לא\u0004 יהיו חייבים על העלאתו בחוץ?","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו, ממה ששנינו במשנתנו: \u0003ר' אליעזר פוטר\u0004 על הקרבת כזית מן הקומץ וכו' משום העלאת חוץ \u0003עד שיקריב את כולן,\u0004 הרי מפורש בדבריו שאינו חייב אם הקריב חסר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי:\u0004 וכי \u0003מ\u0004דברי \u0003ר' אליעזר פשיט מר\u0004 \u0005[פותר אדוני]\u0006 את השאלה הזו? והרי השאלה הינה לשיטת חכמים, המחייבים כשהקריב כזית בחוץ, גם אם לא הקריב את כולו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרבה בר רב חנן: \u0003בפירוש שמיע לי מיניה דרב\u0004 \u0005[שמעתי ממנו, מרבי]:\u0006 \u0003עד כאן לא\u0004 שמענו ש\u0003פליגי רבנן עליה\u0004 \u0005[\u0006ש\u0005נחלקו חכמים עליו]\u0006 על \u0003ר' אליעזר,\u0004 \u0003אלא\u0004 במקרה \u0003דאיתיה בעיניה\u0004 \u0005[ש\u0006הקומץ \u0005ישנו בעינו,\u0006 בשלימותו\u0005],\u0006 ומקטיר כזית ממנו. \u0003אבל בחסרון,\u0004 שנחסר מן הקומץ והקריבו בחוץ, \u0003מודו ליה\u0004 \u0005[מודים לו]\u0006 שאינו חייב. \u0003לאו\u0004 \u0005[האם לא]\u0006 שמדובר שם גם ש\u0003חסר בחוץ?\u0004 ודוחים: \u0003לא,\u0004 מדובר ש\u0003חסר בפנים,\u0004 ואין להביא מכאן ראיה לשאלתנו זו.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003וכולן שחסרו והקריבן בחוץ\u0004 — \u0003פטור. לאו\u0004 \u0005[האם לא]\u0006 מדובר גם כש\u0003חסר בחוץ?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003חסר בפנים,\u0004 ואין מכאן ראיה.","עוד שנינו במשנתנו כי \u0003המקריב\u0004 בחוץ \u0003קדשים\u0004 הנאכלים, שבשרם אינו ראוי להקרבה, יחד עם אימוריהם, הריהו חייב על הקרבת האימורים. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא חייב על כך? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 פה \u0003חציצה\u0004 שחוצץ הבשר בין האימורים לבין המזבח, ואין זו איפוא הקרבה בפנים, ומדוע חייב עליה בחוץ!","\u0003אמר שמואל:\u0004 מדובר פה \u0003כשהפכן\u0004 הנה והנה את הבשר והאימורים, וכך נגעו האימורים במערכה.","\u0003ור' יוחנן אמר:\u0004 יש להסביר את המשנה כך: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר במשנתנו \u0003שלא הפכן,\u0004 ולא נגעו האיברים במזבח. \u0003והא מני\u0004 \u0005[וזו\u0006 משנתנו כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 בדין המקריב בחוץ: \u0003אפילו העלו על הסלע\u0004 ולא על מזבח — \u0003חייב.\u0004","ואילו \u0003רב אמר\u0004 הסבר אחר לשאלה זו: אין הבשר מהווה חציצה בין האימורים ולמזבח, משום שכלל הוא בהלכות חציצה ש\u0003מין במינו אינו חוצץ,\u0004 ובשר ואימורים מין אחד הם, ששניהם מגוף הבהמה.","\u0003מנחה שלא נקמצה,\u0004 שלא הרים ממנה הכהן את הקומץ, \u0003והקריבה\u0004 בלא קמיצה \u0003בחוץ\u0004 — \u0003פטור\u0004 משום העלאה בחוץ, שהרי אין המנחה ראויה להיות מוקטרת כך בפנים. אבל אם \u0003קמצה\u0004 הכהן את המנחה, \u0003ו\u0004אחר כך \u0003חזר קומצה לתוכה, והקריבו בחוץ\u0004 את כל המנחה — \u0003חייב\u0004 משום העלאת הקומץ בחוץ, שכן באופן זה כשירה המנחה בפנים.","שנינו בסוף משנתנו שאם נקמצה המנחה, וחזר הקומץ לתוכה, והקריבה כולה בחוץ — חייב משום הקרבת הקומץ. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 חייבים על כך? \u0003ליבטלי\u0004 \u0005[שיבטלו]\u0006 ה\u0003שירים\u0004 (שאר המנחה) שהם הרוב, את ה\u0003קומץ!\u0004","\u0003אמר ר' זירא: נאמרה\u0004 לשון \u0003הקטרה בקומץ\u0004 המנחה: \"והקטיר הכהן את אזכרתה המזבחה\" (ויקרא ב, ב), ו\"אזכרתה\" היא הקומץ. \u0003ונאמרה\u0004 לשון \u0003הקטרה בשירים\u0004 של המנחה: \"לא תקטירו ממנו אשה לה'\" (ויקרא ב, יא). ובאה גזירה שווה זו ללמד: \u0003מה הקטרת קומץ\u0004 — \u0003אין\u0004 בו ביטול, שאפילו היה \u0003קומץ\u0004 אחד מרובה על חבירו, אין הוא \u0003מבטל חבירו. אף\u0004 ב\u0003הקטרת שירים\u0004 — \u0003אין\u0004 ביטול, ולכן אין ה\u0003שירים מבטלין\u0004 את ה\u0003קומץ.\u0004","\u0003הקומץ והלבונה,\u0004 שלאחר הקטרת שניהם מותרת המנחה באכילה לכהנים, \u0003שהקריב\u0004 רק \u0003את אחד מהן בחוץ\u0004 — \u0003חייב,\u0004 שהרי כל אחד ואחד כשלעצמו ראוי להקטרה במקדש. \u0003ר' אליעזר פוטר\u0004 על הקטרת אחד משניהם, \u0003עד שיקריב\u0004 גם \u0003את השני,\u0004 שרק שניהם יחד מתירים את המנחה לאכילה. אם הקריב \u0003אחד\u0004 משניהם \u0003בפנים\u0004 המקדש כדינו, \u0003ואחד\u0004 הקטיר שלא כדינו \u0003בחוץ\u0004 — הרי הוא \u0003חייב\u0004 על זה שבחוץ, שהרי אם היה מקריבו בפנים היה מתיר את המנחה.","וכיוצא בזה, \u0003שני בזיכי\u0004 (כלי) ה\u0003לבונה\u0004 המונחים בצד כל אחת משתי המערכות של לחם הפנים, והם המתירים בהקטרתם את אכילת לחם הפנים לכהנים, \u0003שהקריב את אחד מהם בחוץ\u0004 — \u0003חייב, ר' אליעזר פוטר, עד שיקריב את השני.\u0004 אם הקריב בזיך לבונה \u0003אחד בפנים ו\u0004אחר כך הקריב \u0003אחד בחוץ\u0004 — \u0003חייב.\u0004","שנינו במשנתנו בדין הקומץ והלבונה, שהקטרת שניהם מתירה את המנחה באכילה לכהנים. ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]:\u0006 הקטרת ה\u0003קומץ\u0004 בלבד, \u0003מהו שיתיר\u0004 באכילה את החלק ש\u0003כנגדו בשירים,\u0004 כלומר, את מחציתם? וצדדי השאלה: האם הקטרת כל אחד משני המתירים הללו, הקומץ והלבונה, \u0003מישרא שרי\u0004 \u0005[מתירה]\u0006 מחצית מן השיריים, \u0003או\u0004 שהיא רק \u0003קלושי מיקלש\u0004 \u0005[מקלישה,\u0006 מחלישה\u0005]\u0006 את איסורם של כל השיריים, עד להיתרם ממש על ידי המתיר השני, ואולם עדיין כל השיריים עומדים באיסורם?","ומבררים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי]\u0006 נשאלה שאלה זו? \u0003אי אליבא\u0004 \u0005[אם לפי שיטתו]\u0006 של \u0003ר' מאיר\u0004 ש\u0003אמר: מפגלין בחצי מתיר\u0004 כלומר, דין פיגול יכול לחול על המנחה אפילו אם חשב מחשבת פיגול בזמן הקטרת אחד מן המתירים בלבד — לשיטה זו בוודאי כל אחד מהמתירים \u0003מישרא שרי\u0004 \u0005[מתיר\u0006 הוא\u0005],\u0006 שאם לא כן לא היה מפגל!","\u0003אי\u0004 \u0005[אם]\u0006 ר' יצחק נפחא שאל את שאלתו זו \u0003אליבא דרבנן דאמרי\u0004 \u0005[לפי שיטת חכמים שאומרים]\u0006 ש\u0003אין מפגלין בחצי מתיר,\u0004 הרי לשיטתם אין חצי מתיר כשלעצמו פועל דבר. ולענייננו יש לומר כי קומץ כשלעצמו \u0003לא מישרא שרי\u0004 \u0005[מתיר]\u0006 חלק מן המנחה, \u0003ולא מקלש קליש\u0004 \u0005[מקליש]\u0006 את איסור האכילה של המנחה!","\u0003אלא\u0004 נסביר שר' יצחק שאל \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' אליעזר\u0004 שבמשנתנו, שאינו מחייב משום הקטרת חוץ אם העלה את הקומץ לבדו — והרי \u0003ר' אליעזר\u0004 אומר כן משום שלדעתו אין זו הקטרה, ומכאן שר' אליעזר \u0003כרבנן סבירא ליה\u0004 \u0005[כחכמים\u0006 החולקים על ר' מאיר \u0005סבור הוא],\u0006 \u0003דאמר\u0004 \u0005[שאומרים]:\u0006 \u0003אין מפגלין בחצי מתיר!\u0004","\u0003אלא\u0004 יש לומר ששאלת ר' יצחק הינה \u0003אליבא דרבנן דהכא\u0004 \u0005[על פי שיטת חכמים של כאן,\u0006 שבמשנתנו\u0005],\u0006 הסוברים שחייב בחוץ על הקטרת קומץ או לבונה לחוד, ומכאן שלדעתם הקטרה זו יש בה ממש. ומעתה יש לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 היא פועלת במנחה? האם היא \u0003מישרא שרי\u0004 \u0005[מתירה]\u0006 את המחצית, \u0003או\u0004 רק \u0003קליש מקלש\u0004 \u0005[מקלישה]\u0006 את האיסור?","לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003הזורק מקצת דם\u0004 כגון שנתן מתנה אחת במקום ארבע \u0003בחוץ\u0004 —"],["\u0003חייב. ר' אלעזר אומר: אף המנסך מי החג,\u0004 מים שמנסכים על המזבח בחג הסוכות, \u0003ב\u0004תוך ה\u0003חג בחוץ\u0004 — \u0003חייב. ר' נחמיה אמר:\u0004 אף \u0003שירי הדם\u0004 שצריך לשפוך אל יסוד המזבח, \u0003שהקריבו בחוץ\u0004 — \u0003חייב.\u0004","\u0003אמר רבא: ומודה ר' אלעזר בדמים\u0004 שגם אם זרק מקצתם — חייב. ואפילו בדמים הפנימיים, שאפילו מתנה אחת מהן מעכבת.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר ור' שמעון אומרים:\u0004 אם נשפך מדם הפר או מדם השעיר של יום הכיפורים לפני שגמר הכהן הגדול את כל הזאותיו — אין הוא נזקק לחזור ולשחוט פר או שעיר ולהזות את כל ההזאות פעם נוספת, אלא \u0003ממקום שפסק\u0004 להזות, משם \u0003הוא מתחיל,\u0004 משום שכל נתינת דם בעבודות יום הכיפורים הריהי דבר בפני עצמו, ומשום כך גם חייב על כך בחוץ.","שנינו במשנתנו ש\u0003ר' אלעזר אומר: אף המנסך מי החג בחג בחוץ. אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מנחם יודפאה: ר' אלעזר בשטת ר' עקיבא רבו אמרה,\u0004 ש\u0003אמר: ניסוך המים דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, ולכן חייב אם עשאו בחוץ. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' עקיבא אומר:\u0004 נאמר בקרבנות חג הסוכות: \"מלבד עולת התמיד מנחתה \u0003ונסכיה\"\u0004 (במדבר כט, לא), הרי זו לשון רבים, ללמדנו כי \u0003בשני ניסוכים הכתוב מדבר: אחד ניסוך המים\u0004 שהוא מצווה המיוחדת לחג הסוכות, \u0003ואחד ניסוך היין\u0004 הנלווה לקרבן התמיד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: אי\u0004 \u0005[אם]\u0006 על כך מסתמך ר' אלעזר לחייב על ניסוך המים, נמצא שהכתוב מקיש את מצוות ניסוך המים למצוות ניסוך היין, ולפי זה יש לומר לשיטתו: \u0003מה להלן\u0004 בניסוך היין, שיעור המצווה הוא \u0003שלשת לוגין,\u0004 שכך הוא שיעור נסכי כבש התמיד, \u0003אף כאן\u0004 במצוות ניסוך המים, יהיה שיעורה \u0003שלשת לוגין,\u0004 בין לצאת בכך ידי חובה, ובין להתחייב על כך משום העלאה בחוץ. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אלעזר \"מי החג\" קאמר\u0004 \u0005[אומר]\u0006 שחייב על הקרבתם בחוץ, ומשמע אפילו בפחות מכך! ועוד, \u0003אי\u0004 \u0005[אם]\u0006 מכאן הוא למד, יש לומר גם: \u0003מה להלן\u0004 ניסוך היין של עולת התמיד הריהו נוהג \u0003בשאר ימות השנה, אף כאן\u0004 ניסוך המים נוהג \u0003בשאר ימות השנה,\u0004 ולא רק בחג הסוכות. ואף חייב אם עשה כן בחוץ. \u0003ו\u0004אילו \u0003ר' אלעזר \"בחג\" קאמר\u0004 \u0005[אומר]!\u0006","ואומרים: \u0003אישתמיטתיה הא דאמר\u0004 \u0005[נשמט ממנו\u0006 מריש לקיש הלכה \u0005זו שאמר]\u0006 \u0003ר' אסי,\u0004 שכן \u0003אמר ר' אסי\u0004 שכך \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' נחוניא איש בקעת בית חורתן:\u0004 דין \u0003עשר נטיעות\u0004 (עצים צעירים) בתוך שטח של בית סאה, שמותר להשקות בגללם את השדה ערב שנת השביעית, וכן דין נטילת \u0003ערבה\u0004 במקדש בחג הסוכות, \u0003ו\u0004כן דין \u0003ניסוך המים\u0004 בחג הסוכות — כל אלה הריהם \u0003הלכה למשה מסיני.\u0004","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המנסך שלשת לוגין מים בחג בחוץ\u0004 — \u0003חייב, ר' אלעזר אומר: אם מלאן לשם חג\u0004 — \u0003חייב.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 להלכה? \u0003אמר רב נחמן בר יצחק: ב\u0004שאלה האם \u0003יש שיעור במים\u0004 שצריך לנסך \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006","\u0003רב פפא אמר:\u0004"],["\u0003ב\u0004שאלה האם \u0003קרבו נסכים\u0004 של יין \u0003במדבר פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 וכאשר יבואר להלן, שמי שסבור שנסכים קרבו במדבר, הוא סבור שחייבים משום ניסוך בחוץ גם על מה שלא נתקדש בכלי שרת. וכדין ניסוך היין כך דין ניסוך המים. ולפיכך, לדעת חכמים קרבו נסכים במדבר, ולכן חייב על ניסוך המים שלא נתקדשו בכלי. ואילו ר' אלעזר סבור שלא קרבו נסכים במדבר, ולפיכך אינו חייב על ניסוך המים בחוץ אלא אם נתקדשו המים בכלי.","\u0003רבינא אמר:\u0004 בניסוך היין בחוץ חייבים לדעת הכל, גם אם לא נתקדש בכלי שרת. וכאן \u0003ב\u0004שאלה האם \u0003למדין ניסוך המים מניסוך היין פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006","ובענין ניסוך היין בחוץ \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המנסך שלשה לוגין יין בחוץ\u0004 — \u0003חייב, ר' אלעזר בר' שמעון אומר: והוא שקדשן בכלי.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 עיקר המחלוקת \u0005ביניהם]?\u0006 \u0003אמר רב אדא בר רב יצחק: בירוצי מידות איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 מה שנגדש ועולה מעל שפת כלי המידה של היין. שלדעת חכמים חייבים על ניסוכם בחוץ. ולדעת ר' אלעזר בר' שמעון, רק מה שנתקדש בתוך הכלי חייבים על ניסוכו בחוץ, ולא על הבירוצים.","ואילו \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה אמר:\u0004 בשאלה האם \u0003קרבו נסכים בבמה\u0004 (של יחיד) בזמן היתר הבמות \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת. לדעת חכמים קרבו נסכים בבמה, ובלי שנתקדשו בכלי שרת (לפי שאין כלי שרת בבמה, להלן זבחים קיג,א), ולכן חייבים על ניסוכם בחוץ בשעת איסור הבמות גם כשלא נתקדשו בכלי שרת. ולדעת ר' אלעזר בר' שמעון לא קרבו כלל נסכים בבמה. ואין לחייב, איפוא, על ניסוך בחוץ אלא באופן שהוא כשר בפנים, כשקדשו הנסכים בכלי שרת.","ומעירים: \u0003ו\u0004נחלקו ר' אלעזר בר' שמעון וחכמים \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 בריתא\u0005]:\u0006 \u0003במת יחיד אינה צריכה נסכים\u0004 עם הקרבנות, אלו \u0003דברי רבי. וחכמים אומרים: טעונה נסכים.\u0004","\u0003ו\u0004מעירים: \u0003הני תנאי כהני תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים אלו\u0006 הריהי \u0005כ\u0006מחלוקת אחרת של \u0005תנאים אלו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בתחילת פרשת הנסכים: \u0003\"כי תבאו\u0004 אל ארץ מושבותיכם\" (במדבר טו, ב), והרי זה בא \u0003להטעינה נסכים\u0004 את הקרבת הקרבנות בארץ ישראל — \u0003בבמה גדולה\u0004 של כל ישראל \u0003הכתוב מדבר,\u0004 כעין המשכן שבמדבר, שבו לא נהגו נסכים.","\u0003אתה אומר בבמה גדולה, או אינו\u0004 אלא דין זה \u0003אפילו בבמה קטנה,\u0004 שכל אחד רשאי לבנות ולהקריב עליה בשעת היתר הבמות? \u0003כשהוא אומר: \"אל ארץ מושבתיכם וגו' אשר אני נתן לכם\"\u0004 (במדבר טו, ב), \u0003הרי בבמה הנוהגת לכולכם הכתוב מדבר,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","ואילו \u0003ר' עקיבא אומר:\u0004 מה שנאמר \u0003\"כי תבאו\" להטעינה נסכים\u0004 — \u0003בבמה קטנה הכתוב מדבר.\u0004","\u0003אתה אומר לבמה קטנה, או אינו אלא לבמה גדולה?\u0004 \u0003כשהוא אומר: \"אל ארץ מושבתיכם\", הרי בבמה הנוהגת בכל מושבות הכתוב מדבר,\u0004 כלומר, בכל מקום בו אתם יושבים ורוצים להקריב קרבן.","ומעירים: \u0003כשתמצא לומר,\u0004 כשתמצה את הדברים, \u0003לדברי ר' ישמעאל\u0004 — \u0003לא קרבו נסכים במדבר\u0004 כלל, ולכן היה צריך לומר שיש חובה להקריב אותם משנכנסו לארץ. \u0003ולדברי ר' עקיבא\u0004 — \u0003קרבו נסכים במדבר\u0004 ומה שהוצרכה התורה לחייב נסכים משבאו לארץ הרי זה בבמה קטנה, שהיתה אסורה במדבר.","שנינו במשנה ש\u0003ר' נחמיה אומר: שירי הדם שהקריבן בחוץ\u0004 — \u0003חייב.\u0004","\u0003אמר ר' יוחנן, תנא\u0004 \u0005[שנה]\u0006 \u0003ר' נחמיה\u0004 במשנתנו \u0003כדברי האומר\u0004 בכלל ש\u0003שיריים מעכבין\u0004 את הכפרה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003ר' נחמיה אומר: שירי הדם שהקריבן בחוץ\u0004 — \u0003חייב. אמר לו ר' עקיבא: והלא שירי הדם שירי מצוה הם,\u0004 ואם לא זרקם לא עיכב את המצוה, ומדוע יהא חייב עליהם בחוץ! \u0003אמר לו\u0004 ר' נחמיה: \u0003איברין\u0004 של עולה \u0003ופדרין\u0004 (חלבים) \u0003יוכיחו, שהן שירי מצוה\u0004 שגם אם לא קרבו יצא ידי חובת הקרבן, \u0003ו\u0004בכל זאת \u0003המקריבן בחוץ\u0004 — \u0003חייב. אמר לו\u0004 ר' עקיבא: \u0003לא, אם אמרת באיברים ופדרים שהן תחלת עבודה,\u0004 כלומר, שהקטרתם עבודה לעצמה, ולכן חייב על כך בחוץ, \u0003תאמר בשירי הדם שאינן תחלת עבודה?\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' יוחנן, שלדעת ר' נחמיה שיריים מעכבים — \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 ר' נחמיה בתשובה: \u0003הני נמי מעכבי\u0004 \u0005[אלה גם כן\u0006 השיריים מעכבים]! ואומרים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005],\u0006 ונדחו דבריו.","\u0003ו\u0004אומרים \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר רב אדא בר אהבה:\u0004 \u0003מחלוקת\u0004 התנאים בענין שיריים האם הם מעכבים, הריהי \u0003בשיריים\u0004 של דמים \u0003הפנימיים,\u0004 של חטאות שדמן ניתן בהיכל, \u0003אבל בשיריים החיצונים,\u0004 של קרבנות שדמם ניתן על המזבח החיצון, \u0003דברי הכל לא מעכבי\u0004 \u0005[מעכבים],\u0006 צריכים לומר כך: \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' נחמיה\u0004 במשנתנו ששיירי הדם שהקריבם בחוץ חייב — הרי זה \u0003בשיריים הפנימים,\u0004 שהוא סבור כי הם מעכבים. \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שנחלק בה עם ר' עקיבא, מדובר \u0003בשיריים החיצונים.\u0004","\u0003ור' עקיבא לא ידע מאי קאמר\u0004 \u0005[לא הבין מה שאומר]\u0006 \u0003ר' נחמיה, הוא סבר\u0004 \u0005[\u0006היה \u0005סבור]\u0006 כי \u0003ר' נחמיה שיריים חיצונים אמר\u0004 שחייבים על הקרבתם בחוץ, \u0003וקא מהדר ליה\u0004 \u0005[\u0006ולכן \u0005משיב הוא לו]\u0006 ממה שאמרו ב\u0003שיריים החיצונים,\u0004 שהם שיירי מצוה ואינם מעכבים. \u0003ור' נחמיה,\u0004 אף שיכול היה לענות לו שהוא מדבר בפנימיים, \u0003לדבריו\u0004 של \u0003ר' עקיבא קאמר\u0004 \u0005[\u0006הוא \u0005אומר],\u0006 שגם אם שיירי הדם החיצונים אינם מעכבים — אין מכאן ראיה לפטור על הקרבתם בחוץ, שהרי חייבים על הקרבת איברים ופדרים, למרות שאינם מעכבים.","\u0003המולק את העוף\u0004 של קדשים \u0003בפנים\u0004 בתוך העזרה, כדינו, \u0003והעלה\u0004 אותו \u0003בחוץ\u0004 — \u0003חייב.\u0004 אבל אם \u0003מלק\u0004 אותו \u0003בחוץ והעלה בחוץ\u0004 — \u0003פטור,\u0004 מפני שמליקתו בחוץ נחשבת כהריגתו סתם, ואינו מתקבל בפנים. \u0003השוחט את העוף בפנים\u0004 העזרה \u0003והעלה\u0004 אותו \u0003בחוץ\u0004 — \u0003פטור,\u0004 שהרי עוף שנשחט ולא נמלק אינו ראוי להקרבה."],["\u0003שחט\u0004 עוף קדשים \u0003בחוץ והעלה בחוץ\u0004 — \u0003חייב.\u0004","\u0003נמצא\u0004 ש\u0003דרך הכשירו\u0004 של עוף \u0003בפנים,\u0004 כלומר, במליקה שעל ידה הוא מתחייב אם העלהו בחוץ — \u0003פטורו בחוץ,\u0004 שאם מלקו בחוץ והעלהו בחוץ — פטור. \u0003דרך הכשירו מבחוץ\u0004 בשחיטה, שאם שחט בחוץ הריהו מתחייב על העלאה בחוץ — \u0003פטורו בפנים,\u0004 שהשוחט בפנים והעלה בחוץ פטור.","\u0003ר' שמעון אומר: כל שחייבין עליו בחוץ\u0004 כששחטו וגם העלהו בחוץ — \u0003חייבין על כיוצא בו\u0004 ששחטו \u0003בפנים\u0004 \u0003שהעלה בחוץ, חוץ מן השוחט\u0004 עוף \u0003בפנים ומעלה בחוץ.\u0004","על מה ששנינו במשנתנו ששחיטה היא דרך הכשרו של עוף קדשים מבחוץ, תוהים: \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"הכשירו\"\u0004 אינו מתאים, שהרי שחיטה זו אינה מכשירה כלל עוף קדשים, אלא \u0003חיובו הוא,\u0004 כלומר, הדרך בה הוא מתחייב על העלאה בחוץ! ומשיבים: אכן \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"חיובו\".\u0004","עוד שנינו בסוף משנתנו כי \u0003ר' שמעון אומר:\u0004 כל שחייבים עליו בחוץ חייבים על כיוצא בו בפנים שהעלהו בחוץ, חוץ מן השוחט בפנים ומעלה בחוץ. ושואלים: \u0003אהיכא קאי\u0004 \u0005[היכן\u0006 ר' שמעון \u0005עומד]?\u0006 לאיזה חלק של המשנה הוא מתייחס?","\u0003אילימא ארישא קאי\u0004 \u0005[אם תאמר על ראשה הוא עומד],\u0006 שאמר התנא הראשון: \u0003המולק עוף בפנים והעלה בחוץ\u0004 — \u0003חייב, מלק בחוץ והעלה בחוץ\u0004 — \u0003פטור. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: כי היכי\u0004 \u0005[כמו]\u0006 שהנמלק ב\u0003פנים מיחייב\u0004 \u0005[מתחייב]\u0006 על העלאתו בחוץ, כך הנמלק \u0003בחוץ נמי מיחייב\u0004 \u0005[גם כן מתחייב]\u0006 על העלאתו. אם כן \u0003האי\u0004 \u0005[זה]\u0006 שהוא שונה: \u0003\"כל שחייבין עליו בחוץ\u0004 חייבים על כיוצא בו בפנים\", \u0003\"כל שחייבין עליו בפנים\u0004 חייבים על כיוצא בו בחוץ\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר להיפך: \u0003כי היכי\u0004 \u0005[כמו]\u0006 שהנמלק \u0003בחוץ לא מיחייב\u0004 \u0005[מתחייב]\u0006 על העלאתו בחוץ, כך המולק \u0003בפנים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[מתחייב]\u0006 על העלאתו. אם כן, \u0003האי\u0004 \u0005[זה]\u0006 שהוא שונה: \"כל שחייבים עליו בחוץ חייבים על כיוצא בו בפנים\", \u0003\"כל שאין חייבין עליו בחוץ\u0004 אין חייבים על כיוצא בו בפנים\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר כי ר' שמעון \u0003אסיפא קאי\u0004 \u0005[על סופה\u0006 של המשנה \u0005מתייחס]\u0006 שאמר התנא הראשון: \u0003השוחט עוף בפנים והעלה בחוץ\u0004 — \u0003פטור, שחט בחוץ והעלה בחוץ\u0004 — חייב. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: כי היכי\u0004 \u0005[כמו]\u0006 שהנשחט \u0003בפנים לא מיחייב\u0004 \u0005[מתחייב]\u0006 על העלאתו בחוץ, כך הנשחט \u0003בחוץ נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 על העלאתו. אם כן, \u0003האי\u0004 \u0005[זה]\u0006 שהוא שונה: \"כל שחייבים עליו בחוץ\", \u0003\"כל שאין חייבין\u0004 עליו בפנים\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תפרש: \u0003כי היכי\u0004 \u0005[כמו]\u0006 שעל הנשחט \u0003בחוץ מיחייב\u0004 \u0005[מתחייב],\u0006 כך על הנשחט \u0003בפנים נמי מיחייב\u0004 \u0005[גם כן מתחייב]\u0006 על העלאתו בחוץ — אולם אי אפשר לומר כן, שכן \u0003הא קתני\u0004 \u0005[הרי\u0006 הוא \u0005שונה]\u0006 במפורש: \u0003חוץ מן השוחט בפנים והמעלה בחוץ\u0004 שאינו חייב!","אלא \u0003אמר זעירי: שחיטת בהמה בלילה\u0004 בפנים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 כלומר, ר' שמעון אינו מתייחס להלכות השנויות קודם לכן במשנה, אלא להלכה אחרת ששנה התנא הראשון, ואינה שנויה לפנינו. \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]\u0006 התנא הראשון: \u0003[וכן] השוחט בהמה בפנים\u0004 במקדש \u0003בלילה,\u0004 והיא נפסלת בכך \u0003והעלה בחוץ\u0004 — \u0003פטור,\u0004 לפי שאין היא מתקבלת בפנים. אבל אם \u0003שחט בחוץ בלילה והעלה בחוץ\u0004 — \u0003חייב.\u0004","ועל כך \u0003ר' שמעון אומר: כל שחייבין עליו\u0004 על העלאתו בחוץ אם שחטו \u0003בחוץ\u0004 — \u0003חייבין על כיוצא בו\u0004 כששחטו \u0003בפנים והעלה\u0004 אותו \u0003בחוץ\u0004 (ואף השוחט בהמה בלילה בפנים והעלה בחוץ בכלל זה), \u0003חוץ מן השוחט עוף בפנים והעלה בחוץ.\u0004","\u0003רבא אמר: קבלה\u0004 של דם הקרבן \u0003בכלי חול\u0004 בפנים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אומר]\u0006 התנא הראשון: \u0003[וכן] המקבל\u0004 דם \u0003בכלי חול בפנים והעלה בחוץ\u0004 — פטור, שהרי אינו ראוי להתקבל בפנים. אבל \u0003המקבל בכלי חול בחוץ והעלה בחוץ\u0004 — \u0003חייב.\u0004","\u0003ר' שמעון אומר: כל שחייבין עליו\u0004 על העלאתו בחוץ, אם עשאו \u0003בחוץ\u0004 — \u0003חייבין על כיוצא בו\u0004 כשעשאו בפנים \u0003והעלו בחוץ\u0004 (ואף המקבל דם בכלי חול בכלל זה), \u0003חוץ מן השוחט עוף בפנים והעלו בחוץ.\u0004","ואומרים: \u0003השתא דתני אבוה\u0004 \u0005[עכשיו ששנה אביו]\u0006 של \u0003שמואל בר רב יצחק\u0004 כי ר' שמעון חולק על ההלכה שבראש המשנה, שכן הוא שונה בברייתא: \u0003המולק עוף בפנים והעלו בחוץ\u0004 — \u0003חייב, מלק בחוץ והעלה בחוץ\u0004 — \u0003פטור, ור' שמעון מיחייב.\u0004 יש לפרש כי \u0003ר' שמעון התם קאי\u0004 \u0005[שם הוא עומד],\u0006 להלכה זו של המולק בחוץ הוא מתייחס בסוף המשנה, \u0003ותני\u0004 \u0005[ושנה]\u0006 כך בדבריו: \u0003כל שחייבין עליו בפנים והעלה בחוץ,\u0004 ובכלל זה המולק את העוף בפנים — \u0003חייבין עליו בחוץ,\u0004 שגם אם מלק בחוץ — חייב על העלאתו.","\u0003חטאת שקבל\u0004 הכהן את \u0003דמה\u0004 \u0003בכוס אחד,\u0004 ו\u0003נתן\u0004 תחילה מן הדם על מזבח \u0003בחוץ\u0004 למקדש, \u0003וחזר ונתן\u0004 ממה שנותר \u0003בפנים.\u0004 או שנתן תחילה מן הדם \u0003בפנים, וחזר ונתן\u0004 ממה שנשאר מן הדם \u0003בחוץ\u0004 — \u0003חייב\u0004 בשני המקרים משום העלאה בחוץ, משום \u0003שכולו\u0004 (כל הדם שבכוס) \u0003ראוי\u0004 הוא לנתינה \u0003בפנים.\u0004","אם \u0003קבל דמה בשתי כוסות, נתן שניהם בפנים\u0004 — \u0003פטור,\u0004 שעשה כראוי. אם נתן את \u0003שניהם בחוץ\u0004 — \u0003חייב,\u0004 שהרי שניהם ראויים ליקרב בפנים. אם נתן \u0003אחד בפנים ואחד בחוץ\u0004 — \u0003פטור\u0004 על השני, שהרי כבר גמר את המצוה בכוס הראשון, ושוב אין השני ראוי לבוא בפנים. אם נתן תחילה \u0003אחד בחוץ ו\u0004אחר כך \u0003אחד בפנים\u0004 — \u0003חייב על החיצון\u0004 שהיה ראוי לבוא בפנים. \u0003והפנימי מכפר\u0004, כלומר, יצא בו ידי חובת חטאתו.","\u0003למה הדבר דומה? למפריש חטאתו ואבדה והפריש אחרת תחתיה, ואחר כך נמצאת הראשונה, והרי שתיהן עומדות\u0004 וצריך להקריב אחת מהן לחטאתו. אם \u0003שחט שתיהן בפנים\u0004 — \u0003פטור.\u0004 אם שחט \u0003שתיהן בחוץ\u0004 — \u0003חייב,\u0004 ששתיהן ראויות היו לישחט בפנים. שחט \u0003אחת בפנים ו\u0004אחר כך \u0003אחת בחוץ\u0004 — \u0003פטור\u0004 על השניה ששחט בחוץ, שכבר יצא ידי חובתו בראשונה, ואין השניה ראויה ליקרב בפנים. שחט \u0003אחת בחוץ ואחת בפנים\u0004 — \u0003חייב על החיצונה, והפנימית מכפרת,\u0004 כלומר, יוצא בה ידי חובת חטאתו.","ומוסיפה המשנה: במקרה שכבר שחט שתיהן בפנים, וזרק דמה של אחת מהן, הרי \u0003כשם שדמה פוטר את בשרה\u0004 מן המעילה, והוא מותר לכהנים, \u0003כך היא\u0004 החטאת הזו \u0003פוטרת את בשר חבירתה\u0004 מן המעילה."],["שנינו במשנתנו שבשני אופנים חייב על נתינה בחוץ של דם חטאת שהתקבל בכוס אחת, בין כשנתן בחוץ תחילה ובין כשנתן בפנים תחילה, מפני שכולו ראוי לבא בפנים. ושואלים על כך: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שחייב במקרה שנתן תחילה \u0003בחוץ וחזר ונתן בפנים,\u0004 משום \u0003שכולו ראוי להיות בפנים, אבל\u0004 אם נתן \u0003בפנים והעלן בחוץ,\u0004 מדוע יתחייב על כך? הלוא כבר נשלמה עבודת הדם, ומה שנתן בחוץ \u0003שיריים נינהו\u0004 \u0005[הם]!\u0006","ואומרים: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' נחמיה היא,\u0004 ש\u0003אמר: שירי הדם שהקריבן בחוץ\u0004 — \u0003חייב.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' נחמיה, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003קבל דמה בשני כוסות, נתן שניהם בפנים\u0004 — \u0003פטור, שניהם בחוץ\u0004 — \u0003חייב, אחד בפנים ואחד בחוץ\u0004 — \u0003פטור.\u0004 ומדוע פטור על השני? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' נחמיה: שירי הדם שהקריבן בחוץ\u0004 — \u0003חייב!\u0004","ואומרים: \u0003סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה \u0005הגענו]\u0006 \u0003ל\u0004שיטת \u0003תנא קמא\u0004 של \u0003ר' אלעזר בר' שמעון,\u0004 ש\u0003אמר: כוס עושה דחוי לחבירו,\u0004 שאם קיבל דם חטאת בכמה כוסות, ונתן מאחד מהם את כל ארבע מתנות הדם — אין הדם שבשאר הכוסות נחשב שיריים הנשפכים ליסוד מזבח, אלא הוא נדחה לגמרי מהקרבה.","שנינו במשנה: חטאת שקיבל דמה בשני כוסות, נתן אחד בפנים ואחד בחוץ — פטור על השני שהקריבו בחוץ, מאחר ושוב אינו ראוי להקרבה בפנים. \u0003למה הדבר דומה? למפריש חטאתו ואבדה והפריש אחרת תחתיה ואחר כך נמצאת הראשונה,\u0004 שאם שחט אחת מהן בפנים ואחת בחוץ — פטור על הקרבת השניה בחוץ. ושואלים: \u0003\"למה הדבר דומה\" למה לי?\u0004 מה בא ללמדנו על ידי השוואה זו? ומשיבים: \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבי היא,\u0004 ש\u0003אמר:\u0004 חטאת שהיתה \u0003אבודה בשעת הפרשה\u0004 של השניה, ונמצאה, והקריב אחת מהן — השניה \u0003מתה\u0004 ואינה ראויה להקרבה, ולכן פטור אם הקריבה בחוץ.","","\u0003והכי קאמר\u0004 \u0005[וכך הוא אומר],\u0006 לכך הוא מתכוון בהשוואה של דין החטאות לדין הכוסות: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אבדה\u0004 חטאתו והפריש אחרת תחתיה, אם הקריב אחת מהן בפנים — פטור על הקרבת השניה בחוץ, משום שהיא דחויה מהקרבה, כמו במקרה של שני כוסות, שפטור אם הקריב את השני בחוץ, משום שהוא דחוי מהקרבה. \u0003הא\u0004 \u0005[אבל]\u0006 \u0003הפריש\u0004 מתחילה \u0003שתי חטאות לאחריות\u0004 שאם תאבד אחת מהן יתכפר בשניה, ובמקרה זה אין השניה מתה, אלא רועה עד שיפול בה מום, ומביאים בדמיה עולה — הרי \u0003חדא מינייהו\u0004 \u0005[אחת מהן],\u0006 זו שתיוותר לאחר שתקרב הראשונה, \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003עולה היא,\u0004 ולכן אם הקריבה בחוץ — חייב על כך. \u0003וכ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב\u0004 במקרה דומה: \u0003אשם ש\u0004נתכפרו בעליו ומשום כך \u0003ניתק\u0004 (הוצא) \u0003לרעייה\u0004 עד שיפול בו מום וייפדה, ויביאו בדמיו עולה, \u0003ושחטו סתם,\u0004 אפילו בלי כוונה מיוחדת — \u0003כשר\u0004 והוא קרב \u0003לעולה.\u0004","","ודוחים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003אשם\u0004 הוא \u0003זכר, ועולה זכר,\u0004 ולכן איל האשם עצמו ראוי לעולה. \u0003אבל חטאת\u0004 הלוא \u0003נקבה היא,\u0004 ואיך אפשר לומר שהיא נחשבת מתחילתה לעולה?! \u0003אמר ר' חייא מיוסתיניא:\u0004 מדובר פה \u0003בשעיר\u0004 חטאת של \u0003נשיא,\u0004 שהוא אכן זכר. והפריש מתחילה שניים לאחריות וקרב אחד מהם. שהואיל והשני כשר לעולה, אם הקריבו בחוץ — חייב.","","\u0003פרת חטאת\u0004 (פרה אדומה) \u0003ששרפה חוץ מגתה\u0004 שהיו מתקינים מקום שקוע כעין גת בהר הזיתים, מול פתח ההיכל, המיועד לשחיטתה ולשריפתה. \u0003וכן שעיר המשתלח\u0004 למדבר ביום הכיפורים, \u0003שהקריב\u0004 אותו \u0003בחוץ\u0004 ולא גלגלו במורד הצוק כראוי לו — הרי זה \u0003פטור\u0004 עליהם משום הקרבה בחוץ, משום","\u0003שנאמר\u0004 בפרשת שחיטה בחוץ של קדשים: \"...אשר ישחט מחוץ למחנה. \u0003ואל פתח אהל מועד לא הביאו\"\u0004 (ויקרא יז, ג— ד), לומר: \u0003כל שאין ראוי\u0004 שאינו מיועד \u0003לבא אל פתח אהל מועד\u0004 — \u0003אין חייבין עליו\u0004 משום שחיטת חוץ והעלאה בחוץ. והרי פרה אדומה ושעיר המשתלח אין מיועדים לבוא אל פתח אהל מועד.","וכיוצא בזה קדשים הפסולים להקרבה: בעל חיים זכר \u0003הרובע\u0004 את האשה, \u0003והנרבע\u0004 על ידי אדם, \u0003ו\u0004כן \u0003המוקצה\u0004 שייעדוהו לעבודה זרה, \u0003והנעבד\u0004 כעבודה זרה, \u0003ו\u0004כן \u0003המחיר\u0004 ששימש כתמורה לכלב, \u0003[והאתנן\u0004 שניתן כתשלום לזונה\u0003], והכלאים\u0004 (שנולד משני מיני בעלי חיים, כגון תיש ורחל), \u0003ו\u0004כן \u0003ה\u0004בהמה שהיא \u0003טריפה\u0004 (שעומדת למות עקב מחלה או פגיעה), \u0003ו\u0004כן בעל חיים שהוא \u0003יוצא דופן\u0004 (שנולד שלא כרגיל, אלא שנחתכה דופן בטנה של אמו והוצא משם), כל אלו \u0003שהקריבן בחוץ\u0004 — הרי זה \u0003פטור,\u0004 משום","\u0003שנאמר\u0004 בפרשת שחיטת קדשים בחוץ: \"ואל פתח אהל מועד לא הביאו להקריב קרבן לה' \u0003לפני משכן ה'\"\u0004 (ויקרא יז, ד), לומר: \u0003כל שאין ראוי לבא לפני משכן ה' אין חייבין עליו\u0004 אם הקריבוהו בחוץ. וכל אלו אין ראויים לבוא וליקרב לפני משכן ה'.","וכן \u0003בעלי מומין, בין\u0004 שהם \u0003בעלי מומין\u0004 \u0003קבועין, בין\u0004"],["שהיו אלו \u0003בעלי מומין עוברין, שהקריבן בחוץ\u0004 — הרי הוא \u0003פטור\u0004 משום הקרבה בחוץ, שהרי אלו קדשים פסולים ואינם בכלל הראויים לבא לפני משכן ה'. \u0003ר' שמעון אומר:\u0004 המקריב בחוץ \u0003בעלי מומין קבועין\u0004 — \u0003פטור\u0004 משום הקרבה בחוץ, ואולם המקריב בחוץ \u0003בעלי מומין עוברין\u0004 — \u0003חייב\u0004 עליהם, לא בכרת (כשאר החייבים על הקרבה בחוץ) אלא \u0003בלא תעשה\u0004 בלבד, משום שהם ראויים לבוא לאחר זמן.","ועוד בדינים אלה, \u0003תורים ש\u0004עדיין \u0003לא הגיע זמנן\u0004 להיות כשרים להקרבה (שאין התורים כשרים להקרבה אלא כשהם גדולים, משיזהיבו כנפיהם), או \u0003בני יונה ש\u0004כבר \u0003עבר זמנן\u0004 (שאין הם כשרים אלא בהיותם קטנים עד שיצהיבו כנפיהם), \u0003שהקריבן בחוץ\u0004 — \u0003פטור\u0004 על הקרבתם בחוץ, משום שאינם ראויים לבא לפני משכן ה' להקרבה. \u0003ר' שמעון אומר: בני יונה שעבר זמנן\u0004 שהקריבם בחוץ — \u0003פטור\u0004 עליהם, \u0003ו\u0004אולם המקריב בחוץ \u0003תורים שלא הגיע זמנן\u0004 — חייב עליהם, אמנם לא בכרת, אלא \u0003בלא תעשה\u0004 בלבד.","ועוד כיוצא בו, המקריב בחוץ \u0003אותו ואת בנו\u0004 ביום אחד, והרי איסור תורה הוא לשחוט את השני באותו יום (ויקרא כב, כח), ואינו ראוי להקרבה. וכן המקריב בחוץ \u0003מחוסר זמן\u0004 שעדיין לא הגיע זמנו להיות ראוי להקרבה — הרי זה \u0003פטור, ר' שמעון אומר: הרי זה\u0004 חייב \u0003בלא תעשה.\u0004 שכן הוא הכלל במחלוקתם זו של חכמים ור' שמעון, \u0003שר' שמעון אומר: כל\u0004 דבר מן הקדשים \u0003שהוא ראוי לבא\u0004 להיות מוקרב במקדש \u0003לאחר זמן\u0004 אף שכעת אינו ראוי, והקריבו בחוץ — \u0003הרי זה בלא תעשה ואין בו כרת. ו\u0004אילו \u0003חכמים אומרים: כל שאין בו כרת אין בו\u0004 גם \u0003לא תעשה.\u0004","ומוסיפה המשנה: \u0003מחוסר זמן\u0004 שנחלקו בו חכמים ור' שמעון — \u0003בין\u0004 שהוא מחוסר זמן \u0003בגופו\u0004 (כגון תורים שלא הגיע זמנם, או בהמה שלא מלאו לה שבעה ימים מלידתה, ראה ויקרא כב, כז), ו\u0003בין\u0004 שהוא מחוסר זמן \u0003בבעליו.\u0004","ומסבירים, \u0003איזהו מחוסר זמן בבעליו?\u0004 כגון \u0003הזב והזבה והיולדת והמצורע\u0004 שעדיין לא מלאו ימי טהרתם, \u0003שהקריבו\u0004 את \u0003חטאתם ואשמם בחוץ\u0004 — הריהם \u0003פטורין\u0004 משום הקרבה בחוץ, שהרי אינם מחוייבים עדיין בקרבנות אלו, ואינם רשאים להביאם. ואולם אם הקריבו בשלב זה את \u0003עולותיהן ושלמיהן בחוץ\u0004 — \u0003חייבין,\u0004 מפני שקרבנות אלה באים כקרבנות נדבה אף כשהבעלים טמאים.","\u0003המעלה\u0004 בחוץ \u0003מבשר\u0004 קרבן ה\u0003חטאת\u0004 (החיצונה, הנאכלת לכהנים), \u0003מבשר אשם, מבשר\u0004 שאר \u0003קדשי קדשים\u0004 הנאכלים, כלומר, שני כבשי עצרת, \u0003מבשר קדשים קלים, ו\u0004כן המעלה בחוץ מ\u0003מותר\u0004 מנחת \u0003העומר,\u0004 לאחר שניטל ממנה הקומץ, \u0003ו\u0004מ\u0003שתי הלחם\u0004 המובאות בחג השבועות, \u0003ו\u0004מ\u0003לחם הפנים\u0004 אותו עורכים כל שבת בהיכל, \u0003ו\u0004כן המעלה בחוץ מ\u0003שירי\u0004 ה\u0003מנחות\u0004 — פטור. משום שכל אלה הריהם מיועדים לאכילה על ידי הכהנים ולא להקרבה על המזבח.","\u0003ו\u0004כן העושה בחוץ עבודות אלו: \u0003היוצק\u0004 את השמן על המנחה, \u0003והפותת\u0004 את המנחה לפתיתים, \u0003והבולל\u0004 בשמן את סולת המנחה, \u0003והמולח\u0004 מנחות (או שאר קרבנות), \u0003והמניף\u0004 מנחה, \u0003והמגיש\u0004 את המנחה לקרן המזבח שעושה בחוץ, לאחר הנפתה, \u0003והמסדר את\u0004 לחם הפנים על \u0003השולחן\u0004 בחוץ, \u0003והמטיב את הנרות\u0004 של המנורה, \u0003והקומץ\u0004 מהמנחה, \u0003והמקבל\u0004 בכלי מן ה\u0003דמים\u0004 של הקרבן. כל אלה אף שאסור לעשותם בחוץ, אם נעשו \u0003בחוץ\u0004 — \u0003פטור,\u0004 שאין חייבים אלא על עבודה כעין העלאה, שהוזכרה בכתוב, שהיא גמר עבודה. וכל אלו יש עבודה אחריהן.","\u0003ואין חייבין עליו\u0004 (על כל העבודות הללו) מיתה \u0003לא משום זרות\u0004 (איסור עבודה למי שאינו כהן), \u0003ולא משום\u0004 האיסור על הכהנים לעבוד ב\u0003טומאה, ולא משום\u0004 האיסור על הכהן לעבוד כשהוא \u0003מחוסר בגדים\u0004 (בגדי הכהונה), \u0003ולא משום\u0004 האיסור על הכהן לעבוד בהיותו במצב \u0003[שלא] רחוץ ידים ורגלים.\u0004","ומעתה נשנה דין הקרבה בחוץ במהלך הדורות: בתחילה, \u0003עד שלא הוקם המשכן\u0004 במדבר סיני, בשנה השנית לצאת בני ישראל ממצרים, \u0003היו הבמות מותרות\u0004 הותר להקריב בכל מקום, \u0003ו\u0004ה\u0003עבודה\u0004 בקרבנות היתה נעשית \u0003בבכורות\u0004 של כל ישראל. \u0003ומ\u0004עת \u0003שהוקם המשכן נאסרו\u0004 כל \u0003הבמות, ו\u0004ה\u0003עבודה\u0004 היתה נעשית \u0003בכהנים\u0004 בלבד. ואז \u0003קדשי קדשים נאכלין לפנים מן הקלעים\u0004 (בחצר אהל מועד), \u0003ו\u0004אילו \u0003קדשים קלים\u0004 נאכלים \u0003בכל מחנה ישראל.\u0004 בזמן כניסת ישראל לארץ בימי יהושע, לאחר שעברו את הירדן ו\u0003באו לגלגל,\u0004 ושם עמד המשכן ומזבח הנחושת — \u0003הותרו\u0004 שוב \u0003הבמות.\u0004 ואז \u0003קדשי קדשים\u0004 היו \u0003נאכלין לפנים מן הקלעים\u0004 של חצר המשכן, \u0003ו\u0004אולם \u0003קדשים קלים\u0004 היו נאכלים \u0003בכל מקום.\u0004","ולאחר מכן, כאשר \u0003באו לשילה\u0004 ושם שוכן אהל מועד, חזרו ו\u0003נאסרו הבמות.\u0004 \u0003ו\u0004משכן זה שהיה בשילה, \u0003לא היה שם תקרה\u0004 העשויה מקרשים או אבנים, \u0003אלא בית אבנים בלבד מלמטן, והיריעות\u0004 של המשכן היו פרוסות \u0003מלמעלן.\u0004 \u0003והיא\u0004 התקופה בה היה המשכן בשילה, \u0003היתה\u0004 זו המכונה בתורה \u0003\"מנוחה\",\u0004 שעד אותה שעה התירה התורה הקרבה בבמות, שנאמר: \"כי לא באתם עד עתה אל המנוחה\" (דברים יב, ט). ובתקופה זו היו \u0003קדשי קדשים נאכלין לפנים מן הקלעים\u0004 המקיפים את חצר בית ה', \u0003וקדשים קלים ומעשר שני\u0004 שצריך להביאם למקום המשכן ולאוכלם לפני ה' (דברים יב, ו) היו נאכלים \u0003בכל\u0004 מקום \u0003הרואה\u0004 את שילה.","ולאחר מכן, כאשר חרבה שילה עם מותו של עלי הכהן (ראה שמואל א ד, יח) \u0003באו\u0004 המשכן וכליו \u0003לנוב וגבעון,\u0004 ושוב \u0003הותרו הבמות.\u0004 ואזי, \u0003קדשי קדשים\u0004 היו \u0003נאכלין לפנים מן הקלעים,\u0004 ו\u0003קדשים קלים\u0004 היו נאכלים \u0003בכל ערי ישראל.\u0004","ומעת ש\u0003באו לירושלים\u0004 ובנו את המקדש בימי שלמה, שוב \u0003נאסרו הבמות, ו\u0004מעתה \u0003לא היה להן\u0004 עוד \u0003היתר. והיא\u0004 בהיות בית המקדש בירושלים, \u0003היתה \"נחלה\",\u0004 שנזכרה בכתוב: \"כי לא באתם עד עתה אל המנוחה ואל הנחלה\" (דברים יב, ט). ובירושלים \u0003קדשי קדשים נאכלין לפנים מן הקלעים,\u0004 כלומר, בעזרה, \u0003קדשים קלים ומעשר שני\u0004 — \u0003לפנים מן החומה\u0004 של העיר, שהיא במקום מחנה ישראל שבמדבר.","\u0003כל הקדשים שהקדישן בשעת איסור הבמות,\u0004 \u0003והקריבן\u0004 בחוץ \u0003בשעת איסור הבמות מבחוץ —\u0004 \u0003הרי\u0004 זה עובר על \u0003אלו ב\u0004מצוות \u0003עשה\u0004 להקריב במקום הנבחר על ידי ה', \u0003ו\u0004על מצוות \u0003לא תעשה\u0004 שאין להקריב אז בבמה, \u0003וחייבין עליו כרת.\u0004","ואם \u0003הקדישן בשעת היתר הבמות\u0004 כגון בזמן הבמה בגבעון, \u0003והקריבן\u0004 בחוץ \u0003בשעת איסור הבמות\u0004 משנבנה המקדש בירושלים \u0003בחוץ\u0004 — \u0003הרי\u0004 הוא עובר על \u0003אלו בעשה ולא תעשה, ו\u0004אולם \u0003אין חייבין עליהן כרת.\u0004 אם \u0003הקדישן בשעת איסור הבמות\u0004 כגון בזמן משכן שילה, \u0003והקריבן\u0004 בחוץ \u0003בשעת היתר הבמות\u0004 בתקופת נוב — \u0003הרי אלו בעשה,\u0004 כלומר, חייב על שביטל מצות עשה להביאם למשכן, \u0003ו\u0004מכל מקום \u0003אין בהן\u0004 עבירה על מצות \u0003לא תעשה\u0004 (ולא עונש כרת), שלא להקריב במקדש, שהרי עכשיו מותר להקריב בחוץ.","ומוסיפה המשנה: \u0003ואלו קדשים\u0004 ש\u0003קרבין\u0004 גם בזמן היתר הבמות רק \u0003במשכן\u0004 שבבמה הגדולה, במת הציבור שבגלגל, בנוב ובגבעון: \u0003קדשים שהוקדשו ל\u0004שם הקרבה ב\u0003משכן.\u0004 ולכן \u0003קרבנות ציבור\u0004 שסתמן עומדים להקרבה במשכן \u0003קרבין במשכן, ו\u0004אילו \u0003קרבנות היחיד\u0004 שאינם עומדים להקרבה דווקא במשכן — קרבים \u0003בבמה. קרבנות היחיד שהוקדשו למשכן\u0004 — \u0003יקריבו במשכן, ואם הקריבן בבמה\u0004 — \u0003פטור.\u0004","\u0003ו\u0004עוד, \u0003מה בין במת\u0004 \u0003יחיד לבמת ציבור?\u0004 שבבמת ציבור יש \u0003סמיכה ו\u0004יש חובה של \u0003שחיטת צפון,\u0004"],["\u0003ומתן\u0004 דם \u0003סביב\u0004 כל צידי המזבח, בקרבנות שנאמר בהם דין זה, \u0003ו\u0004אין בהם לא \u0003תנופה\u0004 של מנחות, \u0003ו\u0004לא \u0003הגשה\u0004 של מנחות לקרן המזבח קודם שיקמוץ מהן את הקומץ. \u0003ר' יהודה אומר:\u0004 \u0003אין\u0004 כלל \u0003מנחה בבמה. ו\u0004אין בבמה קטנה \u0003כיהון,\u0004 כלומר, כהונה, אלא גם זרים כשרים לעבודה, \u0003ו\u0004אין בה צורך ב\u0003בגדי שרת\u0004 של כהונה, \u0003ו\u0004לא ב\u0003כלי שרת\u0004 כדי לקדש בהם את הדברים העולים על המזבח, כגון מזרקי הדם. \u0003ו\u0004אין צריכים ל\u0003ריח ניחוח, ו\u0004אין צריכים \u0003מחיצה לדמים\u0004 כגון חוט סיקרא שהיה במקדש, להבחין בין חלק עליון ותחתון של המזבח, \u0003ו\u0004אין בהם מצות \u0003ריחוץ ידים ורגלים\u0004 לפני עבודה.","\u0003אבל הזמן\u0004 מחשבת הקרבה או אכילה חוץ לזמנו שמפגלת את הקרבן, ודין \u0003הנותר\u0004 שאסור להותיר מן הקדשים, \u0003והטמא\u0004 שאסור להקריב ולאכול מן הקדשים בטומאה — \u0003שוין בזה ובזה\u0004 בגדולה ובקטנה.","שנינו במשנתנו שאין חייבים משום הקרבת חוץ על שריפת פרה אדומה חוץ מגתה. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"חוץ מגתה\"? אמר ריש לקיש: חוץ מ\u0004ה\u0003מקום הבדוק לה\u0004 מטומאה. \u0003אמר לו ר' יוחנן\u0004 לריש לקיש: \u0003והלא כל ארץ ישראל בדוקה היא\u0004 לענין טומאה, ואין צורך איפוא למקום מיוחד הבדוק מטומאה לשריפת הפרה!","\u0003אלא אמר ר' יוחנן:\u0004 כוונת המשנה בביטוי \"חוץ מגתה\" היא \u0003כגון ששחטה\u0004 הכהן את הפרה האדומה \u0003לפנים מן חומת ירושלים,\u0004 ולא מחוץ לחומת ירושלים, כפי שנאמר: \"והוציא אותה אל מחוץ למחנה ושחט אותה\" (במדבר יט, ג).","ושואלים: ומדוע להעמיד במקרה כזה? \u0003ולוקמה\u0004 \u0005[ושיעמיד\u0006 ר' יוחנן \u0005אותה\u0006 את לשון זו של משנתנו\u0005]\u0006 \u0003כגון ששחטה\u0004 מ\u0003חוץ לחומה,\u0004 אבל \u0003שלא כנגד הפתח\u0004 (של ההיכל במקדש), שהרי \u0003אמר רב אדא בר אהבה: שחטה שלא כנגד הפתח\u0004 — \u0003פסולה, שנאמר\u0004 בתורה בדין הפרה האדומה: \"והוציא אותה אל מחוץ למחנה \u0003ושחט\u0004 אותה לפניו... \u0003והזה\u0004 אל נכח פני אהל מועד מדמה\" (במדבר יט, ג-ד).","והכתוב מזכיר יחד את שחיטת הפרה והזאת דמה, להקישן זו לזו: \u0003מה הזאתה\u0004 צריכה להיות \u0003כנגד הפתח\u0004 כנאמר במפורש בכתוב, \u0003אף שחיטתה\u0004 צריכה להיות \u0003כנגד הפתח! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שר' יוחנן \u0003לא מקיש\u0004 היקש זה — \u0003והא אתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בדין הפרה האדומה ש\u0003שחטה\u0004 הכהן \u0003שלא כנגד הפתח\u0004 — \u0003ר' יוחנן אומר: פסולה,\u0004 וטעמו הוא משום היקש זה של \u0003\"ושחט... והזה\". ריש לקיש אמר: כשרה,\u0004 משום שנאמר: \"והוציא אותה \u0003אל מחוץ למחנה ושחט\u0004 אותה לפניו\", ומשמע — בכל מקום מחוץ למחנה.","\u0003ואיתמר נמי\u0004 \u0005[ונאמר גם כן]\u0006 שנחלקו אמוראים בדין הפרה האדומה ש\u0003שרפה\u0004 הכהן \u0003שלא כנגד הפתח,\u0004 ואף בזאת \u0003ר' יוחנן אמר: פסולה, ו\u0004אילו \u0003ר' אושעיא אמר: כשרה.\u0004 וטעמו של כל אחד: \u0003ר' יוחנן אמר פסולה,\u0004 משום ההיקש הנוסף שבפרשה זו, שכן נאמר: \u0003\"ושרף\u0004 את הפרה\" (במדבר יט, ה), ובפסוק שקדם לו נאמר: \u0003\"והזה\u0004 אל נכח פני אהל מועד\", ללמד שכשם שהזאה צריכה להיות כנגד הפתח, אף השריפה צריכה להיות כנגד הפתח.","\u0003ו\u0004אילו \u0003ר' אושעיא אמר\u0004 שפרה ששרפה שלא כנגד הפתח \u0003כשרה,\u0004 שכן נאמר בשריפת הפרה: \"ושרף את הפרה לעיניו וכו' \u0003על פרשה ישרף\"\u0004 (במדבר יט, ה), והרי זה בא ללמד שב\u0003מקום\u0004 שבו \u0003פורשת\u0004 (\"פרשה\") הפרה \u0003למיתה,\u0004 כלומר, במקום בו יוצאת נפשה \u0003שם תהא שריפתה.\u0004 וכשם שאין מקום מוגדר ליציאת נפשה כך גם אין מקום מוגדר לשריפתה. הרי שר' יוחנן סבור כי מדין תורה צריכה גם השחיטה להיות דווקא נגד הפתח, ומדוע לא העמיד את משנתנו בשחיטת הפרה שלא כנגד הפתח?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתירוץ לזה: בדרך \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אומר\u0006 ר' יוחנן\u0005],\u0006 ובאופן זה: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם שחטה \u0003חוץ לחומה\u0004 שלא כנגד פתח ההיכל, שהיא פסולה, \u0003דרחוקי רחקה\u0004 \u0005[ש\u0006הרי \u0005ריחק אותה]\u0006 ממקום המקדש, ומשום כך לא יהא חייב משום שחיטת חוץ. \u0003אלא אפילו\u0004 אם שחטה \u0003לפנים מן החומה, דקרובי קרבה\u0004 \u0005[שקירב אותה]\u0006 אל המקדש, \u0003ואימא תתכשר\u0004 \u0005[\u0006ויכול אתה \u0005לומר\u0006 ש\u0005תהיה כשרה],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 תוך כדי פירושו למשנה, שאין שחיטת הפרה כשירה אלא כשעשאה בחוץ.","ודנים במחלוקת שהובאה קודם לכן. \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003אמר לו ר' יוחנן\u0004 לריש לקיש: \u0003והלא כל ארץ ישראל בדוקה היא,\u0004 ולא נשנתה בברייתא תשובתו של ריש לקיש על שאלה זו. ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון, \u0005הם חלוקים]?\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005סבור]:\u0006 \u0003ירד מבול לארץ ישראל,\u0004 ומתו בה היושבים בה, ולכן יש צורך לבדוק במקום שריפת הפרה אם אין מתחתיו טומאה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005סבור]:\u0006 \u0003לא ירד\u0004 המבול בארץ ישראל, ולכן אין צורך לחפש אחר שרידי המתים.","\u0003אמר רב נחמן בר יצחק: ושניהם,\u0004 ר' יוחנן וריש לקיש, \u0003מקרא אחד דרשו.\u0004 שנאמר בנבואת יחזקאל אודות ארץ ישראל: \u0003\"בן אדם אמר לה את ארץ לא מטהרה היא לא גשמה ביום זעם\"\u0004 (יחזקאל כב, כד), ונחלקו בדרך קריאתו של מקרא זה,","\u0003ר' יוחנן סבר\u0004 \u0005[סבור]\u0006 כי \u0003אתמוהי מתמה קרא\u0004 \u0005[תמיהה\u0006 היא ש\u0005תמה הכתוב]:\u0006 \u0003ארץ ישראל, מי\u0004 \u0005[האם]\u0006 \u0003לא מטוהרה את\u0004 מטומאת מתים בך? \u0003כלום ירדו עליך גשמים\u0004 של מבול \u0003ביום זעם?! וריש לקיש סבר:\u0004 דרך קריאתו של מקרא זה היא \u0003כפשטיה\u0004 \u0005[כפשוטו,\u0006 כאמירה פשוטה, שלא בתמיהה\u0005]:\u0006 \u0003ארץ לא מטוהרה את, מי\u0004 \u0005[האם]\u0006 \u0003לא ירדו עליך גשמים ביום זעם?!\u0004 ולכן נשארו בך כל מתי המבול, המטמאים אותך.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו בדין הפרה האדומה: \u0003חצירות היו בירושלים,\u0004 \u0003בנויות על הסלע, ותחתיהן חלול\u0004 (היה חלל), \u0003מפני\u0004 חשש \u0003קבר התהום\u0004 שמא יש קבר בעומק האדמה, ואם יש שם חלל הריהו חוצץ בפני הטומאה. \u0003ו\u0004היו \u0003מביאין נשים מעוברות ויולדות\u0004 שם את בניהם, ונמצאו איפוא הילדים גדלים בלא חשש טומאה. \u0003ומגדלות שם\u0004 את \u0003בניהם\u0004 כדי שיהיו ראויים \u0003ל\u0004השתתף בעשיית ה\u0003פרה\u0004 האדומה.","\u0003ו\u0004כיון שהילדים הגיעו לגיל ראוי, היו \u0003מביאין\u0004 לאותן חצרות \u0003שוורים, ועל גביהן\u0004 של השוורים הללו היו \u0003דלתות, ו\u0004ה\u0003תינוקות\u0004 הללו היו \u0003יושבין עליהן,\u0004 כדי שיפסיקו הדלתות בינם לבין טומאה המצויה בתהום, \u0003וכוסות של אבן,\u0004 שאינן מקבלות טומאה, \u0003בידן.\u0004 וירדו כשהם רכובים על השוורים הללו אל מעין השילוח שבירושלים, \u0003ומלאו\u0004 מים מן המעין, וחזרו \u0003וישבו במקומן\u0004 על גבי השוורים, והלכו להר הבית, שם היו נותנים מאפר הפרה לתוך המים שבכוסות האבן הללו. משמע מסדר זה של עשיית הפרה שאנו חוששים לטומאה בארץ ישראל!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 כך יכול ר' יוחנן להשיב: \u0003מעלה\u0004 (חומרה מיוחדת) \u0003עשו\u0004 חכמים \u0003ב\u0004מעשיה של \u0003פרה\u0004 אדומה, ואולם אין זה מלמד שבאופן כללי יש לחשוש לטומאה בארץ ישראל משום מתי המבול.","ומן הצד האחר, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בברייתא: \u0003פעם אחד מצאו עצמות\u0004 מת \u0003בלשכת דיר העצים\u0004 \u0003ובקשו\u0004 חכמים \u0003לגזור טומאה על ירושלים\u0004 לטמא את המהלך בה, שאם במקום זה נמצא מת, יש לחשוש שאף בשאר מקומות נמצאים מתים. \u0003עמד ר' יהושע על רגליו ואמר: לא בושה וכלימה היא לנו שנגזור טומאה על עיר אבותינו\u0004 בשל חשש זה? הראו לי \u0003איה\u0004 הם \u0003מתי מבול,\u0004 \u0003איה\u0004 הם כל \u0003מתי נבוכדנצר\u0004 שהרג?","ויש לדייק בדברי ר' יהושע: \u0003מדקאמר הכי\u0004 \u0005[מ\u0006מה \u0005שהוא אומר כך],\u0006 \u0003לאו למימרא דלא הוו\u0004 \u0005[האם אין\u0006 זה \u0005בא לומר שלא היו\u0006 מתי מבול בירושלים\u0005]?\u0006 ומכאן שלא ירד שם המבול! ומשיב ריש לקיש על שאלת ר' יוחנן: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שלא היו כלל מתי מבול בארץ ישראל, האם ב\u0003הרוגי נבוכדנצר\u0004 שהזכיר ר' יהושע \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא הוו\u0004 \u0005[היו]?\u0006 והרי ברור שרבים היו המתים שהרג נבוכדנצר בירושלים! \u0003אלא הוו ופנינהו\u0004 \u0005[היו ופינו אותם].\u0006 \u0003הכא נמי הוו ופנינהו\u0004 \u0005[כאן,\u0006 בענין מתי מבול, \u0005גם כן\u0006 נאמר ש\u0005היו ופינו אותם].\u0006 מקשה עליו ר' יוחנן: \u0003ואי אפנו\u0004 \u0005[ואם\u0006 הם כבר \u0005פונו]\u0006 מדוע יש לחשוש לטומאה, כפי שאתה חושש בענין מקומה של פרה אדומה?"],["\u0003הא איפני\u0004 \u0005[הרי\u0006 כבר \u0005פונו]!\u0006 ומשיב ריש לקיש: ברייתא זו הרי עוסקת בירושלים, ויש לומר ש\u0003נהי דאיפני\u0004 \u0005[אם אמנם פונו\u0006 עצמות מתי מבול ונבוכדנצר\u0005]\u0006 \u0003מירושלים, מכולה\u0004 \u0005[מכל]\u0006 \u0003ארץ ישראל לא איפני\u0004 \u0005[פונו],\u0006 ולכן מחוץ לירושלים רק מקום בדוק כשר לשחיטת הפרה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך את מהלך הדברים הללו, שמברייתא זו \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 הסבור שהמבול לא הגיע לארץ ישראל: הרי כך אמר ר' יהושע: \u0003\"איה מתי מבול? איה מתי נבוכדנאצר?\"\u0004 ולכאורה \u0003מאי לאו מדהני הוו\u0004 \u0005[האם אין\u0006 להבין מכאן כי \u0005מ\u0006כיון \u0005שאלה,\u0006 מתי נבוכדנצר, \u0005היו]\u0006 בארץ, \u0003הני נמי הוו\u0004 \u0005[אלה,\u0006 מתי מבול, \u0005גם כן היו\u0006 בארץ\u0005]?\u0006 ודחה ר' יוחנן את הראייה הזו: \u0003מידי איריא\u0004 \u0005[כלום הדברים שייכים]?\u0006 \u0003הא כדאיתיה והא כדאיתיה\u0004 \u0005[זה כמו שישנו וזה כמו שישנו],\u0006 מתי נבוכדנצר אמנם היו בארץ ישראל, ואולם מתי מבול לא היו בה, משום שהמבול לא היה בה.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ריש לקיש לר' יוחנן: נאמר במבול \"כל אשר נשמת רוח חיים באפיו \u0003מכל אשר בחרבה מתו\"\u0004 (בראשית ז, כב). ומעתה, \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי, שאני אומר]\u0006 ש\u0003ירד מבול לארץ ישראל, משום הכי\u0004 \u0005[כך]\u0006 \u0003מתו\u0004 כל בעלי החיים שעל פני האדמה (\"בחרבה\"), ואף אלו שבארץ ישראל, \u0003אלא לדידך\u0004 \u0005[לשיטתך]\u0006 שלא ירד בארץ ישראל מבול, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מתו\u0004 בעלי החיים שבארץ ישראל? והשיב ר' יוחנן: \u0003משום הבלא\u0004 \u0005[חום]\u0006 שהתלווה למי המבול, ואותו חום היה אף בארץ ישראל.","ומעירים: והוא \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: ברותחין\u0004 בחום שיש במעשי עריות \u0003קלקלו\u0004 בני דור המבול, \u0003וברותחין נידונו\u0004 שמי המבול רותחים היו. \u0003דכתיב הכא\u0004 \u0005[ש\u0006כן \u0005נאמר כאן\u0006 בתום המבול\u0005]:\u0006 \"ויעבר אלקים רוח על הארץ \u0003וישכו המים\"\u0004 (בראשית ח, א), \u0003וכתיב התם\u0004 \u0005[ונאמר שם\u0006 במגילת אסתר לאחר תליית המן\u0005]:\u0006 \u0003\"וחמת המלך שככה\"\u0004 (אסתר ז, י), הרי ששכיכה באה לאחר חום, ואף במבול היה חום ששכך.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את מהלך הדברים הזה באופן הפוך, שמפסוק אחר \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש,\u0004 וכך הקשה: נאמר \u0003\"מכל אשר בחרבה מתו\"\u0004 (בראשית ז, כב). \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי,\u0006 \u0005שאני אומר]\u0006 ש\u0003לא ירד מבול לארץ ישראל\u0004 — \u0003משום הכי הוי\u0004 \u0005[כך היה]\u0006 מקום של \u0003חרבה\u0004 אף בזמן המבול (ומתו בעלי החיים שבו מחמת החום). \u0003אלא לדידך\u0004 \u0005[לשיטתך],\u0006 שירד מבול בארץ ישראל, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חרבה\"\u0004 האמור בתיאור המבול? והרי לא היה אז כל מקום יבש בעולם! והשיב ריש לקיש: הכוונה ל\u0003חרבה\u0004 (ליבשה) \u0003שהיתה מעיקרא\u0004 \u0005[מתחילה,\u0006 לפני בוא המבול\u0005]\u0006 שמתו כל בעלי החיים שהיו בה.","\u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לה]\u0006 הכתוב בתוך תיאור המבול \u0003\"חרבה\"?\u0004 להשמיענו \u0003כ\u0004דברי \u0003רב חסדא,\u0004 שכך \u0003אמר רב חסדא: בדור המבול לא נגזרה גזרה על דגים שבים, שנאמר: \"מכל אשר בחרבה מתו\",\u0004 כלומר, אלו שהיו מתחילה ביבשה, \u0003ולא דגים שבים.\u0004","וממשיכים לדון במחלוקת ר' יוחנן וריש לקיש אם ירד המבול בארץ ישראל, ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 ש\u0003לא ירד מבול לארץ ישראל, היינו דקם רימא התם\u0004 \u0005[זהו\u0006 ההסבר לכך \u0005שעמד הראם שם\u0006 בארץ ישראל\u0005]\u0006 בזמן המבול, וכך נשאר בחיים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 ריש לקיש\u0005]\u0006 ש\u0003ירד\u0004 מבול אף בארץ ישראל, \u0003רימא היכא קם\u0004 \u0005[הראם היכן עמד],\u0006 שהרי ברור שהראם במידותיו הגדולות (כמבואר להלן) לא יכול היה להיכנס לתיבת נח! ומביאים בתשובה לכך מה ש\u0003אמר ר' ינאי:\u0004 הוא אכן נכנס לתיבה, ואולם לא היה זה ראם גדול במלוא קומתו, אלא \u0003גוריות\u0004 (גורים) של ראמים \u0003הכניסו בתיבה,\u0004 וכך נשתמרו הראמים לאחר המבול.","ומקשים על כך: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה: לדידי חזי לי אורזילא דרימא בת יומא\u0004 \u0005[אני ראיתי גור ראם בן יומו]\u0006 \u0003והוי\u0004 \u0005[והיה\u0006 גודלו\u0005]\u0006 \u0003כהר תבור\u0004 שבארץ ישראל. \u0003והר תבור כמה הויא\u0004 \u0005[הוא\u0006 גודלו\u0005]?\u0006 \u0003ארבעין פרסי\u0004 \u0005[ארבעים פרסה],\u0006 \u0003משכא דצואריה תלתא פרסי\u0004 \u0005[אורך צווארו\u0006 של אותו גור ראמים היה \u0005שלוש פרסות],\u0006 \u0003מרבעתא דרישא פרסא ופלגא\u0004 \u0005[\u0006מקום \u0005מרבץ ראשו,\u0006 צווארו, היה גודלו \u0005פרסה וחצי],\u0006 \u0003רמא כבא וסכר ירדנא\u0004 \u0005[הטיל\u0006 אותו גור ראמים \u0005גלל, וסתם\u0006 את \u0005הירדן\u0006 מרוב גודלו\u0005].\u0006 ואם כן אף את גור הראם אי אפשר היה להכניס לתיבה בשל גודלו!","ומשיבים: \u0003אמר ר' יוחנן:\u0004 רק את \u0003ראשו\u0004 של גור הראם \u0003הכניסו לתיבה,\u0004 בעוד שכל גופו היה מחוצה לה. ומקשים על כך: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם,\u0006 רבה בר בר חנה\u0005]:\u0006 \u0003מרבעתא דרישא פרסא ופלגא\u0004 \u0005[\u0006מקום \u0005מרבץ ראשו,\u0006 צוארו, היה בגודל \u0005פרסה וחצי],\u0006 ואם כן אף את ראשו בלבד אי אפשר היה להכניס לתיבה! \u0003אלא\u0004 צריך לתקן ולומר שרק את \u0003ראש\u0004 (קצה) \u0003חוטמו\u0004 של גור הראם \u0003הכניסו לתיבה,\u0004 כדי שיוכל לנשום.","ותמהים: ומדוע נזקק ר' יוחנן להסבר זה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 ש\u0003לא ירד מבול לארץ ישראל,\u0004 ולשיטתו היה הראם עצמו בזמן המבול עומד בארץ ישראל! ומשיבים: אכן ר' יוחנן לא נזקק לכך, ורק \u0003לדברי ריש לקיש קאמר\u0004 \u0005[הוא אומר],\u0006 שכך יש להסביר לשיטת ריש לקיש. ושואלים לגופו של הסבר זה: כיצד ניתן היה להשאיר את הראם כשקצה חוטמו בתוך התיבה?","\u0003והא קסגיא\u0004 \u0005[והרי היתה מהלכת]\u0006 ה\u0003תיבה\u0004 על פני המים! \u0003אמר ריש לקיש: קרניו\u0004 של הראם \u0003קשרו בתיבה\u0004 וכך הוא נסחף עימה. ומקשים עוד על הסבר זה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: אנשי דור המבול ברותחין קלקלו וברותחין נידונו,\u0004 ואם כן כיצד שרד הראם במים הרותחים?","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאי אפשר היה לשרוד במים הרותחים של המבול, ה\u0003תיבה\u0004 עצמה \u0003היכי סגיא\u0004 \u0005[כיצד היתה מהלכת]?\u0006 והרי היתה מצופה בזפת שנמסה במים רותחים! \u0003ועוד, עוג מלך הבשן,\u0004 שלפי המסורת היה מאנשי דור המבול, ושרד בחיים, \u0003היכא קאי\u0004 \u0005[איך עמד,\u0006 שרד\u0005]\u0006 בתוך המים הרותחים? \u0003אלא\u0004 בודאי יש לומר ש\u0003נס נעשה להם, שנצטננו\u0004 המים שהיו \u0003בצידי התיבה,\u0004 וכך שרדה התיבה, וגם גור הראם ועוג מלך הבשן.","וחוזרים לעיקר הדברים ושואלים: \u0003ול\u0004שיטת \u0003ר' שמעון בן לקיש,\u0004 שירד מבול בארץ ישראל, ולכן יש לחשוש בה לטומאה של אנשי המבול, \u0003נהי נמי\u0004 \u0005[אם גם כן]\u0006 ש\u0003ירד מבול לארץ ישראל, והא\u0004 \u0005[והרי]\u0006 גם לשיטתו \u0003לא פש\u0004 \u0005[נשאר]\u0006 דבר מן המתים שם! שכך \u0003אמר ריש לקיש: למה נקרא שמה\u0004 של בבל \u0003\"מצולה\"? שכל מתי מבול\u0004 שבכל העולם \u0003נצתללו\u0004 (צללו) \u0003שם.\u0004 \u0003ור' יוחנן אמר: למה נקרא שמה\u0004 של בבל \u0003\"שנער\"? שכל מתי מבול ננערו שם.\u0004 הרי שריש לקיש עצמו אמר שכל המתים במבול, ואף אלו שבארץ ישראל, שקעו בבבל! ומשיבים: מכל מקום, \u0003אי אפשר\u0004 ש\u0003לא אידבקו\u0004 \u0005[נדבקו]\u0006 מקצת ממתי המבול שבארץ ישראל בטיט שהיה אז, ונשארו בה.","כיון שהוזכרו הסברים בענין שמותיה של בבל, מוסיפים עוד, \u0003אמר ר' אבהו: למה נקרא שמה \"שנער\"? שמנערת עשיריה,\u0004 שאינם עומדים בעשירותם. ושואלים על כך: \u0003והא קחזינן דהוו\u0004 \u0005[והרי אנו רואים שיש\u0006 שם עשירים\u0005]\u0006 העומדים בעשירותם! ומשיבים: \u0003תלתא דרי לא משכי\u0004 \u0005[שלושה דורות אינם נמשכים]\u0006 בעושרם.","ועוד בענין בבל, שהגיעו לשם כל מתי המבול, \u0003אמר ר' אמי: כל האוכל מעפרה של בבל, כאילו אוכל בשר אבותיו,\u0004 שיש שם הרבה מעפר המתים. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כל האוכל מעפרה של בבל, כאילו אוכל בשר אבותיו. ויש אומרים: כאילו אוכל שקצים ורמשים,\u0004 שהרי אף הם מתו במבול, ונבלעו באדמת בבל.","שנינו במשנתנו שאם הקריב בחוץ \u0003שעיר המשתלח\u0004 של יום הכיפורים, הריהו פטור מהקרבת חוץ, משום שנאמר בענין זה: \"ואל פתח אהל מועד לא הביאו\" (ויקרא יז, ד), ושעיר המשתלח אינו ראוי ומיועד לבוא אל פתח אהל מועד.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא על המשך הכתוב: \"להקריב קרבן לה'\" שדרשו חכמים, כי המלה \"קרבן\" באה למעט שוחט חולין בפנים, שאינו חייב על כך. ועל כך שואלים: \u0003או\u0004 שמא מן המלה \u0003\"קרבן\"\u0004 \u0003שומע אני\u0004 שדין שחיטת חוץ אמור \u0003אפילו\u0004 ב\u0003קדשי בדק הבית\u0004 שהוקדשו לצורך המקדש, ולא לשם הקרבה על המזבח, \u0003ש\u0004הרי גם הם \u0003נקראו \"קרבן\", ש\u0004כך \u0003נאמר\u0004 בשלל מלחמת מדין: \u0003\"ונקרב את קרבן ה'\u0004 איש אשר מצא כלי זהב אצעדה וצמיד טבעת עגיל וכומז לכפר על נפשותינו\" (במדבר לא, נ) והם בודאי אינם קדשי מזבח!","\u0003תלמוד לומר: \"ואל פתח אהל מועד לא הביאו\"\u0004 (ויקרא יז, ד) ללמדנו שדין זה נוהג דווקא ב\u0003מי שראוי לבא ב\u0004פתח \u0003אהל מועד,\u0004 שעומד להקרבה. \u0003יצאו\u0004 מכלל דין זה \u0003קדשי בדק הבית שאינן ראוין\u0004 להקרבה.","וממשיכים לדון, \u0003אוציא\u0004 מכלל דין שחיטת חוץ \u0003את אלו\u0004 את קדשי בדק הבית, \u0003שאינן ראוין\u0004 לבוא בפתח אהל מועד, \u0003ולא אוציא את שעיר המשתלח, ש\u0004הרי \u0003הוא ראוי לבא אל פתח אהל מועד!\u0004 \u0003תלמוד לומר:\u0004 \"להקריב קרבן \u0003לה'\" להוציא שעיר המשתלח,\u0004 שאין חייבים על שחיטתו בחוץ מפני \u0003שאינו מיוחד\u0004 להקרבה \u0003לה',\u0004 שהרי משלחים אותו לעזאזל. הרי שלפי ברייתא זו שעיר המשתלח ראוי לבוא אל פתח אהל מועד!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 ששנינו בברייתא שהוא ראוי לבוא אל פתח אהל מועד, הרי זה \u0003קודם הגרלה,\u0004 שהרי מכניסים את שני שעירי יום הכיפורים לעזרה, והכהן עושה הגרלה איזה קרב לה' ואיזה לעזאזל. ואילו \u0003כאן\u0004 במשנתנו, ששנינו שאין הוא ראוי לבוא אל פתח אהל מועד, הרי זה \u0003לאחר הגרלה,\u0004 שמעתה שוב אינו ראוי למקדש. ושואלים על כך: \u0003אחר הגרלה נמי\u0004 \u0005[גם כן]\u0006 עדיין ראוי לפנים הוא, שהרי \u0003האיכא\u0004 \u0005[ישנה]\u0006 מצות \u0003וידוי,\u0004 שהכהן הגדול מתוודה עליו בעזרה!","\u0003אלא אמר רב מני, לא קשיא\u0004 \u0005[אין\u0006 זו הסתירה שבין המשנה לברייתא \u0005קשה],\u0006 שכך יש להסביר: \u0003כאן\u0004 בברייתא ששנינו בה ששעיר המשתלח ראוי לפתח אהל מועד, הרי זה \u0003קודם וידוי\u0004 שעדיין הוא ראוי להיות בפנים, \u0003כאן\u0004 במשנתנו ששנינו בה שאין הוא ראוי לפתח אהל מועד, הרי זה \u0003לאחר וידוי,\u0004 שמעתה שוב אין הוא ראוי להיות בפנים.","שנינו במשנתנו שהמקריב בחוץ בעל חיים \u0003הרובע והנרבע\u0004 או שאר קדשים פסולים, כגון המוקצה והנעבד ועוד, הריהו פטור על כך, משום שנאמר בדין שחיטת חוץ: \"...לא הביאו להקריב קרבן לה' לפני משכן ה'\" (ויקרא יז, ד) — שכל שאינו ראוי להקרבה במשכן ה' (משום פסולו), אין חייבים על הקרבתו בחוץ.","ושואלים: ולמה הוצרכנו ללימוד מכתוב זה? \u0003והא נמי\u0004 \u0005[וזה גם כן],\u0006 בדומה לפרה אדומה ושעיר המשתלח שנשנה דינם בראשית משנתנו, \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו \u0003מ\u0004האמור בתחילת אותו פסוק \"ואל \u0003פתח אהל מועד\u0004 לא הביאו\", שכל שאינו מיועד לבוא לפתח אהל מועד אין חייבים על הקרבתו בחוץ. אלו גם כן אינם ראויים לבוא פתח אהל מועד!"],["\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רובע ונרבע משכחת ליה\u0004 \u0005[מוצא אתה אותו],\u0006 שאין לפטור על שחיטתו בחוץ משום שאינו ראוי להבאה לפתח אוהל מועד, וכיצד? בזמן \u0003דאקדשינהו מעיקרא\u0004 \u0005[שהקדיש אותו מתחילה]\u0006 והיה איפוא ראוי להבאה למקדש, ושוב אין לפטור על שחיטתו בחוץ מטעם זה, \u0003והדר\u0004 \u0005[וחזר,\u0006 ושב\u0005]\u0006 אחרי כן ו\u0003רבעו.\u0004","\u0003אלא\u0004 לגבי \u0003מוקצה ונעבד\u0004 לא ניתן להסביר באופן זה, משום שאם כבר הוקדשו לא היו נפסלים, שכן כלל הוא ש\u0003אין אדם אוסר דבר שאינו שלו!\u0004 ומשיבים: יש אופן בו אדם יכול לאסור דבר שכבר הוקדש, והרי זה \u0003בקדשים קלים\u0004 שהקדיש בהמה לשלמים, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר: קדשים קלים ממון בעלים הוא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין הגוזל חפץ של חבירו ונשבע לשקר, שמביא אשם גזילות: \u0003\"ומעלה מעל בה'\u0004 וכחש בעמיתו\" (ויקרא ה, כא) — \u0003לרבות\u0004 זה הנשבע על \u0003קדשים קלים\u0004 של חבירו, לפי \u0003שהן\u0004 בעיקרם \u0003ממונו\u0004 של הבעלים, אלו \u0003דברי ר' יוסי הגלילי.\u0004","ומסכמים: \u0003הלכך\u0004 כל אלו המנויים במשנה, ראויים היו לבוא אל פתח אוהל מועד, אלא שנפסלו אחר כך להקרבה. \u0003רובע ונרבע\u0004 — \u0003דבר ערוה\u0004 הוא זה, שפוסל את הקרבנות, והם נאסרים גם לאחר שהוקדשו. \u0003מוקצה ונעבד\u0004 כ\u0003עבודה זרה\u0004 נאסרו בכך אף לאחר שהוקדשו — \u0003ב\u0004זמן שהיו אלה \u0003קדשים קלים\u0004 שהם ממון בעלים.","ואילו פסול \u0003אתנן ומחיר כלאים\u0004 ו\u0003יוצא דופן,\u0004 שאינם יכולים לחול על בהמות שכבר היו ראויות להקרבה — כל אלה נשנו דווקא \u0003בולדות\u0004 (עוברים) של בהמות \u0003קדשים,\u0004 שהקנה אותם כאתנן או מחיר כשהם במעי אמם. ואלו היו ראויים להקרבה כחלק מגוף הקדשים, ורק לאחר שנולדו נפסלו כשלעצמם מהקרבה. ואף שיש לשאול: כיצד יכול ליתנם כאתנן ומחיר במעי אמם, והרי קדשים הם, ואין הם שלו לאוסרם!","על כך יש להשיב: \u0003קסבר\u0004 \u0005[סבור הוא\u0006 התנא במשנתנו\u0005]\u0006 ש\u0003ולדי קדשים\u0004 רק \u0003בהוייתן\u0004 בשעה שהם נולדים הרי \u0003הן קדושים,\u0004 אבל במעי אמם עדיין חולין הם, וחל עליהם פסול אתנן או מחיר.","שנינו במשנתנו שנחלקו חכמים ור' שמעון בקדשים שהם \u0003בעלי מומין\u0004 עוברים (שאינם קבועים), שלדעת ר' שמעון עוברים על לא תעשה על הקרבתם בחוץ, מאחר ויהיו ראויים להקרבה לאחר זמן. וכן נחלקו בשני מקרים דומים — על הקרבתם בחוץ של תורים שלא הגיע זמנם, וכן בדינו של השוחט ביום אחד \u0003אותו ואת בנו,\u0004 כאשר את השני שוחט בחוץ, למרות שהוא ראוי לשחיטה רק למחרת.","ומסבירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 לשנות את מחלוקתם זו בכל האופנים הללו, משום \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק את מחלוקתם בדין \u0003בעלי מומין\u0004 עוברים, הייתי אומר שדווקא שם אומרים חכמים שפטור על הקרבתם בחוץ, \u0003משום דמאיסי\u0004 \u0005[ש\u0006הם \u0005מאוסים]\u0006 לקרבן בפנים, \u0003אבל תורין\u0004 שעדיין לא הגיע זמנם, \u0003דלא מאיסי\u0004 \u0005[שאינם מאוסים],\u0006 שהרי משיגיע זמנם יהיו ראויים להקרבה — \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003לא\u0004 כך הוא הדין, אלא \u0003דמודו\u0004 \u0005[שמודים]\u0006 בזה חכמים \u0003ליה\u0004 \u0005[לו]\u0006 \u0003לר' שמעון\u0004 שעובר על כך בלא תעשה.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 את מחלוקת חכמים ור' שמעון במשנתנו רק בדינם של \u0003תורין\u0004 שלא הגיע זמנם, הייתי אומר כי דווקא לגביהם אמר ר' שמעון שעובר על הקרבתם בחוץ בלא תעשה, \u0003משום\u0004 שהם \u0003לא\u0004 היו בגדר של \u0003חזי ואידחו\u0004 \u0005[ראויים\u0006 להקרבה \u0005ונדחו],\u0006 אלא רק טרם הגיע זמנם להקרבה. \u0003אבל בעלי מומין\u0004 עוברים, \u0003דאיחזו ואידחו\u0004 \u0005[שהיו\u0006 כבר בגדר \u0005ראויים\u0006 להקרבה \u0005ונדחו],\u0006 \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003מודה להו\u0004 \u0005[להם]\u0006 \u0003ר' שמעון לרבנן\u0004 \u0005[לחכמים],\u0006 שאינו עובר בלא תעשה על הקרבתם בחוץ, שהרי נדחו מהקרבה במקדש.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 רק את \u0003הני תרתי\u0004 \u0005[שני אלה,\u0006 בעלי מומים עוברים ותורים שלא הגיע זמנם\u0005],\u0006 הייתי אומר בשיטת חכמים שאינו עובר על הקרבתם בחוץ \u0003משום\u0004 שפסול הקרבתם הוא \u0003פסולא דגופייהו\u0004 \u0005[פסול גופם,\u0006 עצמם\u0005],\u0006 \u0003אבל\u0004 פסול הקרבה של \u0003אותו ואת בנו, דפסולא מעלמא קאתי לה\u0004 \u0005[שפסול מבחוץ\u0006 ש\u0005בא לו],\u0006 שהרי הוא כשלעצמו כשר להקרבה, ואין הוא נאסר להקרבה באותו יום אלא רק משום שבנו (או אביו) נשחט באותו היום, \u0003אימא מודו ליה רבנן\u0004 \u0005[אמור\u0006 ש\u0005מודים לו חכמים]\u0006 \u0003לר' שמעון\u0004 שבדבר זה אכן עובר הוא על הקרבתו בחוץ בלא תעשה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת אף באופן זה.","שנינו במשנתנו: \u0003שהיה ר' שמעון אומר:\u0004 כל שהוא ראוי לבוא לאחר זמן, והקריבו — הרי זה בלא תעשה. ולא פירש ר' שמעון בדבריו איזה לא תעשה הוא זה. ונפנים לברר את דבריו, \u0003מאי טעמא\u0004 \u0005[מה\u0006 בדיוק הוא ה\u0005טעם,\u0006 המקור בתורה\u0005]\u0006 לאותו לאו שציין \u0003ר' שמעון?\u0004","\u0003אמר ר' אילעא אמר ריש לקיש:\u0004 שכן \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"לא תעשון ככל אשר אנחנו עושים פה היום\u0004 איש כל הישר בעיניו. כי לא באתם עד עתה על המנוחה ואל הנחלה\" (דברים יב, ח — ט). שכך \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003משה לישראל: כי עייליתו\u0004 \u0005[כאשר אתם נכנסים]\u0006 \u0003לארץ\u0004 ישראל, \u0003ישרות,\u0004 כלומר, קרבנות שבאים מתוך מה שישר בעיני אדם, מנדבת לבו, שהם נדרים ונדבות — אותם \u0003תקריבו,\u0004 אבל \u0003חובות לא תקריבו\u0004 ואפילו במשכן שבגלגל, עד שתגיעו אל \"המנוחה\" — זו שילה, ותקריבום.","\u0003ו\u0004הרי איפוא שקרבן חובה בתקופת \u0003גלגל לגבי\u0004 (ביחס) לתקופת המשכן ב\u0003שילה, מחוסר זמן הוא, וקאמר להו\u0004 \u0005[ואומר להם]\u0006 \u0003משה: לא תעשון\u0004 אותם באותה תקופה. הרי שהמקריב מחוסר זמן עובר בלא תעשה זה של \"לא תעשון\".","\u0003אמר ר' ירמיה לר' זירא:\u0004 לפי זה נמצא שיש כאן איסור \"לא תעשה\" כללי להקריב מחוסר זמן אפילו במשכן, כפי שהיה בגלגל, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כל המקריב מחוסר זמן, ואפילו בפנים,"],["\u0003מילקי נמי לילקי\u0004 \u0005[שילקה גם כן]\u0006 על כך, כעל כל איסור לאו בתורה שיש בו מעשה. \u0003אלמה\u0004 \u0005[מפני מה]\u0006 \u0003אמר ר' זירא\u0004 בדינו של השוחט מחוסר זמן בפנים, שאין לוקים על כך משום האיסור הכללי של פסולי ההקרבה \"לא ירצה\" (ויקרא כב, כג), לפי ש\u0003הכתוב נתקו\u0004 \u0003ל\u0004כלל איסור \u0003עשה\u0004 \"מיום השמיני והלאה ירצה\" (ויקרא כב, כז) שעליו אין לוקים? והרי עדיין קיים לאו זה של \"לא תעשון\"!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר ר' זירא, הינם רק \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' שמעון במשנתנו, והם סבורים שאין ללמוד מ\"לא תעשון\" מצוות לא תעשה על שחיטת מחוסר זמן. ואולם \u0003לר' שמעון הכי נמי\u0004 \u0005[\u0006אכן \u0005כך\u0006 הוא \u0005גם כן\u0006 הדין\u0005],\u0006 שלוקים על שחיטת מחוסר זמן בפנים המקדש.","\u0003רב נחמן בר יצחק אמר:\u0004 דברי ר' זירא הינם אף לשיטת ר' שמעון, שאף הוא סבור שאין לוקים על שחיטת מחוסר זמן במקדש. ואין ללמוד מאיסור לאו שנאמר על תקופת המשכן בגלגל, משום ש\u0003פנים\u0004 המשכן ב\u0003גלגל לגבי\u0004 (ביחס) לתקופת המשכן ב\u0003שילה כחוץ דמי\u0004 \u0005[נחשב],\u0006 ומה שנאסר ב\"לא תעשון\" הריהו איפוא הקרבה של מחוסר זמן בחוץ, ולא הקרבה של מחוסר זמן בפנים.","\u0003רבה אמר: טעמיה\u0004 \u0005[טעמו,\u0006 מקור שיטתו\u0005]\u0006 של \u0003ר' שמעון\u0004 אינו מ\"לא תעשון\", כפי שלמד ריש לקיש, אלא ממקרא אחר, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: מנין לזובח\u0004 את קרבן ה\u0003פסח\u0004 שלו \u0003בבמת יחיד בשעת\u0004 \u0003איסור הבמות, שהוא\u0004 עובר על כך \u0003ב\u0004איסור \u0003לא תעשה? תלמוד לומר: \"לא תוכל לזבח את הפסח\u0004 באחד שעריך... כי אם אל המקום אשר יבחר ה' אלהיך לשכן שמו שם תזבח את הפסח...\"(דברים טז, ה — ו).","\u0003יכול אף בשעת היתר הבמות כן\u0004 הוא הדין, שאסור לזבוח את הפסח בבמת יחיד? \u0003תלמוד לומר: \"באחד שעריך\",\u0004 לומר: \u0003לא אמרתי לך\u0004 שהדבר אסור \u0003אלא בשעה שכל ישראל נכנסין בשער אחד\u0004 למקדש להביא קרבנותיהם, אבל בזמן שאין מקום מיוחד שכל ישראל חייבים להביא בו את קרבנותיהם, אינו עובר בלא תעשה אם שחט את הפסח בבמת יחיד.","ומעתה נדון בדברים אלה: \u0003אימת\u0004 \u0005[מתי]\u0006 היתה שחיטה זו של קרבן הפסח, שהוא עובר עליה ב\"לא תעשה\" בבמת יחיד בשעת איסור במות? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שהיה זה \u0003אחר חצות\u0004 היום של י\"ד בניסן, שהוא הזמן הראוי להקרבת הפסח במקדש — לא רק שעבר על לא תעשה, אלא אף \u0003כרת נמי מחייב\u0004 \u0005[גם כן\u0006 הוא \u0005מתחייב],\u0006 ככל השוחט בחוץ קדשים הראויים להיקרב במקדש! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שהקריב את הפסח בבמת יחיד ביום י\"ד בניסן \u0003קודם חצות,\u0004 כשהוא מחוסר זמן. ומכאן שעוברים על כך באיסור לא תעשה!","ודוחים את דברי רבה: \u0003לעולם\u0004 אפשר לומר ששחיטה זו של הפסח בבמת יחיד נעשתה בזמנה, \u0003לאחר חצות\u0004 יום י\"ד בניסן, \u0003ובשעת היתר הבמות\u0004 \u0003קאי\u0004 \u0005[עומד,\u0006 מדבר\u0005]\u0006 (בתקופת המשכן בגלגל ובנוב ובגבעון) ובא מקרא זה ללמדנו שאף שהותרה הקרבת נדרים ונדבות בבמת יחיד, את קרבן הפסח נאסר להקריב מחוץ לבמה הגדולה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"בשעת איסור הבמות\" קאמר\u0004 \u0005[הוא אומר\u0006 בברייתא\u0005]!\u0006 ומשיבים: כך כוונת הדברים, בתקופה שיש \u0003איסור במה לו\u0004 לענין קרבן זה של פסח, אבל יש בה \u0003היתר במה לחבירו\u0004 לקרבן אחר, של נדרים ונדבות.","שנינו במשנתנו שהמקריב בחוץ \u0003מחוסר זמן\u0004 בבעליו אינו חייב על כך, ובפרטי ענין זה נמנו הזב, והזבה, והיולדת, שהקריבו חטאתם ואשמם בחוץ בתוך ימי ספירת טהרתם. ושואלים: \u0003והני\u0004 \u0005[ו\u0006כי \u0005אלה]\u0006 \u0003בני\u0004 (חייבי) \u0003אשמות נינהו\u0004 \u0005[הם]?\u0006 \u0003אמר זעירי: תני\u0004 \u0005[שנה,\u0006 בגירסת משנתנו\u0005]\u0006 \u0003\"מצורע\" בהדייהו\u0004 \u0005[יחד איתם,\u0006 עם זב וזבה ויולדת\u0005],\u0006 ומצורע בטהרתו מביא גם אשם.","עוד שנינו במשנתנו שאם הקריבו מחוסרי הזמן את \u0003עולותיהן ושלמיהן\u0004 בחוץ — חייבים על כך. ושוב שואלים: \u0003והני\u0004 \u0005[ו\u0006כי \u0005אלה]\u0006 \u0003בני\u0004 \u0003שלמים נינהו\u0004 \u0005[הם]?\u0006 \u0003אמר רב ששת: תני\u0004 \u0005[שנה,\u0006 בגירסת משנתנו\u0005]:\u0006 \u0003\"נזיר\"\u0004 יחד עם אלו המנויים בה, והרי נזיר מביא שלמים בסוף נזירותו. ומעירים: את גירסת \u0003זעירי\u0004 במשנתנו (\"מצורע\") \u0003קבעוה תנאי\u0004 \u0005[התנאים,\u0006 שוני המשנה\u0005]\u0006 בנוסח המשנה שהיו חוזרים ושונים. ואילו את גירסת \u0003רב ששת\u0004 במשנתנו (\"נזיר\") \u0003לא קבעוה תנאי\u0004 \u0005[התנאים]\u0006 בלימודם\u0005.\u0006","שנינו במשנתנו שמי שלא מלאו ימי טהרתו, כגון מצורע, השוחט בחוץ את אשמו — הריהו פטור על כך, משום שאינו ראוי ליקרב באותה שעה. ובדין זה, \u0003אמר ר' חלקיה (דבי\u0004 \u0005[\u0006מחכמי \u0005בית\u0006 המדרש\u0005]\u0006\u0003)\u0004 של \u0003רב טובי: לא שנו אלא\u0004 ששחט את האשם בחוץ \u0003לשמו\u0004 (לשם אשם), \u0003אבל\u0004 אם שחט את האשם בחוץ \u0003שלא לשמו,\u0004 אלא לשם קרבן אחר — \u0003חייב\u0004 משום הקרבה בחוץ, \u0003הואיל וראוי ל\u0004היות מוקרב \u0003שלא לשמו בפנים\u0004 (במקדש), שהרי אשם שנשחט שלא לשמו כשר להקרבה (לעיל זבחים ב, א).","ומקשים על כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, אפילו אם שחט את האשם \u0003לשמו נמי ניחייב\u0004 \u0005[גם כן יתחייב]\u0006 משום הקרבה בחוץ, \u0003הואיל וראוי\u0004 (יכול היה) לשוחטו \u0003לשלא לשמו בפנים!\u0004 ומשיבים: כדי שייחשב האשם שנשחט בחוץ בגדר \"ראוי לפנים\", \u0003בעי\u0004 \u0005[צריך]\u0006 הוא תחילה \u0003עקירה\u0004 של שמו (שיכוון במפורש לשמו של קרבן אחר). אבל כל עוד לא נעקר שם אשם ממנו, אין הוא נחשב \"ראוי לפנים\".","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא\u0004 על דברי רב חלקיה, שאשם מחוסר זמן ראוי לפנים כששחטו שלא לשמו: \u0003וכי יש לך דבר שאינו כשר\u0004 כשהוא נעשה \u0003לשמו, וכשר\u0004 כשהוא נעשה \u0003שלא לשמו?\u0004 ומשיבים: \u0003ולא?\u0004 וכי אין דבר כזה? \u0003והרי\u0004"],["קרבן \u0003פסח בשאר ימות השנה\u0004 (שלא בי\"ד בניסן אחר חצות היום, שהוא זמן הקרבתו הראוי) \u0003אינו כשר\u0004 אם הקריבוהו אז \u0003לשמו,\u0004 \u0003ו\u0004אולם הריהו \u0003כשר\u0004 אם הקריבוהו \u0003שלא לשמו!\u0004 ודוחים את הראיה: \u0003פסח בשאר ימות השנה\u0004 \u0003שלמים נינהו\u0004 \u0005[הם\u0006 נחשבים\u0005],\u0006 ואין זה פסח שנשחט שלא לשמו.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שהמקור הבא \u0003מסייע ליה\u0004 \u0005[לו\u0006 לרב חלקיה\u0005],\u0006 שאמר כי השוחט אשם מחוסר זמן שלא לשמו בחוץ — חייב. שכך שנינו בברייתא: \u0003יכול שאני מוציא\u0004 מכלל החייבים על שחיטת קדשים בחוץ \u0003אף\u0004 את השוחט \u0003עולת מחוסר זמן בבעלים,\u0004 כגון יולדת שלא מלאו ימי טהרתה, \u0003ו\u0004כן גם השוחט \u0003אשם נזיר ואשם מצורע\u0004 כשאינם ראויים להקרבה?","\u0003תלמוד לומר\u0004 בתחילת פרשה זו: \"איש איש מבית ישראל אשר ישחט שור או כשב או עז... או אשר ישחט מחוץ למחנה\" (ויקרא יז, ג). ובא פירוט הדברים הזה ללמדנו: \u0003\"שור\"\u0004 — \u0003מכל מקום, \"כשב\"\u0004 — \u0003מכל מקום, \"עז\"\u0004 — \u0003מכל מקום,\u0004 שחייב על שחיטתם בחוץ בכל האופנים. \u0003ואילו חטאת שיירא\u0004 \u0005[שייר]\u0006 בברייתא ולא הזכיר שהשוחט אותה בחוץ חייב.","ויש לברר: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 בברייתא זו? באיזה מקרה של אשם נזיר ואשם מצורע? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 באשם שנשחט בחוץ \u0003בזמנו, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003אשם\u0004 שחייב עליו? והרי \u0003אפילו חטאת נמי\u0004 \u0005[גם כן]\u0006 חייבים על שחיטתה בחוץ בזמנה! \u0003אלא\u0004 מדובר באשם שנשחט \u0003שלא לזמנו\u0004 כאשר הנזיר או המצורע מחוסר זמן.","ונברר עוד: \u0003ובמאי\u0004 \u0005[ובמה]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששוחט אותו \u0003לשמו,\u0004 באופן זה \u0003אשם אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב\u0004 על שחיטתו בחוץ? והרי אין הוא ראוי ליקרב בפנים! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שמקריבו \u0003שלא לשמו.\u0004 ושנינו איפוא בברייתא זו שחייב על כך, כפי שאמר רב חלקיה! ודוחים: \u0003לעולם\u0004 תאמר שמדובר בברייתא באשם ששחטו בחוץ \u0003בזמנו ושלא לשמו.\u0004","\u0003ו\u0004אף שלכאורה אין צורך בריבוי מיוחד לחייב על כך, שהרי אשם שנשחט שלא לשמו כשר בפנים, ברייתא זו שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: מקשינן\u0004 \u0005[מקישים אנו]\u0006 \u0003אשם לחטאת,\u0004 בכתוב (\"כחטאת כאשם תורה אחת להם\", ויקרא ז, ז) ללמד שדינם שווה, וגם אשם שנשחט שלא לשמו פסול. ומשום כך, היה מקום לומר כי השוחט אשם שלא לשמו יהא פטור, שהרי אינו ראוי ליקרב בפנים — לכך הוצרך ריבוי הכתוב.","\u0003ו\u0004התנא בברייתא זו \u0003תנא\u0004 \u0005[שנה]\u0006 קרבן אשם, שהוא \u0003טפל\u0004 (נספח) לקרבן חטאת בדין זה, שכן הוא נלמד ממנו, \u0003ו\u0004אולם \u0003הוא הדין\u0004 ב\u0003עיקר\u0004 שהוא החטאת, שהשוחטה בחוץ שלא לשמה — חייב.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לשיטת רב חלקיה, ממה ששנינו בברייתא: \u0003יכול שאני מרבה\u0004 לחייב על שחיטה בחוץ אף את השוחט \u0003עולת מחוסר זמן בגופה\u0004 (שטרם מלאו לה שמונה ימים) \u0003ו\u0004כן את השוחט \u0003חטאת\u0004 מחוסרת זמן, \u0003בין בגופה בין בבעלים?\u0004","\u0003תלמוד לומר\u0004 בעניינו של השוחט בחוץ: \u0003\"ואל פתח אהל מועד\u0004 לא הביאו\" (ויקרא יז, ד), ללמד: ש\u0003כל\u0004 קרבן \u0003שאינו ראוי לבא בפתח אהל מועד\u0004 — \u0003אין חייבין עליהן\u0004 משום שחיטה בחוץ. ועולה וחטאת אלו אינן ראויות עתה לבוא אל פתח אהל מועד. \u0003ואילו אשם\u0004 מחוסר זמן \u0003שיירא\u0004 \u0005[שייר]\u0006 התנא ולא הזכיר, ומכאן יש להסיק שהוא חייב על שחיטתו בחוץ.","ויש לשאול: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 באיזה מקרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כששחט בחוץ את החטאת מחוסרת הזמן \u0003לשמו,\u0004 באופן זה בקרבן \u0003אשם נמי ליפטריה\u0004 \u0005[גם כן\u0006 יש \u0005לפוטרו],\u0006 שהרי מחוסר זמן הוא! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר ששחט בחוץ את החטאת מחוסרת הזמן \u0003שלא לשמו.\u0004 ובחטאת אכן הוא פטור על שחיטת חוץ, משום שהיא פסולה בפנים שלא לשמה, ואילו באשם מחוסר זמן — חייב באופן זה, משום שהוא ראוי בפנים, וכשיטת רב חלקיה.","ודוחים: אמנם \u0003לעולם\u0004 מדובר בברייתא זו בשוחט חטאת מחוסרת זמן בחוץ \u0003שלא לשמו.\u0004 \u0003ו\u0004מכל מקום אין להסיק ממנה שבאשם חייב במקרה זה, שכן יש לומר כי ברייתא זו כ\u0003ר' אליעזר היא,\u0004 ש\u0003מקיש אשם לחטאת,\u0004 ואף באשם הדין כן. ולא הזכיר התנא בברייתא אשם, משום ש\u0003תנא\u0004 \u0005[שנה]\u0006 בה חטאת, שהיא ה\u0003עיקר\u0004 (המקור) לדין פסול שלא לשמה, \u0003ו\u0004אני יודע ש\u0003כל שכן\u0004 שכך הוא הדין גם \u0003לטפל\u0004 (הנספח, הנלמד) שהוא האשם.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לשיטת רב חלקיה, \u0003דכי אתא\u0004 \u0005[ש\u0006כן \u0005כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר, תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו \u0005של]\u0006 \u0003ר' ליואי\u0004 ברייתא זו: \u0003יכול שאני מוציא\u0004 מכלל החייבים בשחיטת קדשים בחוץ \u0003אף\u0004 את השוחט \u0003עולת מחוסר זמן בבעלים,\u0004 או השוחט בחוץ \u0003אשם נזיר ואשם מצורע? מנין\u0004 שהוא חייב? והוסיף רב דימי: \u0003ונסיב להו תלמודא לחיובא\u0004 \u0005[והביאו להם\u0006 החכמים \u0005לימוד\u0006 מן הכתוב \u0005לחייב\u0006 על כך\u0005],\u0006 \u0003ו\u0004אולם \u0003לא ידענא מאי היא\u0004 \u0005[אין אני יודע מה הוא\u0006 אותו לימוד\u0005].\u0006","ומבררים: \u0003מאי תלמודא\u0004 \u0005[מה\u0006 הוא אותו \u0005לימוד]?\u0006 \u0003אמר רבינא:\u0004 מן הנאמר בתחילת פרשת שחיטת חוץ (ויקרא יז, ג): \u0003\"שור\"\u0004 — \u0003מכל מקום, \"כשב\"\u0004 — \u0003מכל מקום, \"עז\"\u0004 — \u0003מכל מקום.\u0004 על כל פנים, מכאן ראיה לשיטת רב חלקיה, כפי שהוכחנו לעיל בעמוד זה, שהברייתא עוסקת באשם מחוסר זמן שנשחט שלא לשמו. ומכאן קושיה על רב הונא החולק עליו. ותוהים: \u0003הא מאי רומיא\u0004 \u0005[מה כאן הקושיה]?\u0006 הרי ניתן להסביר את הדברים \u0003כדאמרת\u0004 \u0005[כמו שאמרת]\u0006 לעיל, שמדובר באשם שנשחט שלא לשמו בזמנו, וכשיטת ר' אליעזר!","\u0003אמר רב נחמן:\u0004 לשיטת רב דימי לא ניתן להעמיד ברייתא זו באשם שנשחט בזמנו, והראיה לכך, \u0003משום דרמי\u0004 \u0005[ש\u0006הוא \u0005משליך\u0006 מראה סתירה\u0005]\u0006 מברייתא זו ששנה \u0003תנא דבי\u0004 \u0005[החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ליואי אדתני\u0004 \u0005[על\u0006 ברייתא \u0005ששנה]\u0006 \u0003לוי: אשם נזיר ואשם מצורע ששחטן שלא לשמן\u0004 — \u0003כשירין ולא עלו לבעלים לשום\u0004 (לשם) \u0003חובה.\u0004","\u0003שחטן מחוסר זמן בבעלים, או שהיו\u0004 הכבשים \u0003בני שתי שנים\u0004 (ולא בני שנה כדינם) \u0003ושחטן\u0004 — \u0003פסולין,\u0004 ולפיכך אינו חייב על שחיטתם בחוץ, ובניגוד לברייתא שהביא תנא דבי ר' ליואי.","\u0003ומשני\u0004 \u0005[ומתרץ]\u0006 \u0003רב דימי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 ששנה שפטור על שחיטת חוץ, הרי זה מדובר כששחט את מחוסר הזמן \u0003לשמו, כאן\u0004 ששנה שחייב, הרי זה מדובר כששחט אותו \u0003שלא לשמו.\u0004","ובדומה לכך, \u0003רב אשי רמי\u0004 \u0005[משליך,\u0006 הראה סתירה\u0005]\u0006 מ\u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ששנינו בה שהשוחט בחוץ אשם מחוסר זמן הריהו פטור, על ה\u0003ברייתא\u0004 ששנינו בה שחייב, \u0003ומשני\u0004 \u0005[ומתרץ]:\u0006 \u0003כאן\u0004 (במשנתנו) ששנינו שפטור, מדובר כששחט אותו \u0003לשמו, וכאן\u0004 (בברייתא) ששנינו שחייב, מדובר כששחט אותו \u0003שלא לשמו,\u0004 וכשיטת רב חלקיה.","ואומרים: אם כן, \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם לומר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על דברי \u0003רב הונא\u0004 החולק על רב חלקיה, וסבור שהשוחט בחוץ אשם מחוסר זמן שלא לשמו, הריהו פטור?","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003רב הונא\u0004 בהסבר הברייתא: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שחייב על אשם ששחטו שלא לשמו? \u0003כגון שהפריש שתי אשמות לאחריות,\u0004 שאם יאבד אחד מהם יתכפר בשני, וקודם שהגיע זמנו שחט אחד מהם לשם עולה, ולא לשם אשם. ועל שחיטה כזו בחוץ חייב, כדין שוחט עולה בחוץ, שהרי באופן זה \u0003חד מינייהו\u0004 \u0005[אחד מהם]\u0006 שאינו עתיד להתכפר בו, כבר \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003עולה היא,\u0004"],["\u0003כ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: אשם ש\u0004מתו או שנתכפרו בעליו ו\u0003ניתק\u0004 (הוצא) \u0003לרעיה\u0004 עד שיפול בו מום, \u0003ושחטו סתם\u0004 — \u0003כשר לעולה.\u0004","\u0003המעלה\u0004 בחוץ \u0003מבשר חטאת [וכו']\u0004 פטור. ובטעמו של דין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין\u0004 \u0003למעלה\u0004 בחוץ \u0003מבשר חטאת, ומבשר אשם, ומבשר קדשי קדשים, ומבשר קדשים קלים, וממותר העומר, ושתי הלחם, ולחם הפנים, ושירי מנחות,\u0004 \u0003שפטור\u0004 אם מעלה אותם בחוץ?","\u0003תלמוד לומר\u0004 באיסור הקרבה בחוץ: \"אשר יעלה \u0003עולה\u0004 וכו' ואל פתח אהל מועד לא יביאנו\" (ויקרא יז, ח — ט), לומר: \u0003מה עולה שהיא ראויה להעלאה\u0004 למזבח, \u0003אף כל שראויה להעלאה.\u0004 וכל אלו אינם מועלים על המזבח, אלא ניתנים לכהנים.","\u0003מנין שאף היוצק\u0004 שמן על המנחה, \u0003והבולל\u0004 את המנחה בשמן, \u0003והפותת\u0004 את המנחה לפתיתים, \u0003והמולח\u0004 אותה, \u0003והמניף\u0004 אותה, \u0003והמגיש\u0004 אותה לקרן המזבח קודם קמיצה, \u0003והמסדר\u0004 את לחם הפנים על \u0003השלחן, והמטיב את הנרות\u0004 במנורה, כלומר, מסיר את הדשן, \u0003והקומץ\u0004 את הקומץ מן המנחה כדי להקטירו, \u0003והמקבל\u0004 דם קרבן \u0003בחוץ, שפטור?\u0004","\u0003תלמוד לומר: \"אשר יעלה עלה או זבח\"\u0004 (ויקרא יז, ח), \u0003מה העלאה שהיא גמר עבודה, אף כל שהוא גמר עבודה,\u0004 וכל אלה אינם גמר עבודה אלא יש עבודה אחריהם.","שנינו במשנה: \u0003עד שלא הוקם המשכן\u0004 היו הבמות מותרות ועבודה בבכורות. מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב הונא בר רב קטינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא וקא קרי\u0004 \u0005[והיה קורא]\u0006 את הפסוק האמור במעמד הר סיני: \u0003\"וישלח את נערי בני ישראל\u0004 ויעלו עולות ויזבחו זבחים וגו'\" (שמות כד, ה) ונערים אלו הם הבכורות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אסי: קרבו ופסקו,\u0004 כלומר, מאותו יום שוב לא הקריבו הבכורות.","\u0003סבר לאותוביה ממתניתין\u0004 \u0005[סבור\u0006 היה רב הונא \u0005להקשות עליו ממשנתנו],\u0006 בה מפורש שלא רק באותו יום, אלא עד שהוקם המשכן בשנה שאחר כך, היתה עבודה בבכורות. בינתיים \u0003שמעיה דקאמר משמיה\u0004 \u0005[שמע אותו\u0006 את רב חסדא \u0005שהוא אומר משמו]\u0006 של \u0003רב אדא בר אהבה: עולה שהקריבו ישראל במדבר,\u0004 קודם שהוקם המשכן, \u0003אינה טעונה הפשט\u0004 עור \u0003וניתוח\u0004 הבשר כדי להקריבו, אלא מקריבים אותה על המזבח כמות שהיא. משום כך \u0003אותביה ברייתא דשויא בכולהו\u0004 \u0005[הקשה לו מברייתא ששווה בכולם]\u0006 שניתן להקשות ממנה על שני הדברים שהביא.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עד שלא הוקם המשכן\u0004 — \u0003הבמות מותרות, ועבודה בבכורות. והכל\u0004 כל בעלי החיים \u0003כשירין להקריב\u0004 מהם — \u0003בהמה חיה ועוף, זכרים ונקבות, תמימין ובעלי מומין,\u0004 ובלבד שיהיו \u0003טהורין אבל לא\u0004 מהמינים ה\u0003טמאין.\u0004","\u0003והכל\u0004 כל מה שקרב עד שהוקם המשכן \u0003קרבו עולות. ועולה שהקריבו ישראל במדבר\u0004 עד שלא הוקם המשכן \u0003טעונה הפשט וניתוח. וגוים בזמן הזה רשאין לעשות כן\u0004 להקריב לקדוש ברוך הוא באותו אופן. הרי מפורש בברייתא זו שעד שהוקם המשכן היתה עבודה בבכורות, והעולה שהקריבו היתה טעונה הפשט וניתוח!","והשיב לו: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין בכורות, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שאמר ה' למשה בהר סיני \u0003\"וגם הכהנים הנגשים אל ה' יתקדשו\"\u0004 (שמות יט, כב) שיפרישו עצמם ולא יתקרבו אל הקדש, ודבר זה היה יום אחד לאחר שהוקרבו העולות והשלמים — \u0003ר' יהושע בן קרחה אומר:\u0004 \u0003זו פרישות בכורות\u0004 שהם היו הכהנים, \u0003רבי אומר: זו פרישות נדב ואביהוא,\u0004 שהם היו הכהנים.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי הציווי \"יתקדשו\" \u0003זו פרישות נדב ואביהוא\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 שאמר משה לאהרן לאחר מותם, ביום השמיני למילואים: \u0003\"הוא אשר דבר ה' לאמר בקרבי אקדש\"\u0004 (ויקרא י, ג), שהרי הוזהרו מלהתקרב יתר על המדה \"פן יפרוץ בהם ה'\" (שמות יט, כב).","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \"הכהנים הנגשים אל ה' יתקדשו\" \u0003זו פרישות בכורות, היכא רמיזא\u0004 \u0005[היכן נרמז\u0006 הדבר\u0005]?\u0006 היכן דיבר ה' שיתקדש בנדב ואביהו? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בציווי על חנוכת המשכן: \u0003\"ונעדתי שמה לבני ישראל ונקדש בכבדי\"\u0004 (שמות כט, מג), \u0003אל תקרי \"בכבודי\" אלא \"במכובדיי\",\u0004 באנשים המכובדים לה' יתקדש שמו, כשיתגלה במשכן.","\u0003דבר זה\u0004 \u0003אמר הקדוש ברוך הוא למשה ולא ידעו\u0004 מה עניינו \u0003עד שמתו בני אהרן. כיון שמתו בני אהרן, אמר לו: אהרן אחי, לא מתו בניך אלא להקדיש שמו של הקדוש ברוך הוא. כיון שידע אהרן שבניו ידועי\u0004 (אהובי) ה\u0003מקום הן, שתק וקבל שכר, שנאמר: \"וידם אהרן\"\u0004 (ויקרא י, ג).","\u0003וכן בדוד הוא אומר: \"דום לה' והתחולל לו\"\u0004 (תהלים לז, ז), לומר: \u0003אף על פי שמפיל לך חללים חללים, את\u0004 \u0005[אתה]\u0006 \u0003שתוק\u0004 ואל תתלונן. \u0003וכן בשלמה הוא אומר: \"עת לחשות ועת לדבר\"\u0004 (קהלת ג, ז), \u0003פעמים ששותק ומקבל שכר על השתיקה, פעמים מדבר ומקבל שכר על הדבור.\u0004","ומעירים: \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"נורא אלהים ממקדשך\"\u0004 (תהלים סח, לו)? \u0003אל תיקרי \"ממקדשך\" אלא \"ממקודשיך\", בשעה שעושה הקדוש ברוך הוא דין בקדושיו, מתיירא ומתעלה ומתהלל\u0004 על כולם. על כל פנים, אין להקשות מן הברייתא ששנינו בה שהבכורות הקריבו עד שהוקם המשכן, משום שמחלוקת תנאים יש בדבר.","\u0003אלא קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003עולה,\u0004 שנאמר בשם רב אדא בר אהבה כי עולה שהקריבו ישראל במדבר אינה טעונה הפשט וניתוח, ובברייתא שהובאה כאן מפורש להיפך! ומשיבים: \u0003תרי תנאי\u0004 \u0005[\u0006מחלוקת \u0005שני תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: כללות\u0004 עקרי התורה בלבד \u0003נאמרו בסיני, ופרטות\u0004 כל הדינים המפורטים בספר ויקרא נאמרו למשה \u0003באהל מועד,\u0004 ובכללם דין הפשט וניתוח העולה (ויקרא א, ו), ומכאן שלא נהג דין זה עד שהוקם המשכן.","\u0003ר' עקיבא אומר:\u0004 גם ה\u0003כללות ו\u0004גם ה\u0003פרטות נאמרו בסיני, ונשנו באהל מועד, ונשתלשו\u0004 לכל ישראל שוב \u0003בערבות מואב\u0004 כשחזר משה ולימד את התורה לעם (ראה דברים א, א). ולפי שיטתו גם דין ההפשט והניתוח נהג מאז מתן תורה, עד שלא הוקם המשכן.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 שנינו בברייתא: עד שלא הוקם המשכן, \u0003הכל כשירין להקריב\u0004 אותם. בהמה חיה ועוף. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב הונא,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בהקרבה שהקריב לאחר המבול: \u0003\"ויבן נח מזבח לה' ויקח מכל הבהמה הטהורה ומכל העוף הטהור\u0004 ויעל עולות במזבח\" (בראשית ח, כ). ומסבירים: \u0003\"בהמה\"\u0004 — \u0003כמשמעו,\u0004 וכן עוף. \u0003חיה\u0004 — \u0003בכלל \"בהמה\"\u0004 האמורה בכתוב היא."],["ומה ששנינו בברייתא שהיו מקריבים בהמה חיה ועוף \u0003זכרים ונקבות, תמימין ובעלי מומין,\u0004 הריהו מתייחס למה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ככלל בדיני קרבנות: דין \u0003תמות\u0004 (למעט בעלי מום) \u0003ו\u0004דין \u0003זכרות\u0004 (למעט נקבות, בקרבן עולה) נוהגים דווקא בקרבנות הבאים מן ה\u0003בהמה, ואין\u0004 דיני \u0003תמות וזכרות\u0004 נוהגים \u0003ב\u0004קרבנות הבאים מן ה\u0003עופות.\u0004","\u0003ו\u0004בקרבנות שהקריב נח בצאתו מן התיבה \u0003איתקש\u0004 \u0005[הוקשו]\u0006 \u0003בהמה לעוף\u0004 (\"מכל הבהמה הטהורה ומכל העוף הטהור\", בראשית ח, כ) ללמדנו שאף הבהמות הטהורות שהוקרבו אז היו כדין העופות, וקרבו בין זכרים ובין נקבות, בין תמימים ובין בעלי מומים.","ומוסיפים: מה ששנינו בברייתא \u0003תמימין ובעלי מומין,\u0004 הרי זה \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 בעל חיים \u0003מחוסר אבר,\u0004 ש\u0003לא.\u0004 שכן \u0003אמר ר' אלעזר: מנין למחוסר אבר שנאסר\u0004 להקרבה \u0003לבני נח? תלמוד לומר\u0004 אצל נח\u0003: \"ומכל החי מכל בשר\"\u0004 (בראשית ו, יט), ובלשון \"מכל החי\", שאינה נצרכת לעניינה, \u0003אמרה תורה:\u0004 \u0003הבא בהמה שחיין\u0004 (שקיימים ופועלים) כל \u0003ראשי איברין שלה,\u0004 ולא מחוסרת אבר, שהרי זו פסולה להקרבה.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 באה לשון זו (\"מכל החי\") \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003טריפה\u0004 שהיא בעל חיים העומד למות, ללמד שאינו כשר להקרבה! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 דין\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"לחיות זרע\u0004 על פני כל הארץ\" (בראשית ז, ג) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שהרי טריפה אינה בכלל \"לחיות זרע\", שכן אינה יולדת.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006הסבר \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003טריפה אינה יולדת,\u0004 ואם כן מן הפסוק \"לחיות זרע\" למדים פסול טריפה, ומן הפסוק \"ומכל החי\" למדים פסול מחוסר אבר, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003טריפה יולדת, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי גם היא בכלל \"לחיות זרע\", ומהיכן למדנו שהיא פסולה להקרבה? ומשיבים: \u0003האמר קרא\u0004 \u0005[הרי אמר הכתוב]\u0006 באותו פסוק: \"ומכל החי מכל בשר... תביא אל התיבה להחיות \u0003אתך\",\u0004 לומר: \u0003בדומין לך,\u0004 שאינם טריפה.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הוה\u0004 \u0005[היה],\u0006 ואם כן אין מכאן ראיה! ומשיבים: \"נח איש צדיק \u0003תמים\u0004 היה\" (בראשית ו, ט) \u0003כתיב ביה\u0004 \u0005[נאמר בו],\u0006 שהיה שלם (\"תמים\"), בלא פגם. ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 כוונת הלשון \"תמים\" להשמיע שהיה \u0003תמים בדרכיו!\u0004 ומשיבים: גם לשון \u0003\"צדיק\" כתיב ביה\u0004 \u0005[נאמרה בו]\u0006 באותו כתוב, וממנה למדים שהיה שלם בדרכיו.","וחוזרים ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 שתי לשונות אלה \"תמים\" ו\"צדיק\" באו ללמדנו ענין זה, שהיה נח \u0003תמים\u0004 — \u0003בדרכיו,\u0004 במידותיו, \u0003צדיק\u0004 — \u0003במעשיו.\u0004 ועדיין אפשר שלא היה שלם בגופו, אלא טריפה! ודוחים: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הוה\u0004 \u0005[היה],\u0006 \u0003מי קאמר ליה\u0004 \u0005[האם היה אומר לו]\u0006 הקדוש ברוך הוא \u0003לנח: דכוותך עייל\u0004 \u0005[\u0006בעלי חיים טריפה \u0005שכמותך הכנס]\u0006 לתיבה, \u0003שלמים לא תעייל\u0004 \u0005[תכניס]?!\u0006 אלא ודאי שנח לא היה טריפה, ופסול טריפה להקרבה נלמד איפוא מ\"אתך\".","ושואלים: \u0003ומאחר דנפקא לן\u0004 \u0005[שיוצא\u0006 שנלמד \u0005לנו]\u0006 פסול טריפה \u0003מ\"אתך\",\u0004 אם כן הכתוב \u0003\"לחיות זרע\" למה לי?\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שהכתוב \u0003\"אתך\"\u0004 כוונתו לומר שנח יביא בעלי חיים אלה לתיבה \u0003ל\u0004צורך \u0003צותא בעלמא\u0004 \u0005[חברה בלבד],\u0006 ולכן ייתכן שיהיו בכלל אלה \u0003אפילו\u0004 בעל חיים \u0003זקן\u0004 וכן \u0003אפילו סריס,\u0004 שאינם ראויים להולדה, כל עוד אינם בגדר טריפה, ולכן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב \"לחיות זרע\" — דווקא כאלה שראויים להחיות זרע, ואין זקן וסריס בכללם.","ועוד שנינו בברייתא כי עד שלא הוקם המשכן הוקרבו בהמה חיה ועוף \u0003טהורין אבל לא טמאין.\u0004 והוא כפי שנאמר לגבי בעלי החיים שהקריב נח בצאתו מן התיבה: \"מכל הבהמה הטהורה ומכל העוף הטהור\" (בראשית ח, כ). ושואלים: \u0003ומי הוו\u0004 \u0005[והאם היו]\u0006 \u0003טמאין וטהורין בההיא שעתא\u0004 \u0005[באותה שעה,\u0006 תקופה\u0005]\u0006 של נח? הרי אז עדיין לא היתה הבחנה זו שבין טהרה וטומאה, אלא משניתנה התורה (ראה ויקרא פרק יא)! \u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן:\u0004 לקח נח בעלי חיים \u0003מאותן שלא נעבדה בהן עבירה,\u0004 והם ה\"טהורים\".","ושואלים: \u0003מנא הוו ידעי\u0004 \u0005[מנין היו יודעים\u0006 נח ובניו\u0005]\u0006 באלו בעלי חיים נעשתה עבירה, ולא היו מכניסים אותם לתיבה? ומשיבים: \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: העבירן\u0004 נח את כל בעלי החיים \u0003לפני התיבה, כל שהתיבה קולטתן\u0004 — \u0003בידוע שהוא טהור, אין התיבה קולטתן\u0004 — \u0003בידוע שהן טמאין.\u0004","\u0003ר' אבהו אמר\u0004 הסבר אחר כיצד ידע נח אלו בעלי חיים טהורים הם, ורק אותם הכניס לתיבה: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתיאור בעלי החיים שנכנסו לתיבה: \u0003\"והבאים זכר ונקבה\u0004 מכל בשר באו\" (בראשית ז, טז), לומר: \u0003הבאין מאליהן\u0004 (מעצמם). ולא נזקק נח לברור את הטהורים מן הטמאים, כיון שרק בעלי חיים טהורים באו.","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתיאור העבודה קודם שהוקם המשכן: \u0003והכל\u0004 כל בעלי החיים \u0003קרבו עולות.\u0004 ומדייקים: \u0003עולות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 קרבו, ואילו \u0003שלמים\u0004 — \u0003לא\u0004 קרבו. ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 בקרבנות שהקריבו בהר סיני בזמן מתן תורה: \"ויעלו עולות \u0003ויזבחו זבחים שלמים לה' פרים\"\u0004 (שמות כד, ה), והיה זה קודם שהוקם המשכן! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כי כוונת הברייתא לומר: \u0003הכל קרבו,\u0004 גם \u0003עולות [ו\u0004גם \u0003שלמים.\u0004","ומקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת\u0005]\u0006 מפורשת בענין זה: \u0003אבל שלמים לא\u0004 הקריבו קודם המשכן, \u0003כי אם עולות\u0004 בלבד\u0003]. עולות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלמים\u0004 — \u0003לא!\u0004 ומשיבים: ברייתא זו סבורה \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003לא קרבו\u0004 (הקריבו) \u0003שלמים בני נח. דאיתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שנחלקו אמוראים בדבר: \u0003ר' אלעזר ור' יוסי בר חנינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: קרבו [שלמים בני נח], וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא קרבו.\u0004","ומבררים את הדעות הללו: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם,\u0006 המקור בתורה, \u0005של מי שאומר]\u0006 ש\u0003קרבו שלמים בני נח? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבל הביא גם הוא מבכורות צאנו ומחלבהן\"\u0004 (בראשית ד, ד), הרי שבנוסף לבכורות צאנו, הביא גם חלב מן הצאן. ויש לדון בדבר: \u0003איזהו דבר\u0004 (קרבן) \u0003שחלבו קרב לגבי מזבח ואין כולו קרב לגבי מזבח? הוי אומר: זה שלמים,\u0004 שבשרם נאכל.","ומן הצד האחר, \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם,\u0006 המקור בתורה, \u0005של מי שאומר]\u0006 ש\u0003לא קרבו\u0004 בני נח שלמים? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"עורי צפון ובואי תימן...\u0004 יבא דודי לגנו ויאכל פרי מגדיו\" (שיר השירים ד, טז), לומר: \u0003תתנער\u0004 (תצא ממקומה) \u0003אומה\u0004 \u0003שמעשיה\u0004 (שקרבנותיה) אינם אלא \u0003בצפון\u0004 (כלומר, עולה, ששחיטתה וקיבול דמה נעשים בצפון העזרה), כלומר, אומות העולם, בני נח, \u0003ותבוא\u0004 במקומה \u0003אומה\u0004 ישראלית \u0003שמעשיה\u0004 (קרבנותיה) \u0003בצפון ובדרום\u0004 שהיא מקריבה גם עולות הנעשות בצפון, וגם שלמים הנעשים בדרום, שכן כל העזרה כשירה להם.","ושואלים: \u0003ומר נמי\u0004 \u0005[וחכם זה,\u0006 הסבור שבני נח לא הקריבו שלמים, \u0005גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ומחלבהן\",\u0004 ומשם למדנו שהקריב הבל שלמים! ומשיבים: \"ומחלביהן\" אין כוונתו שהקריב מן החלב שלהן, אלא שהקריב \u0003משמניהן [דידהו\u0004 \u0005[שבהם]\u0006\u0003]\u0004 (מהשמנים, המובחרים ביותר).","ומן הצד האחר, שואלים: \u0003ומר נמי\u0004 \u0005[וחכם זה,\u0006 הסבור שבני נח מקריבים שלמים, \u0005גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"עורי צפון\"\u0004 ומשם למדנו לענין אומות העולם שאינן מקריבות שלמים! ומשיבים: לשיטת חכם זה, \u0003[ההוא\u0004 \u0005[אותו]\u0006 מקרא\u0003] בקיבוץ גליות הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שיבואו גולי ישראל מן הצפון ומן הדרום.","ומקשים עוד על הסבור שבני נח לא הקריבו שלמים, \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויאמר משה\u0004 (לפרעה) \u0003גם אתה תתן בידינו זבחים ועלת ועשינו לה' אלהינו\"\u0004 (שמות י, כה), הרי שעוד לפני מתן תורה הקריבו \"זבחים\", כלומר, שלמים! ומשיבים: \u0003\"זבחים\"\u0004 כוונתם בהמות \u0003ל\u0004צורך \u0003אכילה,\u0004 \u0003ו\"עולות\" להקרבה.\u0004","ומקשים עוד: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 קודם מתן תורה \u0003\"ויקח יתרו [חתן משה] עולה וזבחים\u0004 לאלהים\" (שמות יח, יב), ו\"זבחים\" האמורים שם הינם קרבנות. והרי שהקריבו שלמים! ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב \u0003לאחר מתן תורה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ואז הותרה הקרבת שלמים לבני ישראל.","ושואלים על כך: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003[\u0004שהמעשה ב\u0003יתרו] אחר מתן תורה היה,\u0004 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003[\u0004שמעשה \u0003יתרו] קודם מתן תורה היה,\u0004 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003דאיתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 ש\u0003בני ר' חייא ור' יהושע בן לוי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: יתרו קודם מתן תורה היה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: יתרו אחר מתן תורה היה!\u0004 ומשיבים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003יתרו קודם מתן תורה היה, קסבר\u0004 \u0005[סבור הוא]\u0006 אכן ש\u0003שלמים הקריבו בני נח.\u0004","ומעירים כי ענין זה שנחלקו בו אמוראים, מתי בא יתרו להר סיני, הריהו שנוי \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים].\u0006 שכך נאמר ביתרו לפני בואו להר סיני: \u0003\"וישמע יתרו כהן מדין...\u0004 את כל אשר עשה אלהים למשה ולישראל עמו כי הוציא ה' את ישראל ממצרים\" (שמות יח, א), ויש לברר \u0003מה שמועה שמע ובא ונתגייר? ר' יהושע אומר: מלחמת עמלק שמע, שהרי כתיב\u0004 \u0005[נאמר]\u0006 \u0003בצדו\u0004 (בסמוך לפסוק זה): \u0003\"ויחלש יהושע את עמלק ואת עמו לפי חרב\"\u0004 (שמות יז, יג).","\u0003ר' אלעזר המודעי אומר: מתן תורה שמע [ובא]. שכשניתנה תורה לישראל היה קולו\u0004 של הקדוש ברוך הוא \u0003הולך מסוף העולם ועד סופו,\u0004 \u0003וכל [מלכי] אומות העולם אחזתן רעדה\u0004 \u0003בהיכליהן ואמרו שירה, ש\u0004כן \u0003נאמר:\u0004 \"קול ה' יחולל אילות... \u0003ובהיכלו כולו אומר כבוד\"\u0004 (תהלים כט, ט). כלומר, כל אחד מן המלכים אילי הארץ, אומר בהיכלו כבוד ושירה לקדוש ברוך הוא.","באותה שעה \u0003נתקבצו כולם\u0004 כל המלכים \u0003אצל בלעם הרשע\u0004 שהיה גדול נביאי אומות העולם, \u0003ואמרו לו: מה קול ההמון\u0004 (הרעש הגדול) \u0003אשר שמענו, שמא מבול בא ל\u0004אבד את ה\u0003עולם? [אמר להם]:\u0004 \u0003\"ה' למבול ישב\"\u0004 (תהלים כט, י)? \u0003אמר להם\u0004 בלעם למלכים: \u0003\"וישב ה' מלך לעולם\"\u0004 (תהלים כט, י), כלומר, \u0003כבר נשבע הקדוש ברוך הוא\u0004 לאחר המבול \u0003שאינו מביא\u0004 שוב \u0003מבול לעולם,\u0004 שנאמר: \"ולא יהיה עוד המבול מים על הארץ\" (בראשית ט, יג).","\u0003אמרו לו\u0004 המלכים: שמא \u0003מבול של מים אינו מביא,\u0004 ועל כך נשבע, \u0003אבל מבול של אש מביא,\u0004 והרי באש מעניש הקדוש ברוך הוא את העמים לעתיד לבוא, \u0003ש\u0004כן \u0003נאמר:\u0004 \u0003\"כי (הנה) באש ה' נשפט\u0004 ובחרבו את כל בשר ורבו חללי ה'\" (ישעיהו סו, טז)! \u0003אמר להן\u0004 בלעם למלכים: \u0003כבר נשבע שאינו משחית כל בשר\u0004 בכל אופן, שנאמר \"לשחת כל בשר\" (בראשית ט, יג), ואף לא באש.","חזרו ושאלו אותו המלכים: \u0003ו\u0004אם כן, \u0003מה\u0004 הוא \u0003קול ההמון\u0004 (הרעש הגדול) \u0003הזה ששמענו? אמר להם: חמדה טובה יש לו בבית גנזיו, שהיתה גנוזה אצלו תשע מאות שבעים וארבעה דורות קודם שנברא העולם, וביקש ליתנה לבניו, ש\u0004כן \u0003נאמר\u0004 לאחר מכן באותו מזמור בתהלים: \u0003\"ה' עוז לעמו יתן\"\u0004 (תהלים כט, יא), ו\"עוז\" הריהו התורה, שהיא עוזם של ישראל. \u0003[מיד] פתחו כולם ואמרו: \"ה' יברך את עמו בשלום\"\u0004 (תהלים כט, יא).","ועוד בפירוש השמועה ששמע יתרו והביאתו להר סיני, \u0003ר' אליעזר אומר: קריעת ים סוף שמע ובא, ש\u0004כן \u0003נאמר\u0004 במקרה הדומה לכך, בקריעת הירדן בימי יהושע: \u0003\"ויהי כשמע כל מלכי האמרי\u0004 אשר בעבר הירדן ימה וכל מלכי הכנעני אשר על הים את אשר הוביש ה' את מי הירדן מפני בני ישראל עד עברם ... ולא היה בם עוד רוח מפני בני ישראל\" (יהושע ה, א). \u0003ואף רחב הזונה אמרה לשלוחי יהושע: \"כי שמענו את אשר הוביש ה' את מי ים סוף\"\u0004 (יהושע ב, י).","ושואלים: \u0003מאי שנא התם\u0004 \u0005[מה שונה שם\u0006 בנאמר בקריעת הירדן\u0005]\u0006 ש\u0003אמר\u0004 הכתוב: \u0003\"ולא היה בם עוד רוח\", ומאי שנא הכא דקאמר\u0004 \u0005[ומה שונה כאן\u0006 בדברי רחב, \u0005שאמר]\u0006 הכתוב \u0003\"ולא קמה עוד רוח באיש\"?\u0004"],["ומשיבים: רחב השתמשה בביטוי \"ולא קמה עוד רוח באיש מפניכם\" (יהושע ב, יא), לומר ש\u0003אפילו אקשויי נמי לא אקשו\u0004 \u0005[להתקשות גם כן לא נתקשו\u0006 איבריהם\u0005]\u0006 מפני גודל פחדם. ושואלים: \u0003ומנא\u0004 \u0005[ומנין]\u0006 \u0003ידעה\u0004 רחב? ומשיבים: שכן \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 \u0003אין לך כל שר ונגיד\u0004 באותה עת \u0003שלא בא על רחב הזונה.\u0004","ומוסיפים, שכך \u0003אמרו\u0004 חכמים בענינה של רחב: \u0003בת עשר שנים היתה כשיצאו ישראל ממצרים, וזנתה\u0004 במשך \u0003כל ארבעים שנה שהיו ישראל במדבר. אחר\u0004 כל זאת, בהיותה בת \u0003חמישים שנה,\u0004 הלכה רחב ו\u0003נתגיירה,\u0004 כשהגיעו אליה שני המרגלים. וכך \u0003אמרה: יהא מחול לי\u0004 כל מה שחטאתי בזנות \u0003בשכר\u0004 שסכנתי עצמי ב\u0003חבל חלון ופשתים\u0004 והצלתי בהם את שני מרגליו של יהושע (שכן הסתירה אותם תחילה מפני המחפשים אחריהם בפשתי העץ, ולאחר מכן הורידה אותם בחבל דרך החלון אל מחוץ לביתה. יהושע ב, ו, טו).","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא בענין הקרבת קרבנות קודם שהוקם המשכן: \u0003וגוים בזמן הזה רשאין לעשות כן,\u0004 להקריב קרבנות לה' שלא בבית המקדש, אף שבני ישראל אסורים לעשות כן. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה בראש פרשת איסור שחיטת קדשים בחוץ \u0003\"דבר\u0004 אל אהרן ואל בניו ו\u0003אל\u0004 כל \u0003בני ישראל\"\u0004 (ויקרא יז, ב), לומר: רק \u0003בני ישראל\u0004 הם ה\u0003מצווין על שחוטי חוץ, ואין הגוים מצווין על שחוטי חוץ.\u0004","\u0003לפיכך כל אחד ואחד\u0004 מן הגוים, אם רוצה, \u0003בונה לו במה לעצמו ומקריב עליה כל מה שירצה. אמר ר' יעקב בר אחא\u0004 שכך \u0003אמר רב אסי:\u0004 אף שלגוים עצמם מותר לשחוט לשם ה' בחוץ, \u0003אסור\u0004 לישראל \u0003לסייען ולעשות שליחותן\u0004 בדבר זה, משום שלנו אסור הדבר. \u0003אמר רבה: ו\u0004אולם \u0003לאורינהו להו שרי\u0004 \u0005[להורות להם\u0006 כיצד להקריב בחוץ \u0005מותר],\u0006","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003איפרא הורמיז אימיה\u0004 \u0005[אימו]\u0006 של \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 הפרסי, \u0003שדרה קורבנא\u0004 \u0005[שלחה קרבן]\u0006 \u0003לרבא,\u0004 ועם הקרבן \u0003שלחה ליה\u0004 \u0005[לו]\u0006 דברים אלה: \u0003אסקוה ניהליה\u0004 \u0005[העלו אותו לי,\u0006 עבורי\u0005]\u0006 \u0003לשם שמים. אמר להו\u0004 \u0005[להם\u0006 רבא\u0005]\u0006 \u0003לרב ספרא ולרב אחא בר הונא: זילו ודברו תרי עולמי גולאי\u0004 \u0005[לכו וקחו\u0006 לצורך זה \u0005שני נערים\u0006 גוים בני גיל אחד\u0005],\u0006 דומים זה לזה, כדי שתהא הקרבה זו ביתר טהרה ונוי, \u0003וחזו היכא דמסקא ימא\u0004 \u0005[וראו מקום היכן שהים מעלה]\u0006 זה עתה \u0003שירטון\u0004 (תלולית של טיט), ויהא זה איפוא מקום שלא השתמש בו אדם לפני כן, \u0003ושקלו ציבי חדתי, ואפיקו נורא ממרא חדתא\u0004 \u0005[וקחו עצים\u0006 לשריפה \u0005חדשים, והוציאו אש מכלי חדש],\u0006 \u0003ואסקוה ניהליה\u0004 \u0005[והעלו אותה לפניה]\u0006 \u0003לשם שמים,\u0004 ואותם שני נערים יקריבו עליה את הקרבן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 הוראה זו להשתמש להקרבה דווקא בעצים חדשים, \u0003כ\u0004דעת \u0003ר' אלעזר בן שמוע?\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003ר' אלעזר בן שמוע אומר: מה מזבח\u0004 הוא מקום \u0003שלא ישתמש בו הדיוט\u0004 תחילה, \u0003אף עצים\u0004 העומדים להקרבה צריך \u0003שלא ישתמש בהן הדיוט. ו\u0004אולם יש להקשות על כך: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מודה ר' אלעזר בן שמוע בבמה\u0004 שאין בה צורך בעצים חדשים!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003כתוב אחד אומר\u0004 בענין קניית מקום המקדש בידי דוד כשרצה לבנות שם מזבח במצות ה': \u0003\"ויתן דוד לארנן במקום שקלי זהב משקל שש מאות.\u0004 ויבן שם דויד מזבח לה' ויעל עולות ושלמים\" (דברי הימים א כא, כה — כו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"ויקן דוד את הגרן ואת הבקר בכסף שקלים חמשים.\u0004 ויבן שם דוד מזבח לה' ויעל עולות ושלמים\" (שמואל ב כד, כד — כה), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מיישבים את הסתירה שבין הפסוקים הללו ביחס לסכום הכסף שנתן דוד?","היה דוד \u0003גובה מכל שבט ושבט\u0004 משנים עשר שבטי ישראל \u0003חמשים\u0004 שקלים, \u0003שהן\u0004 בסך הכל \u0003שש מאות\u0004 שקלים. \u0003רבי אומר משום\u0004 (בשם) \u0003אבא יוסי בן דוסתאי\u0004 הסבר אחר: את ה\u0003בקר [ועצים] ומקום מזבח\u0004 קנה דוד \u0003בחמשים\u0004 שקלים, \u0003ו\u0004את מקום \u0003כל הבית כולו\u0004 קנה \u0003בשש מאות\u0004 שקלים.","\u0003ר' אלעזר בן שמוע אומר:\u0004 את ה\u0003בקר ועצים ומקום מזבח\u0004 קנה דוד \u0003בחמשים\u0004 שקלים, \u0003ו\u0004אילו את מקום \u0003כל הבית כולו\u0004 קנה \u0003בשש מאות\u0004 שקלים. ומנין שקנה ממנו את הבקר והעצים? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ארונה אל דוד יקח ויעל אדוני המלך הטוב בעיניו ראה הבקר לעלה והמרגים וכלי הבקר לעצים\"\u0004 (שמואל ב כד, כב), ועל כך השיב דוד: \"לא כי קנה אקנה מאותך במחיר... ויקן דוד את הגורן ואת הבקר בכסף שקלים חמשים\" (שמואל ב כד, כד). על כל פנים גם לשיטת ר' אלעזר בן שמוע קנה דוד את המוריגים ואת כלי הבקר של ארונה לשם עצים! \u0003ורבא אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 בתשובה לשאלה זו: \u0003התם נמי בחדתי\u0004 \u0005[שם\u0006 אצל דוד המלך \u0005גם כן\u0006 מדובר \u0005בחדשים]\u0006 שלא השתמשו באותם כלים לפני כן.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"מרגים\"\u0004 הנזכרים שם? \u0003אמר עולא:\u0004 הוא הדבר שנקרא \u0003מטה של טורבל.\u0004 ושואלים על הסבר זה, \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"מטה של טורבל\"? אמר אביי: עיזא דקרקסא דדיישן דישאי\u0004 \u0005[לוח כבד ומשונן שדשות בו בהמות הדייש].\u0006 \u0003אמר אביי: מאי קרא\u0004 \u0005[מהו הפסוק]\u0006 המלמד את זה? שנאמר: \u0003\"הנה שמתיך למורג חרוץ חדש בעל פיפיות\u0004 תדוש הרים ותדוק וגבעות כמוץ תשים\" (ישעיהו מא, טו). הרי שמורג יש בו חריצים (\"חרוץ\") ושיניים (\"פיפיות\"), והוא משמש לדישה.","ובענין זה של הסתירה בכתובים במנין השקלים שנתן דוד, מסופר: \u0003מקרי ליה\u0004 \u0005[היה מלמד אותו מקרא]\u0006 \u0003רבא לבריה\u0004 \u0005[את בנו],\u0006 \u0003ורמי ליה קראי אהדדי\u0004 \u0005[והשליך לו פסוקים זה על זה],\u0006 הראהו שיש בהם סתירה, \u0003כתיב\u0004 \u0005[נאמר]\u0006 בדברי הימים (דברי הימים א כא, כה): \u0003\"ויתן דוד לארנן...\u0004 שקלי זהב משקל שש מאות\", \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בספר שמואל (שמואל ב כד, כד): \u0003\"ויקן דוד...\u0004 בכסף שקלים חמישים\", \u0003הא כיצד\u0004 ניתן ליישבה? \u0003גובה מכל שבט ושבט חמשים\u0004 שקלים, \u0003שהן\u0004 בסך הכל \u0003שש מאות\u0004 שקלים.","ושואלים: \u0003ואכתי קשיין אהדדי\u0004 \u0005[ועדיין קשים,\u0006 סותרים המקראות הללו, \u0005זה את זה],\u0006 שכן, \u0003התם\u0004 \u0005[שם,\u0006 בספר שמואל\u0005]\u0006 מצויין כי היו אלה שקלי \u0003כסף,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בספר דברי הימים\u0005]\u0006 מצויין כי היו אלה שקלי \u0003זהב!\u0004 ומתרצים: \u0003אלא הכי קאמר\u0004 \u0005[כך אומר]\u0006 הכתוב, באופן שאין בו סתירה בין התיאורים הללו: \u0003גובה\u0004 היה דוד המלך מכל שבט בישראל שקלי \u0003כסף במשקל\u0004 חמישים שקלי זהב, ובאופן שהגיע בסך הכל ל\u0003שש מאות\u0004 שקלי \u0003זהב.\u0004","שנינו במשנה כי משהוקם המשכן במדבר \u0003קדשים קלים נאכלים בכל מחנה ישראל. אמר רב הונא:\u0004 הכוונה היא שקדשים קלים נאכלו \u0003בכל מקומות\u0004 ששהו בהם \u0003ישראל,\u0004 \u0003אבל מחנה\u0004 ממש, שמחוץ לו אסורה האכילה, \u0003לא הוי\u0004 \u0005[היו].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא: ו\u0004כי \u0003מחנות ב\u0004זמן שהיה עם ישראל ב\u0003מדבר לא הואי\u0004 \u0005[היו]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כשם ש\u0004היה \u0003מחנה במדבר,\u0004 שיש בו אזורים חלוקים זה מזה בדינם, לענין אכילת קדשים ולענין הטמאים האסורים להיכנס לכל אחד מהם, \u0003כך\u0004 יש \u0003מחנה בירושלים,\u0004 ובאופן זה: התחום ש\u0003מ\u0004חומת \u0003ירושלים להר הבית\u0004 — הרי זה בגדר \u0003מחנה ישראל,\u0004 התחום ש\u0003מהר הבית לשער נקנור\u0004 שבפתח העזרה — הרי זה \u0003מחנה לויה,\u0004","\u0003מכאן ואילך\u0004 מפתח העזרה ופנימה — הרי זה \u0003מחנה שכינה, ו\u0004גבול העזרה \u0003הן הן\u0004 התחום שלפנים מן ה\u0003קלעים\u0004 של חצר המשכן \u0003שבמדבר!\u0004","ומתרצים \u0003אלא אימא\u0004 \u0005[אמור]\u0006 והסבר את דברי רב הונא כך: בזמן המשכן במדבר, קדשים קלים נאכלים \u0003בכל מקום\u0004 בו היה מצוי \u0003מחנה ישראל.\u0004 ושואלים על כך: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שבכל מקום שהיו בו ישראל במדבר, הרי הוא מחנה ישראל! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שבעת נסיעתם במדבר, בין חניה לחניה, הרי יצאו בכך הקדשים הקלים אל מחוץ למחנה ישראל, ולכן \u0003איפסלו\u0004 \u0005[נפסלו]\u0006 \u0003ב\u0004פסול \u0003יוצא, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב הונא שאין בשר הקדשים נפסל ביוצא.","ושואלים על כך: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 שבאמת \u0005כך\u0006 הוא \u0005גם כן]\u0006 הדין, שיש בזה פסול יוצא! ומשיבים: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתיאור מחנה ישראל לדגליו במדבר\u0005:\u0006 \u0003\"ונסע אהל מועד\u0004 מחנה הלויים בתוך המחנות, כאשר יחנו כן יסעו\" (במדבר ב, יז), לומר: \u0003אף על פי שנסע\u0004 ממקומו — \u0003אהל מועד הוא,\u0004 ובדומה לכך גם מחנה ישראל ממשיך להיקרא כן אף בעת נסיעתו.","ובענין זה ששנינו בחלוקת שלוש מחנות שהיתה בירושלים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בר יוחאי אומר: עוד\u0004 מחנה \u0003אחרת היתה\u0004 בירושלים, בתוך הר הבית עצמו, \u0003וחיל\u0004 (החומה) של \u0003עזרת נשים היא,\u0004 שאסרו חכמים על חלק מהטמאים להיכנס לשם\u0003. ולא היו עונשין עליה,\u0004 משום שמדין תורה אין לה דין מסויים לעצמו לעומת שאר הר הבית, ואף הוא בכלל מחנה לויה. ומוסיפה הברייתא: \u0003וב\u0004משכן \u0003שילה לא היו אלא שני מחנות בלבד.\u0004","ושואלים: \u0003הי מינייהו\u0004 \u0005[איזה מהם,\u0006 משלשת המחנות שהיו במדבר\u0005]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 שם? \u0003אמר רבה: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003מחנה לויה הואי\u0004 \u0005[היה]\u0006 בשילה, ולא מחנה ישראל, משום \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה\u0006 על \u0005דעתך]\u0006 לומר ש\u0003מחנה לויה לא הואי\u0004 \u0005[היה]\u0006 בשילה,"],["\u0003נמצאו\u0004 איפוא גם \u0003זבין ו\u0004גם \u0003טמאי מתים משתלחין חוץ למחנה אחת\u0004 שהוא מחנה שכינה בלבד, ומותרים שניהם (כדינם) במחנה ישראל. \u0003ו\u0004אולם הרי \u0003התורה אמרה\u0004 בדין שילוח מחנות של טמאים: \"אל מחוץ למחנה תשלחום \u0003ולא יטמאו את מחניהם\"\u0004 (במדבר ה, ג), ובאה לשון כפולה זו לומר:","\u0003תן מחנה\u0004 מיוחד \u0003לזה\u0004 לשילוחם של טמאי מתים (שהם מותרים במחנה לויה ואסורים רק במחנה שכינה), \u0003ו\u0004תן \u0003מחנה לזה\u0004 לשילוחם של זבים (שהם מותרים במחנה ישראל ואסורים במחנה שכינה ובמחנה לויה). ואם לא היה במשכן שילה מחנה לויה, נמצאו איפוא הזבים וטמאי המתים שניהם משולחים רק ממחנה אחד, ואין הבחנה ביניהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר בפירוש הדברים, ש\u0003מחנה ישראל לא הואי\u0004 \u0005[היה]\u0006 במשכן שילה? אם כן \u0003נמצאו\u0004 איפוא ה\u0003זבין ו\u0004גם ה\u0003מצורעין משתלחין\u0004 שניהם \u0003למקום אחד,\u0004 שהוא מחוץ למחנה לויה, \u0003ו\u0004אילו \u0003התורה אמרה\u0004 על המצורע: \u0003\"בדד ישב\u0004 מחוץ למחנה מושבו\" (ויקרא יג, מו), ולשון זו \"בדד\" באה להורות \u0003שלא ישב טמא אחר עמו!\u0004","\u0003אלא\u0004 יש לומר, מכח זה, כי \u0003לעולם כולהו תלתא הוו\u0004 \u0005[כל שלוש\u0006 המחנות \u0005היו]\u0006 במשכן שילה, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 מה ששנינו שבשילה \u0003\"לא היו אלא שתי מחנות\"?\u0004 הכוונה היא \u0003ל\u0004ענין \u0003קליטה,\u0004 שבמשכן שילה לא היה מחנה לויה קולט את הרוצח בשגגה. ותוהים: האם \u0003מכלל\u0004 תירוץ זה ניתן להסיק כי במשכן ש\u0003במדבר הואי קלטה\u0004 \u0005[היתה קולטת]\u0006 \u0003מחנה לויה\u0004 את הרוצחים?","ומשיבים: \u0003אין\u0004 \u0005[\u0006אכן \u0005כן],\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על האמור בדין עיר מקלט לרוצח בשגגה: \"ושמתי לך מקום אשר ינוס שמה\" (שמות כא, יג), אמר הקדוש ברוך הוא למשה \u0003\"ושמתי לך מקום\"\u0004 להשמיעו כי עוד \u0003בחייך\u0004 יהיה הדבר, ואף לפני שיכנסו ישראל לארץ. ואמר לו: \"לך \u0003מקום\"\u0004 — שזה הוא \u0003מקומך\u0004 עתה, שהוא מחנה לויה. ועל אותו מקום נאמר \u0003\"אשר ינוס שמה\",\u0004 נמצא הכתוב \u0003מלמד שמגלין\u0004 את הרוצח בשגגה גם \u0003במדבר,\u0004 ו\u0003להיכן גולין? למחנה לויה.\u0004 ואף בלויים הדין כן, שהם גולים למחנה לויה.","\u0003מכאן אמרו\u0004 חכמים: \u0003בן לוי שהרג\u0004 בשגגה, וחייב הוא בגלות — \u0003גולה מפלך לפלך,\u0004 כלומר, מעיר לויים אחת לעיר אחרת. \u0003ואם גלה ל\u0004מקום אחר ב\u0003פלכו\u0004 — גם \u0003פלכו קולטו.\u0004","ושואלים: \u0003מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 נאמר בדין עיר מקלט לרוצח בשגגה \u0003\"כי בעיר מקלטו ישב\"\u0004 (במדבר לה, כח) — \u0003עיר שקלטתו כבר.\u0004","שנינו במשנתנו כי מש\u0003באו לגלגל\u0004 הותרה ההקרבה בבמות יחיד. ובפרטי ענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל\u0004 קרבן שהוא \u0003נידר ונידב\u0004 (שבא בנדר או בנדבה) — \u0003היה קרב בבמה\u0004 של יחיד, וכל קרבן \u0003שאין נידר ונידב\u0004 אלא חובה — \u0003אין קרב בבמה\u0004 של יחיד. וכיון שכך, \u0003מנחה\u0004 (סתם, שהיא באה נדבה) \u0003ו\u0004קרבנות \u0003נזירות,\u0004 שהם בגדר נדרים, שהרי אין אדם חייב להיות נזיר — \u0003קריבין בבמה.\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: לא קרבו\u0004 בבמת \u0003יחיד אלא עולות ושלמים בלבד,\u0004 אבל לא מנחה ונזירות.","\u0003ר' יהודה אומר: כל\u0004 קרבן \u0003שהצבור והיחיד מקריבין באהל מועד שבמדבר\u0004 — \u0003מקריבין\u0004 אותו גם \u0003באהל מועד שבגלגל,\u0004 ו\u0003מה\u0004 אם כן, ההבדל ש\u0003בין אהל מועד שבמדבר לבין אהל מועד שבגלגל?\u0004 שבזמן \u0003אהל מועד שבמדבר לא היו במות\u0004 יחיד \u0003מותרות,\u0004 והיו חייבים להקריב רק במשכן, ואילו בזמן \u0003אהל מועד שבגלגל היו הבמות מותרות. ו\u0004מכל מקום גם כאשר עושה ב\u0003במתו שבראש גגו,\u0004 עדיין \u0003לא היה מקריב עליה אלא עולה ושלמים.\u0004","\u0003וחכמים אומרים: כל שהצבור מקריבין באהל מועד שבמדבר\u0004 — \u0003מקריבין\u0004 גם \u0003באהל מועד שבגלגל, וכאן וכאן,\u0004 בין בגלגל ובין בבמת היחיד — \u0003לא קרבו\u0004 ל\u0003יחיד אלא עולה ושלמים בלבד,\u0004 ולא קרבנות אחרים. \u0003ר' שמעון אומר: אף צבור לא הקריבו\u0004 בבמת הציבור שבגלגל כל קרבנותיהם, \u0003אלא פסחים\u0004"],["\u0003ו\u0004כן שאר \u0003חובות\u0004 ציבור \u0003שקבוע להן זמן\u0004 מוגדר מתי הם צריכים להיות מובאים, כגון תמידים ומוספים. ואולם קרבנות חובה שאין להם זמן מוגדר להקרבתם, לא קרבו בבמה בזמן משכן גלגל.","ומעתה נפנים לברר את השיטות השונות של החכמים ששנינו בברייתא זו. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטת \u0003ר' מאיר\u0004 שלא הקריבו בבמת יחיד בתקופת המשכן בגלגל אלא קרבנות הבאים בנדר ונדבה, ובכללם מנחות ונזירות? שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין ההקרבה לכשייכנסו בני ישראל לארץ ישראל\u0005:\u0006 \u0003\"לא תעשון ככל אשר אנחנו עשים פה היום\u0004 איש כל הישר בעיניו. כי לא באתם עד עתה אל המנוחה ואל הנחלה\" (דברים יב, ח — ט).","שכך \u0003אמר להן משה לישראל: כי עייליתו\u0004 \u0005[כאשר אתם נכנסים]\u0006 \u0003לארץ\u0004 ישראל, ועדיין לא באתם למשכן שילה ולמקדש בירושלים, ומותרים אתם להקריב בבמות — לא תעשו ככל אשר אנחנו עושים במדבר, קרבנות חובה ונדבה. אלא \"איש כל הישר בעיניו\" — \u0003ישרות,\u0004 כלומר, קרבנות הבאים מנדבת (מיושר) ליבו של כל איש \u0003תקריבו,\u0004 ואילו \u0003חובות\u0004 \u0003לא תקריבו.\u0004 ואף \u0003מנחות ו\u0004קרבנות הבאים עם סיום ה\u0003נזירות\u0004 הלוא בכלל \u0003ישרות נינהו\u0004 \u0005[הם],\u0006 שהמנחות באות בנדר ונדבה, ואין נזירות אלא בנדר, ואינה חובה על האדם.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' מאיר, ולשיטתם לא הקריבו בבמות יחיד מנחות ונזירות, טעמם הוא — משום ש\u0003אין מנחה\u0004 נוהגת כלל \u0003בבמה,\u0004 ואילו קרבנות \u0003נזירות\u0004 אינם בכלל ישרות, אלא \u0003חובות נינהו\u0004 \u0005[הם].\u0006 שאמנם הנזירות עצמה היא נדר, אבל משעה שנעשה נזיר מוטלים עליו הקרבנות כחובה.","ובעניין זה, \u0003אמר שמואל: מחלוקת\u0004 ר' מאיר וחכמים הינה דווקא \u0003ב\u0004קרבנות ה\u0003חטאת ואשם\u0004 שמביא הנזיר, \u0003אבל בעולות ושלמים\u0004 שהוא מביא — \u0003דברי הכל,\u0004 ואף לדעת חכמים, בכלל \u0003ישרות\u0004 \u0003נינהו\u0004 \u0005[הם],\u0006 \u0003וקרבי\u0004 \u0005[וקרבים]\u0006 בבמת יחיד\u0005.\u0006","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבה\u0004 ממה ששנו חכמים בברייתא: \u0003חזה ושוק\u0004 של קרבנות שלמים הניתנים לכהנים לאכילה (ראה ויקרא ז, לד), \u0003ו\u0004כן \u0003תרומת לחמי תודה\u0004 (הלחם הניתן לכהן לאכילה מכל אחד מארבעת מיני לחמי התודה, ראה ויקרא ז, יד), \u0003נוהגין\u0004 רק \u0003בבמה גדולה, ואין נוהגין בבמה קטנה.\u0004 ויש מעתה לדייק: דווקא אלו אינם נוהגים בבמה קטנה, \u0003ואילו\u0004 מתנת כהנים האחרת, שהיא \u0003הזרוע בשלה\u0004 שבאיל נזיר (ראה במדבר ו, יט — כ), \u0003שיירה\u0004 \u0005[שייר אותה],\u0006 לא הזכיר אותה התנא.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שאף \u0003בעולה ושלמים פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 ר' מאיר וחכמים אם קרבו בבמת יחיד, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שלא נזכר בה איל נזיר, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שלדעתם לא קרבו שלמי נזיר. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שרק \u0003ב\u0004קרבנות ה\u0003חטאת ואשם\u0004 של הנזיר \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ושלמים ועולות של נזיר אף חכמים מודים שהקריבו בבמה, \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 דבר זה, \u0005כך נאמר],\u0006 \u0003אמר שמואל: מחלוקת\u0004 ר' מאיר וחכמים היא דווקא \u0003בעולה ושלמים\u0004 של נזיר, \u0003אבל בחטאת ואשם\u0004 — \u0003דברי הכל חובות נינהו\u0004 \u0005[הן],\u0006 \u0003ולא קרבי\u0004 \u0005[קרבים],\u0006 גם לא לדעת ר' מאיר.","ועוד בבירור דעות התנאים שבברייתא זו, \u0003אמר מר\u0004 \u0005[החכם]\u0006 ר' יהודה אומר: כל שהציבור והיחיד מקריבים באהל מועד שבמדבר — מקריבים באהל מועד שבגלגל, בין נדרים ונדבות ובין חובות. ורק בבמת יחיד לא הקריב היחיד אלא עולה ושלמים. \u0003וחכמים אומרים: כל שהצבור מקריבין באהל\u0004 מועד שבמדבר, מקריבין באהל מועד שבגלגל. אבל יחיד אינו מקריב אלא עולה ושלמים בלבד, בין בבמת יחיד ובין במת ציבור.","ומבררים את השיטות הללו, \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 הסבורים שרק ציבור הקריבו קרבנות חובה בבמה גדולה? \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי תקופת היתר הבמות: \u0003\"איש [כל] הישר בעיניו (יעשה)\"\u0004 (דברים יב, ח), לומר: לגבי \u0003איש,\u0004 אדם פרטי — \u0003ישרות,\u0004 כלומר, קרבנות נדבה \u0003הוא דליקרוב\u0004 \u0005[שיקרבו],\u0006 \u0003חובות\u0004 — \u0003לא ליקרוב\u0004 \u0005[יקרבו],\u0006 \u0003ו\u0004אילו לגבי \u0003צבור\u0004 — \u0003אפילו חובות ליקרוב\u0004 \u0005[שיקרבו].\u0006"],["\u0003ור' יהודה\u0004 הסבור שבבמה גדולה גם יחיד מקריב קרבנות חובה, \u0003אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 \u0003\"הישר\"\u0004 שרק קרבנות הבאים בנדר ונדבה (\"ישרות\") מקריב היחיד, הרי על \u0003\"בעיניו\" הוא דכתיב\u0004 \u0005[שנאמר],\u0006 כלומר, במקום שישר בעיניו להקריב, בבמת יחיד שהוא בונה לעצמו, \u0003אבל בבמה גדולה\u0004 — \u0003אפילו חובות נמי ליקרוב\u0004 \u0005[גם כן יקרבו].\u0006","ושואלים: \u0003אלא\u0004 גם אם תדייק כך, מכל מקום \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 במקרא זה \u0003\"איש\", לאו למימרא\u0004 \u0005[האם לא\u0006 בא \u0005לומר]\u0006 שלגבי \u0003איש\u0004 (יחיד) דווקא קרבנות שהם בגדר \u0003ישרות הוא דליקרוב\u0004 \u0005[שיקרבו],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 מכאן נדייק שקרבנות \u0003חובות\u0004 — \u0003לא ליקרוב\u0004 \u0005[יקרבו]?\u0006 ומשיבים: \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 \u0003\"איש\"\u0004 בכתוב זה, הריהו בא \u0003להכשיר את הזר\u0004 (מי שאינו כהן) בעבודה בבמה קטנה.","ושואלים: והרי \u0003זר\u0004 כשר לעבודה בבמה קטנה, \u0003מ\u0004הכתוב \u0003\"וזרק הכהן את הדם על מזבח ה'\u0004 פתח אהל מועד\" (ויקרא יז, ו) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שרק במזבח ה' שבמשכן (שהיה בבמה הגדולה) יש חובה שיעשה כהן את עבודות ההקרבה, ואילו בבמה קטנה כשר לכך אף זר!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 מהפסוק \"וזרק הכהן את הדם על מזבח ה'\" אמנם יש ללמוד כי אין צורך בכהן לעבודה בבמת יחיד, ואולם \u0003ליבעי\u0004 \u0005[שיצטרכו]\u0006 לשם כך \u0003קדוש בכורות,\u0004 שיפרישו אותם לשם כך, \u0003כ\u0004דרך שהיתה העבודה \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 קודם שהוקם המשכן. לכך בא הכתוב \"איש הישר בעיניו יעשה\" ו\u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכל איש עושה את קרבנותיו בבמת יחיד.","ועוד בבירור שיטת חכמים החולקים על ר' יהודה, שואלים: שיטת \u0003חכמים\u0004 \u0003היינו\u0004 \u0005[זוהי]\u0006 אף שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון,\u0006 חכמים הנזכרים בתחילת הברייתא\u0005],\u0006 שאמרו שיחידים לא הקריבו אף בבמה גדולה אלא עולות ושלמים, ומה איפוא ההבדל ביניהם?","\u0003אמר רב פפא:\u0004 בשאלה האם \u0003קרבו נסכים במדבר\u0004 עם קרבנות העולה והשלמים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלשיטת חכמים שבתחילת הברייתא לא קרבו נסכים במדבר, וגם לא בארץ ישראל בתקופת המשכן שבגלגל, עד שהוקם המקדש בשילה. ואילו לשיטת חכמים שבסוף הברייתא, קרבו נסכים במדבר, וגם בזמן הגלגל.","ועוד בבירור השיטות ששנינו בברייתא. \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 אף ציבור לא הקריבו באהל מועד שבגלגל אלא פסחים וחובות שקבוע להן זמן. ומסבירים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו,\u0006 מה המקור בתורה\u0005]\u0006 לשיטה זו של \u0003ר' שמעון? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעשו בני ישראל את הפסח בגלגל\"\u0004 (יהושע ה, י), ויש לדון בכתוב זה: מה בא להשמיענו שעשו את הפסח בגלגל?","\u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שכך עשו, שהרי זו חובה המוטלת עליהם, כמו כל קרבן אחר! \u0003אלא הא קא משמע לן\u0004 \u0005[\u0006פסוק \u0005זה משמיע לנו],\u0006 שאף שאר קרבנות שהקריבו בגלגל, קרבנות \u0003חובות כעין פסח,\u0004 שקבוע להן זמן, \u0003הוא דקרב\u0004 \u0005[שהקריבו],\u0006 \u0003הא לאו\u0004 \u0005[אבל\u0006 שאר קרבנות חובה, ש\u0005אינן]\u0006 \u0003כעין פסח\u0004 — \u0003לא קרב\u0004 \u0005[הקריבו].\u0006 ושואלים: \u0003ואידך\u0004 \u0005[והאחרים],\u0006 חכמים החולקים על ר' שמעון, וסבורים שציבור הקריבו בגלגל אף שאר קרבנות, מה עושים הם בפסוק זה?","ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004למדנו אותה הלכה שאמר \u0003ר' יוחנן,\u0004 שכך \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' בנאה:\u0004 בן ישראל שהוא \u0003ערל\u0004 ונטמא בטומאת מת, הריהו \u0003מקבל הזאה\u0004 ממי פרה אדומה ביום השלישי וביום השביעי לטהרתו, בכדי להיטהר מטומאה זו, למרות שהוא ערל. והראיה היא מכך שישראל שעשו את הפסח בגלגל כשהם טהורים מטומאת מת, לא יכולים היו לעשותו בטהרה אלא אם היזו עליהם עוד כשהיו ערלים.","ובענין פסחים וחובות שקבוע להם זמן, שהוזכרו בדברי ר' שמעון, מסופר: \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב אדא בר אהבה\u0004 ברייתא זו: \u0003אין\u0004 הבדל \u0003בין במה גדולה\u0004 כגון זו שבגלגל \u0003לבמה קטנה\u0004 שמקריב בה היחיד, \u0003אלא פסח וחובות הקבוע להן\u0004 \u0003זמן,\u0004 שמקריבים בבמה גדולה ואין מקריבים בבמה קטנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אדא בר אהבה: \u0003יחיד\u0004 קרבנות \u0003חובות שקבוע להן זמן מנא ליה\u0004 \u0005[מנין לו]?\u0006 שהרי אין קרבנות כאלו, ואין צורך להשמיענו שאינם קרבים בבמה קטנה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 חוזר המשניות: אם כן, האם \u0003אסמייה\u0004 \u0005[אמחוק אותו]\u0006 מגרסת משנתי, ולא אשנה אלא פסח? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אדא בר אהבה: אינך צריך לכך, \u0003תתרגם מתניתך\u0004 \u0005[הסבר\u0006 את \u0005משנתך]\u0006 \u0003בעולת חובה,\u0004 והיא עולת הראיה שצריך כל יחיד להביא ברגלים, והיא אינה קריבה בבמת יחיד, \u0003דאיכא\u0004 \u0005[ש\u0006לעומתה \u0005יש]\u0006 \u0003עולת נדבה,\u0004 שהיא קריבה בבמת יחיד. ודווקא בעולה של יחיד עוסקת ברייתא זו, \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר ש\u0003חטאת יחיד הוא,\u0004 וכי \u0003חובות\u0004 של חטאת \u0003דקביע ליה\u0004 \u0005[שקבוע להם]\u0006 \u0003זמן\u0004 \u0003מי איכא\u0004 \u0005[האם\u0006 בכלל \u0005יש]\u0006 ליחיד?","ומקשים: \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 הברייתא הזו \u0003במנחת חובה\u0004 של יחיד שקבוע לה זמן, \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 מנחת \u0003חביתין\u0004 שכן הכהן הגדול צריך להקריב בכל יום, והיא קריבה בבמה גדולה ולא בבמה קטנה! ומשיבים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 רב אדא בר אהבה שבכלל \u0003אין מנחה בבמה\u0004, שלא הביאו מנחה כלל אף בבמה גדולה \u0003.\u0004","שנינו במשנתנו כי כש\u0003באו\u0004 ישראל \u0003לשילה\u0004 נאסרו הבמות, ולא היתה במשכן שילה תקרה, אלא קירות של אבנים ויריעות פרוסות עליהן מלמעלה. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן, כתוב אחד\u0004 המתאר את משכן שילה \u0003אומר\u0004 כשהביאה חנה את שמואל: \u0003\"ותבאהו בית ה' שילה\"\u0004 (שמואל א א, כד), \u0003ו\u0004אילו \u0003כתוב אחד אומר: \"ויטש משכן שילה אהל שכן באדם\"\u0004 (תהלים עח, ס), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וימאס באהל יוסף ובשבט אפרים לא בחר\"\u0004 (תהלים עח, סז), אם כן מצד אחד נראה שמשכן שילה היה בית, ובפסוק אחר נראה שהיה זה אוהל,","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 תתיישב סתירה זו? כפי שנאמר במשנתנו: \u0003לא היתה שם תקרה, אלא\u0004 רק \u0003אבנים מלמטן\u0004 (ומשום כך נקרא בית), \u0003ויריעות מלמעלן\u0004 (ומשום כך נקרא אוהל). \u0003והיא\u0004 (תקופת משכן שילה) \u0003היתה\u0004 זו המכונה בתורה \u0003\"מנוחה\"\u0004 (\"כי לא באתם עד עתה אל המנוחה ואל הנחלה\", דברים יב, ט).","ועוד שנינו במשנתנו כי בתקופת משכן שילה \u0003קדשי קדשים\u0004 היו נאכלים לפנים מן הקלעים, ואילו קדשים קלים ומעשר שני היו נאכלים בכל מקום הרואה את שילה. ומבררים הלכה זו שבאכילת קדשים קלים ומעשר שני: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' אושעיא:\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באיסור הקרבה בחוץ \u0003\"השמר לך פן תעלה עלתיך בכל מקום אשר תראה\"\u0004 (דברים יב, יג), ויש לדייק בכתוב: \u0003בכל מקום אשר תראה אי\u0004 (אין) \u0003אתה מעלה, אבל אתה אוכל\u0004 את הקרבנות \u0003בכל מקום שאתה רואה.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך את דיוק הכתוב: \u0003בכל מקום שאתה רואה אי אתה מעלה\u0004 קרבנות על המזבח, \u0003אבל אתה זובח בכל מקום שתראה,\u0004 ותהא שחיטתם מותרת בכל הרואה!","\u0003אמר ר' ינאי:\u0004 אין לומר כן, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסוק שלאחריו: \"כי אם במקום אשר יבחר ה' באחד שבטיך \u0003שם תעלה\u0004 עולותיך \u0003ושם תעשה\u0004 כל אשר אנכי מצוך\" (דברים יב, יד), ללמד שבמקום בו מעלים את הקרבנות, בו נעשות כל עבודות ההקרבה, ורק אכילת קדשים קלים מותרת במקום הרואה.","\u0003ר' אבדימי בר חסא אמר\u0004 מקור אחר לכך שקדשים קלים נאכלים בכל הרואה, שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006"],["בתיאור מהלך גבול נחלתם של בני יוסף (שם שכנה שילה): \"ונסב הגבול מזרחה \u0003(ולו) תאנת שלה\"\u0004 (יהושע טז, ו), כלומר במקום הסמוך לשילה, ולמה נקרא על שם שילה? משום שהיה זה \u0003מקום שכל הרואה אותו\u0004 את מקדש שילה משם לאחר חורבנו, הריהו \u0003מתאנח\u0004 (\"תאנת\") \u0003עליו על אכילת קדשים\u0004 קלים \u0003שלו\u0004 שבטלה, שהיתה מותרת עד מקום זה.","\u0003ר' אבהו אמר\u0004 רמז אחר בכתוב, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בברכת יעקב ליוסף: \u0003\"בן פרת יוסף בן פרת עלי עין\"\u0004 (בראשית מט, כב) — \u0003עין שלא רצתה לזון וליהנות מדבר שאינו שלו\u0004 בנסיון עם אשת פוטיפר, \u0003תזכה ותאכל\u0004 קדשים קלים בשילה (שבנחלת יוסף) \u0003כמלא עיניה.\u0004","\u0003ר' יוסי בר' חנינא אמר:\u0004 רמז אחר לדבר, ממה שנאמר בברכת משה ליוסף: \u0003\"ורצון שכני סנה\"\u0004 (דברים לג, טז) — \u0003עין שלא רצתה ליהנות מדבר שאינו שלו, תזכה ותאכל בין השנואין,\u0004 כלומר, גם בנחלת השבטים האחרים ששנאו אותו (כנאמר בבראשית פרק לז), שכן קדשי משכן שילה נאכלים אף בנחלת שאר השבטים, בכל מקום הרואה.","ועוד בהלכה זו של אכילת קדשים קלים בכל הרואה בתקופת משכן שילה, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003\"רואה\"\u0004 זה \u0003שאמרו\u0004 במשנתנו, כוונתו ש\u0003רואה כולו, ולא\u0004 שיהא דבר \u0003המפסיק בינו לבינו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן אליקום לר' אלעזר: אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 למה הכוונה \u0003—\u0004 \u0003כגון בי כנישתא\u0004 \u0005[בית הכנסת]\u0006 של \u0003מעון\u0004 שהיה סמוך לעיר טבריה, וניתן היה לראותו משם. \u0003אמר רב פפא: \"רואה\" שאמרו לא\u0004 בדווקא שיהא \u0003רואה כולו\u0004 את כל משכן שילה, \u0003אלא\u0004 אף אם הוא \u0003רואה מקצתו\u0004 די בכך לאכול שם קדשים קלים.","ועוד בהגדרת מקום הרואה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם היה במקום כזה שבהיותו \u0003עומד\u0004 שם \u0003ורואה\u0004 את שילה, וכאשר הוא \u0003יושב\u0004 שם \u0003ואינו רואה\u0004 את שילה, \u0003מאי\u0004 \u0005[מה]\u0006 יהיה הדין? האם נקרא הוא \"רואה\" או לא? וכמו כן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 מקום כזה, שכאשר אדם \u0003עומד\u0004 בו \u0003על גבי הנחל\u0004 על שפתו \u0003ו\u0004אז הוא \u0003רואה\u0004 את שילה, ואולם כאשר הוא \u0003(יושב) בתוך הנחל ו\u0004אז \u0003אינו רואה, מאי\u0004 \u0005[מה]\u0006 הדין? שתי השאלות הללו לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה\u0005.\u0006","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003רבי, בשלשה מקומות שרתה שכינה על ישראל: בשילה, ונוב וגבעון, ובית עולמים, ובכולן לא שרתה\u0004 שכינה \u0003אלא בחלק\u0004 (בנחלת) שבט \u0003בנימין. ש\u0004כך \u0003נאמר\u0004 לבנימין בברכת משה: \"ידיד ה' ישכון לבטח עליו \u0003חפף עליו כל היום\u0004 ובין כתפיו שכן\" (דברים לג, יב), לומר: ש\u0003כל חפיפות\u0004 (השראת שכינה) בישראל \u0003לא יהו אלא בחלקו של בנימין.\u0004","ובענין זה נמסר, \u0003כי אזיל\u0004 \u0005[כאשר הלך]\u0006 \u0003אביי\u0004 ללמוד תורה לפני רב יוסף \u0003אמרה\u0004 לשמועה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף, אמר\u0004 רב יוסף על כך: \u0003חד ברא הוה ליה\u0004 \u0005[בן אחד היה לו]\u0006 \u0003לכייליל\u0004 אביו של אביי, \u0003ולא מיתקן\u0004 \u0005[ואינו מתוקן],\u0006 כלומר, כיצד ניתן לומר דבר כזה? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 אודות משכן שילה \u0005:\u0006 \u0003\"ויטש משכן שילה\"\u0004 (תהלים עח, ס), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך: \u0003\"וימאס באהל יוסף ובשבט אפרים לא בחר\"\u0004 (תהלים עח, סז), משמע שמשכן שילה היה בנחלת יוסף ולא בנחלת בנימין!","\u0003אמר רב אדא: מאי קא קשיא ליה\u0004 \u0005[מה היה קשה לו\u0006 לרב יוסף\u0005]\u0006 ממקרא זה? \u0003דלמא\u0004 \u0005[שמא]\u0006 היה המשכן גם בנחלת בנימין וגם בנחלת יוסף, ה\u0003שכינה\u0004 היתה \u0003בחלק בנימין, ו\u0004אילו ה\u0003סנהדרי גדולה\u0004 שצריכה לשבת סמוך למקום השכינה, היתה \u0003בחלק יוסף. מדמצינו\u0004 \u0005[כמו שמצאנו]\u0006 \u0003בבית עולמים\u0004 (בבית המקדש), שהיתה ה\u0003שכינה בחלקו של בנימין וסנהדרין בחלק יהודה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בבית המקדש בירושלים\u0005]\u0006 \u0003מיקרבן\u0004 \u0005[קרובות]\u0006 היו \u0003נחלות\u0004 בנימין ויהודה \u0003גבי הדדי\u0004 \u0005[זו לזו],\u0006 ולכן יכולה להיות חלוקה שכזו, שבית המקדש בנחלת שבט אחד והסנהדרין בנחלת שבט אחר, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בשילה\u0005]\u0006 \u0003מי מקרבן\u0004 \u0005[האם\u0006 הן \u0005קרובות],\u0006 שילה ונחלת בנימין? ומשיבים: \u0003הכא נמי מקרבן\u0004 \u0005[כאן גם כן\u0006 יש לומר שהן \u0005קרובות],\u0006 כי \u0003כ\u0004שם ש\u0003אמר ר' חמא בר' חנינא: רצועה היתה יוצאת מחלקו של יהודה ונכנסת לחלקו של בנימין, ובה היה מזבח בנוי, והיה בנימין הצדיק מצטער עליה לבלעה,\u0004 שגם המזבח כולו יהיה בתחום נחלתו.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במשכן שילה, יש לומר כי \u0003רצועה היתה יוצאת מחלקו של\u0004 \u0003יוסף לחלקו של בנימין,\u0004 שחיברה את שילה לנחלת בנימין. ובתחום אותה רצועה, שנחשבה כחלק מנחלת בנימין, עמד חלק ממשכן שילה. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 בתיאור גבול נחלת בני יוסף: \"ונסב הגבול מזרחה \u0003תאנת שלה\"\u0004 (יהושע טז, ו), שלפי הסבר זה יש לפרשו שהיה שבט בנימין מתאונן (\"תאנת\") על שאין כל תחום משכן שילה בתחומו.","ומעירים: מחלוקת זו שבין האמוראים בתחום איזה שבט היה שרוי משכן שילה, הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 בענין זה, שכן שנינו: מה שנאמר בברכת משה לבנימין: \u0003\"חפף עליו\"\u0004 — \u0003זה מקדש ראשון, \"כל היום\"\u0004 — \u0003זה מקדש שני, \"ובין כתפיו שכן\"\u0004 — \u0003אלו ימות המשיח,\u0004 ואילו","\u0003רבי אומר: \"חופף עליו\"\u0004 — \u0003זה העולם הזה, \"כל היום\"\u0004 — \u0003אלו ימות המשיח, \"ובין כתפיו שכן\"\u0004 — \u0003זה העולם הבא.\u0004 הרי שלדעת חכמים שרתה שכינה בתחום שבט בנימין החל מבית ראשון והלאה, ולא בתקופת משכן שילה, שאז היתה בנחלת יוסף. ואילו לדעת רבי שרתה השכינה בנחלת בנימין בכל ימי העולם הזה, ובכלל זה גם בשילה.","ובענין אורך התקופות השונות שהוזכרו במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ימי אהל מועד שבמדבר\u0004 היו \u0003ארבעים שנה חסר אחת. ימי אהל מועד ש\u0004היה \u0003בגלגל\u0004 — \u0003ארבע עשרה\u0004 שנה, שהן \u0003שבע\u0004 שנים \u0003שכבשו\u0004 בהן בני ישראל את הארץ, \u0003ושבע\u0004 שנים \u0003שחלקו\u0004 בהן אותה לשבטים. \u0003ימי אהל מועד שבנוב וגבעון\u0004 עד שהוקם המקדש בירושלים — \u0003חמשים ושבע\u0004 שנים. והואיל והמקדש הוקם ארבע מאות ושמונים שנה ליציאת מצרים (מלכים א ו, א), נמצא כי \u0003נשתיירו ל\u0004תקופת המשכן ב\u0003שילה שלש מאות ושבעים חסר אחת.\u0004","ומעתה דנים בברייתא זו: מה שנאמר \u0003ימי אהל מועד שבמדבר ארבעים חסר אחת, מנלן\u0004 \u0005[מנין לנו]?\u0006 שכן \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: ב\u0003שנה ראשונה\u0004 ליציאת בני ישראל ממצרים \u0003עשה משה את המשכן,\u0004 בשנה \u0003שניה הוקם המשכן ושלח משה מרגלים,\u0004 וכתוצאה מחטא המרגלים היו בני ישראל במדבר ארבעים שנה. הרי שימי המשכן במדבר היו ארבעים שנה חסר אחת.","ומה ששנינו בברייתא כי ימי אהל מועד \u0003שבגלגל\u0004 היתה \u0003ארבע עשרה\u0004 שנה, שהן \u0003שבע שכבשו ושבע שחלקו, מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דקאמר\u0004 \u0005[ש\u0006כן \u0005אמר]\u0006 \u0003כלב\u0004 בן יפונה ליהושע בתום תקופת הכיבוש, לפני חלוקת הארץ: \u0003\"בן ארבעים שנה אנכי בשלח משה עבד ה' אותי מקדש ברנע לרגל את הארץ ואשב אותו דבר כאשר עם לבבי\"\u0004 (יהושע יד, ז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך אותו מקרא \u0005:\u0006 \u0003\"ועתה הנה אנכי היום בן חמש ושמנים שנה\"\u0004 (יהושע יד, י).","\u0003כי עבריה\u0004 \u0005[כאשר עברו]\u0006 בני ישראל את ה\u0003ירדן בר\u0004 \u0005[בן]\u0006 \u0003כמה הוי\u0004 \u0005[היה]\u0006 כלב? \u0003בר שבעין ותמני\u0004 \u0005[בן שבעים ושמונה],\u0006 שהרי המרגלים נשלחו בשנה השניה לצאתם ממצרים, ובשנה הארבעים עברו את הירדן. \u0003וקאמר\u0004 \u0005[ואמר]\u0006 בזמן שהגיעו לחלוקת הארץ כי הוא \u0003בן חמש ושמונים שנה, הרי שבע\u0004 שנים \u0003שכבשו.\u0004","ושואלים: \u0003ושבע\u0004 שנים \u0003שחלקו מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 סברה היא: \u0003מ\u0004כיון שהיו \u0003שבע\u0004 שנים \u0003שכבשו, שבע נמי\u0004 \u0005[גם כן]\u0006 \u0003שחלקו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מדלא משכחת לה\u0004 \u0005[מ\u0006כיון \u0005שאינך מוצא]\u0006 הסבר לתאריך אותו מציין הנביא יחזקאל: \"בראש השנה בעשור לחודש \u0003בארבע עשרה שנה אחר אשר הכתה העיר\"\u0004 (יחזקאל מ, א), שממנו עולה כי שנה זאת היתה שנת היובל, אלא רק אם נאמר שזמן כיבוש וחלוקת הארץ יחד היה ארבע עשרה שנים, ומתום תקופה זו החלו למנות שנות שמיטה ויובל.","ועוד נאמר בברייתא שמשך תקופת \u0003אהל מועד שבנוב וגבעון\u0004 היתה \u0003חמשים ושבע\u0004 שנים. ומבררים: \u0003מנא לן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור מות עלי הכהן כאשר בישרו לו על נפילת הארון בידי הפלישתים\u0005:\u0006 \u0003\"ויהי כהזכירו את ארון האלהים\u0004 ויפול מעל הכסא אחורנית בעד יד השער ותשבר מפרקתו וימות\" (שמואל א ד, יח),","\u0003ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]:\u0006 \u0003כשמת עלי הכהן חרבה שילה, ובאו\u0004 ישראל \u0003לנוב\u0004 ושם הוקם המשכן. ובאותה שעה החל שמואל להנהיג את העם במקומו. \u0003כשמת שמואל הרמתי חרבה נוב\u0004 על ידי שאול (שמואל א כב, יט) \u0003ובאו לגבעון,\u0004 ושם היה המשכן (ראה דברי הימים א טז, לט).","\u0003ו\u0004כשאנו באים לבדוק כמה שנים עברו מאז נפל הארון ביד פלשתים (וחרבה שילה), הרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויהי מיום שבת הארון בקרית יערים\u0004 (מזמן שהחזירוהו פלשתים, שבעה חדשים לאחר ששבוהו) \u0003וירבו הימים ויהיו עשרים שנה וינהו כל בית ישראל אחרי ה'\"\u0004 (שמואל א ז, ב), הרי שהיה הארון בקרית יערים עשרים שנה, עד שהעלהו דוד לירושלים.","ויש לדון במנין השנים הללו, \u0003הני\u0004 \u0005[אלה]\u0006 \u0003עשרים שנה\u0004 כיצד מונים אותם? \u0003עשר שנה שמלך שמואל בעצמו\u0004 (לבדו), ממות עלי ועד שהמליך את שאול. \u0003ושנה שמלך שמואל ושאול,\u0004 כלומר, שמלך שאול בחייו של שמואל. \u0003ושתים שמלך שאול\u0004 בלבד לאחר שנפטר שמואל. \u0003ו\u0004על שלש עשרה שנים אלה יש להוסיף עוד את \u0003שבע\u0004 השנים שמלך \u0003דוד\u0004 בחברון, לפני שנות מלכותו בירושלים,"],["\u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והימים אשר מלך דוד על ישראל ארבעים שנה בחברון מלך שבע שנים\u0004 ובירושלים מלך שלשים ושלש שנים\" (מלכים א ב, יא), ובשנה שמלך בירושלים העלה את הארון מקרית יערים לירושלים. והרי אלו עשרים השנה ששהה הארון בקרית יערים. ועליהן יש להוסיף את שלשים ושלש שנות מלכות דוד בירושלים (מלכים א ב, יא). הרי אלו חמישים ושלש שנים מאז חורבן שילה, ובכל אלו השנים היה המשכן בנוב ואחר כך בגבעון, וגם בתחילת מלכות שלמה (ראה מלכים א ג, ד).","\u0003וב\u0004בניית המקדש בימי \u0003שלמה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויחל לבנותו ... בשנת ארבע למלכותו\"\u0004 (ראה דברי הימים ב ג, ב), ובאותה שנה מלאו ארבע מאות ושמונים שנה מיציאת מצרים (מלכים א ו, א). ואם נפחית מארבע מאות ושמונים שנה אלו את ארבעים שנות המדבר, וארבע עשרה שנות המשכן בגלגל (לפני משכן שילה), ואת חמישים ושבע שנות המשכן בנוב ובגבעון (לאחר משכן שילה), ובסך הכל מאה ואחת עשרה שנה, נמצא ש\u0003נשתיירו לשילה שלש מאות ושבעים חסר אחת.\u0004","שנינו במשנתנו כי משעה שחרבה שילה ו\u0003באו לנוב\u0004 \u0003ו\u0004לאחר מכן ל\u0003גבעון\u0004 הותרו הבמות, וקדשים קלים נאכלים בכל ערי ישראל. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 נאמר לבני ישראל כי כשייכנסו לארץ יהיו מותרים בהקרבה בבמות \u0003\"כי לא באתם עד עתה אל המנוחה ואל הנחלה\"\u0004 (דברים יב, ט), שאז יהיו אסורים בכך.","ופירושן של לשונות אלה: \u0003\"אל המנוחה\"\u0004 — \u0003זו שילה,\u0004 \"אל ה\u0003נחלה\"\u0004 — \u0003זו ירושלים.\u0004 ויש לשאול: \u0003למה חלקן\u0004 בשני ביטויים \"אל המנוחה\" ו\"אל הנחלה\"? \u0003כדי ליתן היתר\u0004 להקריב בבמות, בזמן ש\u0003בין זה לזה,\u0004 ומכאן להיתר הבמות בתקופת נוב וגבעון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: מעשר שני נמי ליתני\u0004 \u0005[גם כן שישנה]\u0006 התנא במשנתנו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003מעשר\u0004 שני, בגזירה שווה \u0003\"שם\" \"שם\"\u0004 \u0003מארון קא ילפי\u0004 \u0005[למדים],\u0006 שבמעשר שני נאמר \"ואכלתם שם\" (דברים יב, ז), ובארון נאמר: \"ושמת שם את ארון העדות\" (שמות מ, ג). \u0003כיון\u0004 ש\u0003ארון לא הוה\u0004 \u0005[היה]\u0006 בנוב ולא בגבעון אלא בקרית יערים, \u0003מעשר נמי לא הואי\u0004 \u0005[גם כן לא היה]\u0006 נאכל.","הקשה ריש לקיש: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שזהו המקור לדין זה, לגבי \u0003פסח ו\u0004שאר \u0003קדשים נמי,\u0004 שאין חולק שהיו נאכלים שם, \u0005[גם כן]\u0006 נאמר שגם הם, \u0003\"שם\" \"שם\" מארון ילפי\u0004 \u0005[למדים],\u0006 ו\u0003כיון\u0004 ש\u0003ארון לא הוה\u0004 \u0005[היה]\u0006 בנוב ובגבעון \u0003אינהו נמי לא הוו\u0004 \u0005[הם גם כן לא היו]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אלא \u0003דאמר לך הא\u0004 \u0005[\u0006החכם \u0005שאומר לך\u0006 דבר \u0005זה],\u0006 כלומר, משנתנו, ממנה דייקת שמעשר שני אינו נאכל אף בנוב וגבעון, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: אף צבור לא הקריבו\u0004 בבמה גדולה, כגון נוב וגבעון, \u0003אלא פסח וחובות הקבוע להן זמן, אבל חובות שאין קבוע להם זמן הכא והכא\u0004 \u0005[כאן וכאן],\u0006 גם בבמה קטנה וגם בבמה גדולה \u0003לא קרב\u0004 \u0005[קרבו].\u0006 ובכלל זה \u0003מעשר בהמה,\u0004 ש\u0003חובות שאין קבוע להן זמן הוא. ו\u0004הרי \u0003איתקש\u0004 \u0005[והוקש]\u0006 \u0003מעשר דגן למעשר בהמה,\u0004 ומכיון שמעשר בהמה אינו קרב באותה שעה, אף מעשר שני אינו נאכל שם.","ושואלים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004 הסבור שגם חובות שלא קבוע להם זמן קרבו בבמה גדולה, \u0003קרב\u0004 מעשר שני ומעשר בהמה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דהאמר\u0004 \u0005[שהרי אמר]\u0006 \u0003רב אדא בר מתנה: מעשר שני ומעשר בהמה נאכלין בנוב וגבעון לדברי ר' יהודה.\u0004 ושואלים: \u0003והא בעי\u0004 \u0005[והרי צריך]\u0006 \u0003בירה,\u0004 כלומר, צריך בית מקדש, ולא רק אוהל, שאליו באים לאכילת המעשר! משיבים: \u0003ולאו תני\u0004 \u0005[ו\u0006כי \u0005לא שנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו שנאמר בה: \u0003שלש בירות הן: שילה, ונוב וגבעון, ובית עולמים? הוא תני לה\u0004 \u0005[שנה אותה]\u0006 \u0003והוא אמר לה\u0004 \u0005[פירש אותה]:\u0006 מדובר שם \u0003ל\u0004ענין \u0003אכילת מעשר שני, ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יהודה.\u0004","שנינו במשנתנו כי משעה ש\u0003באו לירושלים\u0004 נאסרו הבמות, ולא היה להם עוד היתר, והיא היתה \"נחלה\". ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 נאמר בהיתר הבמות \u0003\"כי לא באתם עד עתה אל המנוחה ואל הנחלה\"\u0004 (דברים יב, ט), ופירושם של לשונות אלה: \u0003\"מנוחה\"\u0004 — \u0003זו שילה, \"נחלה\"\u0004 — \u0003זו ירושלים.\u0004","\u0003ו\u0004כן \u0003אומר\u0004 הכתוב בנבואה על ירושלים: \"עזבתי את ביתי נטשתי את נחלתי... \u0003היתה לי נחלתי כאריה ביער\"\u0004 (ירמיהו יב, ז — ח), \u0003ו\u0004עוד שם בדברי הנבואה על ירושלים \u0003אומר\u0004 הכתוב: \u0003\"העיט צבוע נחלתי לי העיט סביב עליה\"\u0004 (ירמיהו יב, ט), אלו \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' שמעון אומר: \"מנוחה\"\u0004 — \u0003זו ירושלים, \"נחלה\"\u0004 — \u0003זו שילה, ו\u0004ראיה לדבר, שכן הכתוב \u0003אומר\u0004 על ירושלים: \u0003\"זאת מנוחתי עדי עד פה אשב כי אויתיה\"\u0004 (תהלים קלב, יד), \u0003ו\u0004מנין שהכתוב מדבר בירושלים — שכן הוא \u0003אומר\u0004 בפסוק הקודם: \u0003\"כי בחר ה' בציון אוה למושב לו\"\u0004 (תהלים קלב, יג).","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר,\u0006 ר' יהודה\u0005]:\u0006 \u0003\"מנוחה\"\u0004 \u0003זו שילה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"אל המנוחה ואל הנחלה\",\u0004 כסדר הזמנים, שהרי קדמה שילה לירושלים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 ר' שמעון\u0005]\u0006 ש\u0003\"מנוחה\"\u0004 — \u0003זו ירושלים, \"נחלה\"\u0004 — \u0003זו שילה,\u0004 אם כן \u0003\"אל הנחלה ואל המנוחה\" מיבעי ליה\u0004 \u0005[צריך הוא\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 הכתוב: כשתיכנסו לארץ עדיין מותרים אתם בבמות, משום ש\u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאל ה\u0003\"מנוחה\",\u0004 שהיא המקדש בירושלים, עדיין \u0003לא מטיתו\u0004 \u0005[הגעתם],\u0006 \u0003אלא אפילו ל\"נחלה\",\u0004 שהיא המשכן בשילה, \u0003נמי\u0004 \u0005[גם כן]\u0006 עדיין \u0003לא מטיתו\u0004 \u0005[הגעתם].\u0006","ובענין זה של \"מנוחה\" ו\"נחלה\" האמורות בכתוב \"כי לא באתם עד עתה אל המנוחה ואל הנחלה\" (דברים יב, ט). שנינו עוד דעות תנאים, שכן \u0003תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל: זו וזו,\u0004 הן \"מנוחה\" והן \"נחלה\", הריהן כינויים ל\u0003שילה.\u0004 ואילו \u0003ר' שמעון בן יוחי אומר:\u0004 \u0003זו וזו\u0004 הריהן כינויים ל\u0003ירושלים.\u0004 ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר,\u0006 ר' יהודה\u0005]\u0006 ש\u0003\"מנוחה\"\u0004 — \u0003זו\u0004"],["\u0003שילה,\u0004 ו\u0003\"נחלה\" זו ירושלים, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003איפכא\u0004 \u0005[היפך]\u0006 הדברים, כלומר, ש\"מנוחה\" זו ירושלים ו\"נחלה\" זו שילה — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בכתוב זה בשתי לשונות נפרדות \u0003\"אל המנוחה\" \"ואל הנחלה\".\u0004 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 חכם בית המדרש של ר' ישמעאל\u0005]:\u0006 ש\u0003זו וזו\u0004 הכוונה היא ל\u0003שילה, או\u0004 לשיטת ר' שמעון בן יוחאי ש\u0003זו וזו\u0004 הכוונה ל\u0003ירושלים,\u0004 אם כן \"כי לא באתם עד עתה אל ה\u0003מנוחה\u0004 וה\u0003נחלה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ושואלים עוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר,\u0006 ר' שמעון בן יוחאי\u0005]:\u0006 ש\u0003זו וזו\u0004 הן כינויים ל\u0003שילה,\u0004 אפשר להסביר כך את הכינויים הללו: \u0003\"מנוחה\"\u0004 — ש\u0003נחו\u0004 בתקופת שילה \u0003מ\u0004ה\u0003כיבוש\u0004 שבימי יהושע. \u0003\"נחלה\"\u0004 — \u0003דפלגו התם\u0004 \u0005[שחלקו שם]\u0006 לשבטים את \u0003נחלות\u0004 ארץ ישראל, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויחלק להם יהושע ויפל להם גורל בשילה על פי ה'\"\u0004 (יהושע יח, י: \"וישלך להם יהושע גורל בשילה לפני ה' ויחלק שם יהושע את הארץ לבני ישראל כמחלקותם\").","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 חכם בית המדרש של ר' ישמעאל\u0005]:\u0006 ש\u0003זו וזו\u0004 הריהן כינויים ל\u0003ירושלים, בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"נחלה\"\u0004 הריהי כינוי לירושלים — משום שהיא \u0003נחלת עולמים, אלא \"מנוחה\"\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 איזו\u0005]\u0006 \u0003מנוחה\u0004 היתה במקדש בירושלים? ומשיבים: \u0003מנוחת ארון, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויהי כנוח הארון\",\u0004 שבכתובים נקרא המקדש שבירושלים מקום מנוחה לארון.","ושואלים עוד, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר,\u0006 ר' שמעון בן יוחאי\u0005]:\u0006 ש\u0003זו וזו\u0004 הריהן כינויים ל\u0003ירושלים,\u0004 ומכאן שהבמות מותרות כל עוד לא הוקם המקדש בירושלים, \u0003אבל\u0004 בזמן משכן \u0003שילה הוה שריא\u0004 \u0005[היו מותרות]\u0006 \u0003במות\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בתקופת שילה, לגבי מנוח אבי שמשון: \u0003\"ויקח מנוח את גדי העזים ואת המנחה ויעל על הצור לה'\"\u0004 (שופטים יג, יט), שהקריב בבמת יחיד, ולא בשילה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 חכם בית המדרש של ר' ישמעאל\u0005]\u0006 ש\u0003זו וזו\u0004 הריהן כינויים למשכן \u0003שילה, ובמות הוה אסירן\u0004 \u0005[היו אסורות]\u0006 בתקופת משכן שילה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ויקח מנוח\"?\u0004 והרי אסור היה לו להקריב קרבן מחוץ למשכן! ומשיבים: \u0003הוראת שעה היתה\u0004 זו להתיר הקרבה זו.","ומעירים כי בענין שיטות התנאים בפירוש \"מנוחה\" ו\"נחלה\" שבכתוב זה, \u0003תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל\u0004 גירסה אחרת, שהיא \u0003כ\u0004דעת \u0003ר' שמעון בן יוחי,\u0004 ש\u0003אמר: זו וזו ירושלים. וסימניך\u0004 כדי לזכור את הענין: \u0003משכי גברא לגברי\u0004 \u0005[משך איש את האנשים],\u0006 כלומר, ר' שמעון בן יוחאי שהוא יחיד, משך בדעתו את חכמי בית מדרשו של ר' ישמעאל שהם רבים.","שנינו במשנתנו כי \u0003כל הקדשים\u0004 שהקדישם בזמן היתר במות, והקריבם בחוץ בשעת איסור במות — עבר בכך על מצוות עשה ועל מצוות לא תעשה, ואין חייב על כך כרת. ודבר זה למדנו מדיוק הכתובים בפרשת שחוטי חוץ. ובענין זה \u0003אמר רב כהנא: לא שנו\u0004 שאין חייב כרת, \u0003אלא בשחיטה\u0004 של אלו בחוץ, \u0003אבל בהעלאה\u0004 — \u0003כרת נמי מיחייב\u0004 \u0005[גם כן חייב],\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן מיד לאחר הפסוקים מהם למדנו דין זה של קרבן שהקדיש בשעת היתר במות, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 עונש כרת על העלאה בחוץ, ופתח במלים: \u0003\"ואלהם תאמר\"\u0004 (ויקרא יז, ח), ומשמע הדברים: \u0003על\u0004 הדינים \u0003הסמוכין,\u0004 שהוזכרו קודם לכן \u0003תאמר,\u0004 שאף שאין עונש כרת בשחיטתם, יש עונש כרת בהעלאתם בבמה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה: מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ועליהם תאמר\"\u0004 הקרבנות שהוזכרו בפסוק הסמוך? והלוא \u0003\"אלהם\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003ו\"אליהם\"\u0004 גם כן \u0003קרינן\u0004 \u0005[קוראים אנו],\u0006 ומשמע אל האמורים בראש הפרשה (\"דבר אל אהרן ואל בניו ואל כל בני ישראל\", ויקרא יז, ב)!","\u0003ועוד\u0004 מוסיפים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 מפורשת שלא כדברי רב כהנא: \u0003ארבעה כללות היה ר' שמעון אומר בקדשים:\u0004 קדשים ש\u0003הקדישן בשעת איסור הבמות, ושחט והעלה בשעת איסור הבמות בחוץ\u0004 — \u0003הרי הן\u0004 \u0003ב\u0004איסור \u0003עשה ולא תעשה, ויש בהן\u0004 עונש \u0003כרת. הקדישן בשעת היתר הבמות, ושחט והעלה בשעת איסור הבמות\u0004 — \u0003הרי הן בעשה ולא תעשה,\u0004 אבל \u0003אין בהן כרת.\u0004","\u0003הקדישן בשעת איסור הבמות, ושחט והעלה בחוץ\u0004 \u0003בשעת היתר הבמות\u0004 — \u0003הרי הן בעשה, ואין בהן בלא תעשה.\u0004","\u0003הקדישן בשעת היתר הבמות, ושחט והעלה בשעת היתר הבמות\u0004 — הריהו \u0003פטור מכלום.\u0004 הרי איפוא נשנה במפורש שאין הבדל בין דין שחיטה ודין העלאה בבמות, ובשתיהם פטור מכרת אם הקדיש את הקדשים בשעת היתר הבמות ושחט או העלה אותם בשעת איסור הבמות. והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב כהנא\u0004 שהבדיל בין שחיטה והעלאה! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו.","שנינו במשנתנו: \u0003ואלו קדשים [וכו'].\u0004 והמשנה הולכת ומפרטת רשימה של דברים שנהגו דווקא בבמת ציבור, שם היה המשכן, ולא בבמת יחיד. ומעתה מבררים מהיכן למדנו כי דברים אלה נוהגים דווקא שם: \u0003סמיכה\u0004 של הבעלים על ראש הקרבן — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"אל פתח אהל מועד יקריב אותו לרצונו \u0003לפני ה'. וסמך\u0004 ידו...\"(ויקרא א, ג—ד).","\u0003שחיטת צפון\u0004 בקדשי קדשים — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ושחט אותו על ירך המזבח \u0003צפונה לפני ה'\"\u0004 (ויקרא א, יא). דין \u0003מתנות סביב\u0004 על ארבעת צידי המזבח, בקרבן עולה ועוד — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וזרק\u0004ו את הדם \u0003על המזבח סביב\u0004 (סביב) אשר פתח אהל מועד\" (ויקרא א, ה).","\u0003תנופה\u0004 בקרבנות הטעונים הנפה — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והניף הכהן לפני ה'\"\u0004 (ראה ויקרא יד, יב: \"ולקח הכהן... והניף אותם תנופה לפני ה'\"). \u0003הגשה\u0004 של המנחות לקרן המזבח קודם קמיצה — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והגישה אל המזבח\"\u0004 (ויקרא ב, ח).","ובענין זה של מנחה, שנינו במשנה: \u0003ר' יהודה אומר: אין\u0004 כלל \u0003מנחה בבמה,\u0004 ואף לא בבמה גדולה (במשכן גלגל, נוב וגבעון). ועל כך \u0003אמר רב ששת: לדברי האומר יש מנחה בבמה, יש\u0004 גם קרבן \u0003עופות בבמה.\u0004 ואילו \u0003לדברי האומר\u0004 ש\u0003אין מנחה בבמה, אין\u0004 גם \u0003עופות בבמה.\u0004","וטעם הדבר, שכן נאמר בענין הקרבנות שהוקרבו בשעת היתר הבמות: \u0003\"זבחים\"\u0004 (\"וזבחו זבחי שלמים\" ויקרא יז, ה), והלשון \"זבחים\" יש בה הדגשה: \u0003\"זבחים\"\u0004 — \u0003ולא מנחות, \"זבחים\"\u0004 — \u0003ולא עופות,\u0004 להורות שלא הותרו אלה אף בבמה גדולה. ושבים לפרט את ההבדלים הנזכרים במשנתנו שבין במת יחיד לבמת ציבור.","\u0003וכהן\u0004 צריך דווקא בבמת ציבור — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וזרק הכהן\u0004 את הדם על מזבח ה' פתח אהל מועד\" (ויקרא יז, ו). \u0003בגדי שרת\u0004 נצרכים דווקא בבמת ציבור — שכן נאמר בהם: \"והיו על אהרן ועל בניו בבואם אל אהל מועד או בגשתם אל המזבח \u0003לשרת בקדש\"\u0004 (שמות כח, מג).","\u0003וכלי שרת\u0004 — שנאמר בהם: \"ולקחו את כל כלי השרת \u0003אשר ישרתו בם בקדש\"\u0004 (במדבר ד, יב). ומה ששנינו שדווקא בבמת ציבור צריכה ההקרבה להיות \u0003לריח ניחוח,\u0004 שאין להעלות על המזבח איברים שנצלו תחילה מחוץ למערכה שעל המזבח — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת איסור הקרבה בחוץ: \"והקטיר החלב \u0003לריח ניחח לה'\"\u0004 (ויקרא יז, ו).","ומה ששנינו שדווקא בבמת ציבור יש \u0003מחיצה בדמים,\u0004 שחוצים את גובה המזבח על ידי חוט הסיקרא, חציו לדמים הניתנים למעלה (דם חטאת), וחציו לדמים הניתנים למטה (דם עולה), טעם הדבר — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והיתה הרשת עד חצי המזבח\"\u0004 (שמות כז, ה), בה\"א הידיעה — דווקא המזבח שבמשכן. חובת \u0003ריחוץ ידים\u0004 ורגלים קודם עבודה לא היתה אלא בבמת ציבור — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין זה: \"בבואם אל אהל מועד \u0003ובקרבתם אל המזבח ירחצו\"\u0004 (שמות מ, לב).","ובדין חיצוי בדמים ושאר דינים שלא נהגו בבמת יחיד אלא בבמת ציבור, \u0003אמר רמי בר חמא: לא שנו\u0004 שאין חיצוי \u0003אלא בקדשי במה קטנה\u0004 שהקדישום \u0003והקריבום בבמה קטנה, אבל בקדשי במה קטנה\u0004 שהקדישם \u0003דקרבינהו\u0004 \u0005[שהקריב אותם]\u0006 \u0003בבמה גדולה\u0004 (במת ציבור) — \u0003יש חיצוי.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבה\u0004 ממה ששנינו בברייתא: תנופת \u0003חזה ושוק\u0004 של שלמים, וכן \u0003תרומת לחמי תודה, נוהגין בקדשי במה גדולה ואין נוהגין בקדשי במה קטנה,\u0004 ומשמע — אפילו הקריבם בבמה גדולה! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך את גירסת הדברים: חזה ושוק ותרומת לחמי תודה \u0003נוהגין בבמה גדולה\u0004 (ואפילו בקדשי במה קטנה) \u0003ואין נוהגין בבמה קטנה.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 שכך \u0003אמר רמי בר חמא: לא שנו\u0004 שיש חיצוי בדמים, \u0003אלא בקדשי במה גדולה והקריבן בבמה גדולה, אבל בקדשי במה קטנה, אף על גב דקרבינהו\u0004 \u0005[אף על פי שהקריב אותם]\u0006 \u0003בבמה גדולה —\u0004 \u0003אין חיצוי.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לסייע לו]\u0006 ממה ששנינו בברייתא: \u0003חזה ושוק ותרומת לחמי תודה נוהגין בקדשי במה גדולה ואין נוהגין בקדשי במה קטנה?\u0004","ומשיבים: אין להביא ראיה מכאן, שכן \u0003אימא\u0004 \u0005[אמור]\u0006 שכך יש להסביר: חזה ושוק ותרומת לחמי תודה \u0003נוהגין בבמה גדולה\u0004 (ואפילו בקדשי במה קטנה) \u0003ואין נוהגין בבמה קטנה.\u0004 ומעירים, \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 לשון זו של רמי בר חמא על שיטת \u0003ר' אלעזר,\u0004 שכך \u0003אמר ר' אלעזר: עולת במת יחיד שהכניסה בפנים\u0004 לתחום הבמה הגדולה — \u0003קלטוה מחיצות לכל דבר\u0004 ולכל הדינים.","ובענין זה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: עולת במת יחיד\u0004"],["\u0003שהכניסה לפנים,\u0004 \u0003ו\u0004חזר ו\u0003הוציאה לחוץ, מהו\u0004 דינה לענין שינהגו בה מעתה כדין קדשי במה גדולה? וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דעיילא\u0004 \u0005[שנכנסה]\u0006 כבר \u0003קלטה לה מחיצתא\u0004 \u0005[קלטה אותה המחיצה],\u0006 ומעתה נוהגים בה כל דיני במה גדולה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 אומרים אנו: \u0003כיון דהדר הדר\u0004 \u0005[שחזרה\u0006 לחוץ \u0005חזרה],\u0006 לדיני במת יחיד.","ושואלים: \u0003לאו היינו פלוגתא\u0004 \u0005[האם אין זו המחלוקת]\u0006 של \u0003רבה ורב יוסף? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנה בראש מסכת מעילה: \u0003קדשי קדשים,\u0004 כגון חטאת ואשם, \u0003ששחטן\u0004 שלא כהלכתם בצפון העזרה, אלא \u0003בדרום\u0004, ונפסלו בכך — \u0003מועלין\u0004 (יש דין מעילה) \u0003בהן, ו\u0004כן למרות שאין מעלים אותם על המזבח, \u0003אם\u0004 קרה ו\u0003עלו\u0004 למזבח — \u0003לא ירדו.\u0004","\u0003ואיבעיא להו\u0004 \u0005[ונשאלה להם,\u0006 ללומדים\u0005]:\u0006 אם \u0003ירדו\u0004 מן המזבח \u0003מהו ש\u0004יחזרו ו\u0003יעלו? רבה אמר: לא יעלו, ורב יוסף אמר: יעלו.\u0004 הרי שבשאלה זו עצמה נחלקו, האם דבר שאינו ראוי להקרבה בתחום קדושה מסויימת, חלים עליו דיני אותה קדושה, אף שיצא מגבולותיה!","ודוחים: אין זו בהכרח אותה מחלוקת, שכן עדיין יש מקום ש\u0003תיבעי\u0004 \u0005[תישאל]\u0006 שאלה זו \u0003ל\u0004דעת \u0003רבה,\u0004 ויש מקום ש\u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003רב יוסף.\u0004 ומפרטים: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003רבה,\u0004 שכן \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאומר]\u0006 \u0003רבה\u0004 שקדשי קדשים ששחטם בדרום, שאם עלו וירדו — שוב לא יעלו, \u0003אלא\u0004 דווקא \u0003במזבח,\u0004 משום שהמזבח מתחילתו, \u0003דחזי ליה\u0004 \u0005[\u0006מה \u0005שראוי לו]\u0006 הוא \u0003מקדש,\u0004 ומה ש\u0003לא חזי\u0004 \u0005[ראוי]\u0006 לו, הוא \u0003לא מקדש. אבל מחיצה\u0004 של במת ציבור אינה כמזבח לענין זה, שהרי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שהקרבן שהוקדש לבמת היחיד הוא בגדר ש\u0003לא חזי ליה\u0004 \u0005[ראוי לה],\u0006 בכל זאת — \u0003קלטה\u0004 \u0005[קולטת]\u0006 אותו, והוא קרב שם, ולכן חלים עליו דיניה גם אם יצא משם.","\u0003או\u0004 להיפך, \u0003דלמא\u0004 \u0005[שמא]\u0006 בעיה זו בענין עולת במת יחיד הריהי נשאלת \u0003אפילו לרב יוסף,\u0004 שכן \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[שאומר]\u0006 \u0003רב יוסף התם\u0004 \u0005[שם],\u0006 לענין קדשי קדשים ששחטם בדרום, שאף אם ירדו מהמזבח חוזרים ומעלים אותם, \u0003אלא\u0004 משום \u0003דחד מקום\u0004 \u0005[שמקום אחד]\u0006 \u0003הוא,\u0004 שהמזבח והבשר שהורד ממנו מצויים שניהם בעזרה, \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בשאלת ר' זירא\u0005]\u0006 \u0003דתרי\u0004 \u0005[ששני]\u0006 \u0003מקומות\u0004 נפרדים \u0003נינהו\u0004 \u0005[הם],\u0006 במת היחיד ומקום הבמה גדולה — \u0003לא\u0004 ינהגו בה דיני במה גדולה אם חזרה ויצאה לחוץ. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 וכשיטות רבה ורב יוסף בזה כן שיטותיהם בזה\u0005?\u0006 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ואומרים: \u0003מילתא דפשיטא ליה\u0004 \u0005[דבר שפשוט לו]\u0006 \u0003לרבה בחד גיסא\u0004 \u0005[בצד אחד],\u0006 שלא יחזרו ויעלו למזבח, \u0003ולרב יוסף בחד גיסא\u0004 \u0005[בצד אחר],\u0006 שיחזרו ויעלו למזבח, \u0003מיבעי ליה\u0004 \u0005[היה מסופק לו]\u0006 \u0003לר' ינאי, דבעי\u0004 \u0005[ש\u0006כן \u0005שאל]\u0006 \u0003ר' ינאי: אברי עולת במת יחיד שעלו למזבח וירדו, מהו\u0004 דינם? ומעירים: \u0003היכא\u0004 \u0005[במקום]\u0006 שעדיין \u0003לא משלה בהן\u0004 \u0003האור\u0004 שלא אחזה האש באיברי העולה, \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שבוודאי אינם חוזרים ועולים, \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003משלה בהן האור, מאי\u0004 \u0005[מה]\u0006 דינה? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בדיני במת יחיד, \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שחיטת\u0004 קדשים ב\u0003לילה בבמת יחיד\u0004 מה דינה? \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כשרה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פסולה.\u0004 \u0003ו\u0004מסבירים: \u0003קא מיפלגי\u0004 \u0005[חלוקים הם]\u0006 \u0003ב\u0004אופן התירוץ לסתירה שהראה \u0003ר' אלעזר,\u0004 שכן","\u0003ר' אלעזר רמי קראי אהדדי\u0004 \u0005[השליך,\u0006 הראה סתירה בין שני \u0005מקראות זה על זה],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בתוך סיפור מלחמת שאול בפלשתים: \"ויעט העם אל השלל ויקחו צאן ובקר ובני בקר וישחטו ארצה ויאכל העם על הדם. ויגידו לשאול לאמר הנה העם חוטאים לה' לאכול על הדם \u0003ויאמר בגדתם גלו אלי היום אבן גדולה\"\u0004 (שמואל א יד, לב — לג), ועשאה במה כדי לשחוט ולהקריב עליה. הרי שהקפיד שאול שהשחיטה תיעשה ביום ולא בלילה (\"גולו אלי היום\"), אף שהיה הדבר בבמת יחיד ולא בבמת ציבור (שהרי בתוך כדי מלחמה היו).","\u0003ו\u0004אולם \u0003כתיב\u0004 \u0005[נאמר]\u0006 מיד לאחר מכן: \u0003\"ויאמר שאול פצו בעם ואמרתם להם הגישו אלי איש שורו ואיש שיהו ושחטתם בזה ואכלתם ולא תחטאו לה' לאכול על הדם ויגשו כל העם איש שורו בידו הלילה וישחטו שם\".\u0004 (שם לד), הרי שהשחיטה נעשתה בלילה, ולא ביום!","וביישוב סתירה זו נחלקו רב ושמואל, \u0003מר משני\u0004 \u0005[חכם זה\u0006 \u0005מתרץ]:\u0006 \u0003כאן\u0004 ששחטו בלילה, מדובר \u0003בחולין,\u0004 \u0003כאן\u0004 שהקפיד שאול שלא ישחטו בלילה, מדובר \u0003בקדשים,\u0004 ונמצא שלדעת חכם זה אף בבמת יחיד אין עבודה אלא ביום. ואילו \u0003מר משני\u0004 \u0005[וחכם זה\u0006 \u0005מתרץ]:\u0006 שני המקראות עוסקים בשחיטת קדשים, אלא ש\u0003כאן\u0004 שהקפיד שאול על שחיטה ביום — מדובר \u0003בקדשי במה גדולה,\u0004 \u0003כאן\u0004 ששחטו בלילה, מדובר \u0003בקדשי במה קטנה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדין \u0003עולת במת יחיד, רב אמר: אין טעונה הפשט\u0004 עורה \u0003וניתוח\u0004 איבריה, כדין מעשה עולה הכתוב בתורה (ויקרא א, ו), \u0003ור' יוחנן אמר: טעונה הפשט וניתוח. ו\u0004מסבירים: \u0003קא מיפלגי\u0004 \u0005[\u0006הרי \u0005הם חלוקים]\u0006 \u0003ב\u0004כוונת דברי \u0003ר' יוסי הגלילי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: עולה שהקריבו ישראל במדבר,\u0004 בהר סיני, קודם שהוקם המשכן — \u0003אין טעונה\u0004 \u0003הפשט וניתוח,\u0004 לפי \u0003שאין\u0004 דין \u0003הפשט וניתוח\u0004 בעולה נוהג \u0003אלא מאהל מועד ואילך,\u0004 שהרי רק באהל מועד נאמר דין זה (ויקרא א, ו).","ובכך נחלקו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]:\u0006 \u0003מאהל מועד ואילך\u0004 חייבים בהפשט וניתוח, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה ב\u0003במה גדולה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה זה ב\u0003במה קטנה. ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003בבמה גדולה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נוהג דין זה, ואילו \u0003בבמה קטנה\u0004 — \u0003לא\u0004 נוהג.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 שכך שנינו: מהם ה\u0003דברים\u0004 \u0003שבין במה גדולה לבמה קטנה?\u0004 יש חיוב שיהיו \u0003קרן וכבש ויסוד וריבוע ב\u0004מזבח של \u0003במה גדולה, ואין קרן ויסוד וכבש וריבוע בבמה קטנה; כיור וכנו בבמה גדולה, ואין כיור וכנו בבמה קטנה;\u0004 תנופת \u0003חזה ושוק\u0004 של שלמים הניתנים לכהן. \u0003בבמה גדולה, ואין חזה ושוק בבמה קטנה.\u0004","ואולם יש \u0003דברים\u0004 אחרים \u0003ששוותה במה גדולה לבמה קטנה: שחיטה\u0004 נוהגת הן \u0003בבמה גדולה ו\u0004הן בבמה \u0003קטנה; הפשט וניתוח\u0004 של עולה נוהגים הן \u0003ב\u0004במה \u0003גדולה ו\u0004הן בבמה \u0003קטנה;\u0004 זריקת \u0003דם\u0004 הקרבנות שהוא \u0003מתיר\u0004 את הבשר לאכילה, \u0003ומפגל\u0004 (שאם חשב הכהן מחשבת אכילה או הקרבה חוץ לזמנו בשעת עבודת הדם הרי זה מפגל את הקרבן) — נוהגים הן \u0003ב\u0004במה \u0003גדולה ו\u0004הן בבמה \u0003קטנה;\u0004 וכן דין ה\u0003מומין\u0004 הפוסלים את הקרבן מהקרבה, \u0003ו\u0004דין \u0003זמן\u0004 מוגבל לאכילת הקרבנות, נוהגים הן \u0003ב\u0004במה \u0003גדולה ו\u0004הן בבמה \u0003קטנה.\u0004","ועוד שנינו במשנתנו לאחר שנמנו ההבדלים שבין במת ציבור לבמת יחיד: \u0003אבל\u0004 דין ה\u0003נותר\u0004 מהקרבן לאחר זמנו, שטעון שריפה, והאוכלו חייב כרת. \u0003ו\u0004דין \u0003הזמן\u0004 מחשבת חוץ לזמנו, שמפגלת את הקרבן, \u0003ו\u0004דין \u0003הטמא\u0004 שפסול לעבודה ואסור באכילת הקרבנות, \u0003שוין\u0004 שנוהגים \u0003בזה ובזה.\u0004","ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מנין לעשות זמן בבמה קטנה\u0004 שיהא הקרבן נפסל אם נותר לאחר זמן אכילתו, \u0003כ\u0004דינו ב\u0003במה גדולה? אמרה תורה:\u0004 \u0003לן,\u0004 כלומר, נותר, דינו ש\u0003ישרף, ו\u0004כן גם ה\u0003פיגול\u0004 (שחשב עליו הכהן בשעת עבודה לאוכלו חוץ לזמנו) אמרה התורה ש\u0003ישרף,\u0004 ומעתה יש עוד להשוות ביניהם, ולומר: \u0003מה פיגול פסול בבמה\u0004 של יחיד, \u0003אף\u0004 ה\u0003לן\u0004 (נותר) \u0003פסול בבמה\u0004 של יחיד.","\u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו,\u0004 ואמור כך: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמרה תורה\u0004 בדין הקדשים במקדש: \u0003לן ישרף, ו\u0004גם \u0003יוצא\u0004 אל מחוץ לעזרה, אמרה תורה ש\u0003ישרף.\u0004 ומעתה, \u0003מה יוצא כשר בבמה\u0004 של יחיד, שהרי אין לה תחום מוגדר — \u0003אף\u0004 ה\u0003לן\u0004 הריהו \u0003כשר בבמה,\u0004 ונסיק איפוא שאין דין זמן בבמת יחיד. ומשיבים: \u0003ולאו\u0004 \u0005[\u0006וכי \u0005לא]\u0006 \u0003קל וחומר הוא, מ\u0004דינם של קרבנות ה\u0003עופות,\u0004 שהזמן פוסל בבמת יחיד?"],["\u0003מה עופות\u0004 הקלים בדינם, \u0003שאין המום פוסל בהן,\u0004 בכל זאת \u0003זמן פוסל בהן,\u0004 \u0003קדשי במה קטנה שהמום פוסל בהן, אינו דין שזמן פוסל בהן?\u0004","ויש לדחות קל וחומר זה: \u0003מה לעופות\u0004 שיש בהם צד חומרה, \u0003שכן אין הזר כשר בהן\u0004 בהקרבתן, \u0003תאמר בבמה קטנה שהזר כשר בה,\u0004 ולכן \u0003לא יהא זמן פסול בה! תלמוד לומר: \"וזאת תורת זבח השלמים\"\u0004 (ויקרא ז, יא) להשוות את כל השלמים זה לזה — \u0003לעשות\u0004 (לקיים) דין \u0003זמן\u0004 ב\u0003במה קטנה\u0004 שיהא נוהג \u0003כ\u0004דין \u0003זמן\u0004 של \u0003במה גדולה.\u0004",""]]};
